window.__D("text/maamarei-admur-hazaken/c005",{"p":[[2100490471,"<h3>וירא ישראל את היד הגדולה</h3>\n<b>שביעי של פסח בעזר\"ה</b>\n<b>וירא</b><sup data-n=\"2661\">1</sup> ישראל<sup data-n=\"2662\">2</sup> את היד הגדולה אשר עשה הוי' במצרים ויראו העם את ה' ויאמינו בה' ובמשה עבדו. להבין למה הקדים בחי' יראה לבחי' אמונה אחר שהי' להם יראה שהוא בחי' התגלות איך יתכן שאח\"כ באו לבחי' אמונה שלמעלה מן ההשגה והשכל כו'. אך הנה כתיב ויקרא<sup data-n=\"2663\">3</sup> הוי' הוי' אל רחום כו' ויש להבין מה זה שכפל ב\"פ הוי' כו' להיות שיש ב'<sup data-n=\"2664\">4</sup> מדריגו' בשם הוי' הא' הנק' על שם ההתהוו'<sup data-n=\"2665\">5</sup> של כל העולמו' מאין ליש לכך נק' בשם זה הוי' לפי שהוא מהווה אותם מאין ליש תמיד ותחלה יש להבין ענין ההתהוו' מאין ליש ואח\"כ יש להבין מה שהוא ע\"י ד' אותיו' הללו דוקא דשם הוי' יו\"ד ה\"א כו'.\n<b>הנה</b> לכאורה אינו מובן איך שייך ענין התהוו' דבר מה שיקרא בבחי' נפרד חוץ מאלקי' חיים והלא ממך<sup data-n=\"2666\">6</sup> הכל כתיב ואין לך דבר חוץ ממנו וגם אחר שנברא הבריא' אין שינוי מכמו קודם הבריא' כמ\"ש אני<sup data-n=\"2667\">7</sup> ה' לא שניתי כו'. אך הענין הוא משום דבאמת אין ערך כלל בין בורא עם הנברא מאחר שהבורא הוא בחי' א\"ס בלתי מוגבל והנבראי' הם בבחי' הגבול ואין ערוך כלל וכלל בין ב\"ג לבלתי ב\"ג ע\"כ כשהי' צריך שיתהווה מציאו' ב\"ג מבלתי ב\"ג א\"א הי' בדרך עילה ועלול כשאר השתלשלו' אלא ע\"י צמצום האור של אלקו' בתחלה והוא בחי' היו\"ד<sup data-n=\"2668\">8</sup> דשם הוי' שהוא רק נקוד' א' כלומר בחי' הצמצום להעלים כל עצמותו מכל וכל כו' עד\"מ הידוע מהשפעת שפע שכל מרב לתלמידו שצריך הרב לצמצם בתחלה כל עצמו' השכלתו באותו השכל ולא ישאר רק כקוצו של יו\"ד כו' ואח\"כ בא השפע בבחי' ההתפשטו' אורך ורוחב כדי הצורך לההשפעה כו' ואח\"כ הוי\"ו הוא ההשפעה עצמה שהוא הנק' בשם המשכה מלמעלה למטה ואח\"כ הה\"א אחרונ' הוא תפיס' וקליט' ההשפעה במקבל לאורך ורוחב כו' וכמ\"ש<sup data-n=\"2669\">*8</sup> במ\"א וע\"י דוגמא מזה יובן למשכיל למעלה שכדי שיתהוו' מציא' ב\"ג מבלתי ב\"ג הוצרך להיו' ע\"י יו\"ד בתחלה והוא הצמצום לגמרי עד שלא",[["2661","1","<b>וירא ישראל את היד הגדולה</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק (1025 כט, ב).\nהנחת המהרי\"ל נדפס בתו\"א בשלח סא, ד. ונמצא בכת\"י 1135 סח, א בכותרת: נאמרה שבת קודש בשלח תקצ\"ה. מוגה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ. הגהות נדפסו באוה\"ת שמות ע' תלא.\n[בכת\"י 1223 פ, ב נעתק המאמר עם הגהות, בכותרת: אחרון של פסח תקצ\"ה].\nמאמר זה באריכות נדפס בתו\"ח בשלח [הוצאת קה\"ת — תשס\"ג] רמט, ב.\nהגהות וכו' מכ\"ק אדמו\"ר הצ\"צ נדפס באוה\"ת שמות כרך ז ע' ב'תערב. ראה פלח הרמון שמות ע' קמג.\nוראה גם ד\"ה זה במאמרי אדה\"א הנחות תקע\"ז ע' נא."],["2662","2","<b>וירא ישראל את היד הגדולה</b>: בשלח יד, לא."],["2663","3","<b>ויקרא הוי' הוי'</b>: תשא לד, ו."],["2664","4","<b>ב' מדריגות בשם הוי'</b>: ע' בלקו\"ת פ' תצא בד\"ה ולא אבה ובהביאור. אוה\"ת נ\"ך ע' תקכו. בפ' יתרו ע' תתקי. תצוה ע' א'תשא. דרושים לשבועות ע' רח. תצא ע' תתקכא. תשא ע' ב'סז."],["2665","5","<b>ההתהוות. . בשם זה הוי'</b>: ראה אגה\"ת פ\"ד."],["2666","6","<b>ממך הכל</b>: ראה דברי הימים-א כט, יד."],["2667","7","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["2668","8","<b>היו\"ד. . בחי' הצמצום</b>: ראה גם אגה\"ת פ\"ד."],["2669","*8","<b>וכמ\"ש במ\"א</b>: ביאור ד\"ה ועשית ציץ תקס\"ו [נדפס בתו\"ח שמות [הוצאת קה\"ת — תשס\"ג] שנו, א]."]]],[2100490472,"נשאר רק נקודא א' ואח\"כ זיו האלקי נתפשט לאורך ורוחב כו' ואח\"כ נעשה בחי' ההמשכה כוי\"ו כו' עד שבה\"א בראם ממש מאין ליש גמור ולהיות כי זה האופן הוא ע\"י צמצום והעלם העצמו' לגמרי הרי נעשה הבריא' כמו מחודש ממש דהיינו בבחי' יש נפרד כו' והיינו ענין שם הוי' המהוו' מאין ליש ממש וד\"ל. וזהו יהללו<sup data-n=\"2670\">9</sup> את שם הוי' כי הוא צוה ונבראו פי' כי הוא קאי על שם הוי' שהזכיר בסמוך ששם הוי' זה צוה ונבראו כלומר נמשך מלמעלה ונתקשר להיו' בחי' כח הפועל בנפעל והיינו ענין צו\"ה שהוא לשון התקשרו' כידוע ונבראו לשון נפעל כו' כי ירד שם הוי' זה מלמעלה ונתקשר למטה להיו' כח הפועל כו' וממילא נבראו יש מאין כו' וכנ\"ל וד\"ל.\n<b>והנה</b> שם הוי' זה ישנו בכל העולמות דאבי\"ע כי כל בחי' התהוו' א\"א כ\"א ע\"י שם הוי' זה בצמצום ואח\"כ התפשטו' כו' וגם עולם האצי' נאצל בשם הוי' מן המאציל כו' אך יש עוד שם הוי' שלמעלה מזה שאינו ע\"ש בחי' &lt;קמד&gt;\nהתהוו' שהוא כח הפועל בנפעל בכל עולם לפי ערכו אלא הוא בבחי' העלם עצמות המשפיע והמהווה עדיין קודם שהוציא מכח אל הפועל כו' והענין הוא מה שאמר בזוהר<sup data-n=\"2671\">10</sup> ובע\"ח כשעלה ברצונו הפשוט כו' שהוא עד\"מ כשאדם רוצה לעשות איזה דבר מה כמו לכתוב ולצייר דבר וכיוצא שבתחלה עולה אופן הציור במחשבתו ורצונו איך יצייר באיזה אופן ואח\"כ גומר זה בפועל וא\"כ אין לך כאן דבר חדש אלא במה שהוציא מכח אל הפועל בלבד אבל גופו של אופן המעשה אין בו חידוש שכבר הועלה בכל פרטיו ברצון ומחשבה אלא ששם הוא בהעלם העצמו' עדיין ובבואו מכח ההעלם אל הפועל הוא בא בהתגלות כו' ולפ\"ז מובן בדוגמא ג\"כ בבחי' שם הוי' הנ\"ל המהוו' העולמו' אחר שהוא בחי' כח הפועל בנפעל בהכרח הוא שקדם לבא ראשונה ברצון העליון דהיינו כשעלה ברצונו להאציל כו' וכשעלה ברצונו לברוא כו' אלא שהי' שם בבחי' העלם העצמו' עדיין וא\"כ כמו שיש שם הוי' למטה בפרט בד' אותיו' יו\"ד ה\"א כו' כך יש שם הוי' למעלה בבחי' הרצון הפשוט בפרט ג\"כ והוא היו\"ד בתחלה ואח\"כ הה\"א כו' והכל ברצון ומחשבה עדיין להאציל ולברוא כו' כי מבואר ממשל הנ\"ל דכל סדרי פרטי הפעולה קדמו לבא תחלה בעצמו' הפועל ברצונו ומחשבתו עדיין כו' וד\"ל וענין היו\"ד בשם הוי' זה כשעלה ברצונו להאציל היינו ג\"כ ענין צמצום העצמו' כמו ענין היו\"ד בשם הוי' למטה בבחי' ההתהוו' כו' כי א\"א להיו' בחי' התפשטו' ברצון כ\"א ע\"י צמצום כל עצמותו בתחלה וזהו מ\"ש ישת<sup data-n=\"2672\">11</sup> חושך סתרו כו' ואח\"כ עלה ברצון בבחי' התפשטו' אורך ורוחב והוא הה\"א ואח\"כ הוי\"ו והה\"א והכל שם הוי' א' שכלול ברצון וכללותו הוא עדיין רק בבחי' ההעלם ונק' כתר עליון בכללות ההשתלשלו' כמ\"ש בספרי הקבלה וד\"ל. ובדרך כלל הנה נק' שם הוי' זה שברצון ומחשבה סתימא' בשם הוי' דלעילא ושם הוי' שמהו' העולמו' בחי' שם הוי' דלתתא ונק' ג\"כ בלשון עלמא דאתכסיא ועלמא דאתגליא שהרצון הוא בבחי' העלם העצמו' של המאציל נק' עלמא דאתכסיא והוי' שמהו' עולם האצי' והבריא' וכיוצא נק' עלמא דאתגליא כידוע וד\"ל.",[["2670","9","<b>יהללו את שם הוי'</b>: תהלים קמח, ה."],["2671","10","<b>בזוהר ובע\"ח כשעלה ברצונו הפשוט</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["2672","11","<b>ישת חושך סתרו</b>: תהלים יח, יב."]]],[2100490473,"<b>וזהו</b> וירא ישראל את היד הגדולה אשר עשה הוי' במצרים כו'. כי הנה פרעה אמר מי<sup data-n=\"2673\">12</sup> הוי' אשר אשמע בקולו לפי ששרש קליפ'<sup data-n=\"2674\">13</sup> פרעה הי' באחורי העורף כו' הוא בא ויונק מבחי' אחוריי' דאחוריי' דשם הוי' דקדוש' שמאיר מאצי' לבריא' וגם בשרש ומקור ההשתלשלו' של העולמו' דהיינו באצילו' עצמו אחר שנאצל בבחי' גילוי אורו' ע\"י שם הוי' כו' גם שם הי' לו שרש יניק' מבחי' חיצוניו' ואחוריי' דאחוריי' כו' אבל בשם הוי' דלעילא דהיינו בבחי' הכתר דעולם האצי' שהוא הרצון כשעלה ברצונו להאציל כו' שהוא בבחי' העלם העצמו' של המאציל עדיין כנ\"ל לא הי' לפרעה שום שרש יניקה כלל וכלל אחר שהוא בבחי' ההעלם ולא נתגלה למטה בבחי' השתלשלו' מכח אל הפועל עדיין כנ\"ל וע\"כ אמר פרעה מי הוי' אשר אשמע כלומר מי הוא זה השם דהוי' אשר לא ידעתיו כלל כי לא הי' לו שרש כלל שם מטעם הנ\"ל וע\"כ לא האמין כלל בשם הוי' זה שברצון ואמר מי הוי' אשר אשמע בקולו כי רק בשם הוי' דלתתא הי' יודע ולא בהוי' דלעילא כו' &lt;קמה&gt;\nוד\"ל.\n<b>אך</b> הנה בני ישראל בשעת קריעת י\"ס ראו והשיגו בזה השם דהוי' שברצון ומחשבה וזהו שאמר וירא ישראל כו' אשר עשה הוי' במצרים פי' ב' השגות השיגו אז אחד שיש שם הוי' בהעלם הרצון כו' והב' איך שיכולי' לעשו' לזה השם ברצון ע\"י מעשה התחתונים למטה והוא ע\"י סור<sup data-n=\"2675\">14</sup> מרע ועשה טוב כו' וזהו אשר עשה הוי' שנעשה שם הוי' דלעילא הנ\"ל במצרים דוקא במדרגו' התחתונו' שנק' מצר י\"ם והוא ע\"י צמצום שיצמצם האדם א\"ע וכובש את יצרו להיו' סור מרע שהוא בחי' ביטול עצמות וכו' ע\"י כפייה שכופה ומבטל א\"ע עושה כמו בחי' יו\"ד שהוא בחי' הצמצום כנ\"ל ואח\"כ בעשותו טוב במעשה המצות ותורה ועבודה וכמו בצדקה וגמ\"ח וכיוצא עושה בחי' ה\"א שהוא בחי' התפשטו' לאורך ורוחב שהרי במעשה זו מתפשטת אור אלקי לשכון למטה כידוע דרמ\"ח<sup data-n=\"2676\">15</sup> פקודי' נק' רמ\"ח איברי' כו' וכיוצא בזה נעשה כללות שם הוי' ע\"י מעשה התחתונים דהיינו בבחי' צמצום והתפשטו' והמשכה והתפשטו' כו' ובאתערותא דלתתא אתערות' דלעילא שנעשה כמו שם הוי' זה ממש בבחי' העלם עצמו' המאציל להיו' עולה ברצונו להאציל כו' ג\"כ ע\"י ד' אותיו' הללו צמצום העצמו' בראשונה והוא היו\"ד כו' וזהו אשר עשה שם הוי' דלעילא ברצון העלם במצרים דוקא. אך הטעם למה במצרים דוקא הנה מצרים<sup data-n=\"2677\">16</sup> הוא המיצר והצמצום כמ\"ש מן<sup data-n=\"2678\">17</sup> המצר קראתי כו' והיינו בחומר<sup data-n=\"2679\">18</sup> ובלביני' שעבדו כו' ועי\"ז הלאו קודם להן נתעורר למעלה ג\"כ כענין המבואר<sup data-n=\"2680\">19</sup> במ\"א בטעם מצות ל\"ת שהם בחי' אותיו' י\"ה שבשם הוי' צמצום דלאו בתחלה (ומה שממשיכי'",[["2673","12","<b>מי הוי' אשר אשמע בקולו</b>: שמות ה, ב."],["2674","13","<b>קליפ' פרעה הי' באחורי העורף</b>: ראה לקו\"ת להאריז\"ל ר\"פ שמות."],["2675","14","<b>סור מרע ועשה טוב</b>: פע\"ח (שחה\"מ) שכ\"א, פ\"ז. סידור סדר הגדה רצג, ג. ל' הכתוב תהלים לד, טו."],["2676","15","<b>דרמ\"ח פקודי' נק' רמ\"ח איברי'</b>: ראה תקו\"ז ת\"ל. וראה תניא פ\"ד, ובליקוט פירושים שם."],["2677","16","<b>מצרים הוא המיצר</b>: ראה ב\"ר פט\"ז, ה."],["2678","17","<b>מן המצר קראתי</b>: תהלים קיח, ה."],["2679","18","<b>בחומר ובלביני' שעבדו</b>: ראה שמות א, יד."],["2680","19","<b>המבואר במ\"א בטעם מצות ל\"ת</b>: ביאור לד\"ה אלה פקודי תקס\"ו נדפס בתו\"ח שמות [הוצאת קה\"ת — תשס\"ג] תמב, ג ואילך. ראה ג\"כ אגה\"ת פ\"א."]]],[2100490474,"שם הוי' שברצון דוקא כי זה המיצר בא מבחי' א\"ח וכמבואר<sup data-n=\"2681\">20</sup> במ\"א ע\"פ הראיני את מראייך שבבחי' א\"ח הכתר קודם והוא דוקא יעורר הרצון הפשוט כו' ע\"ש) וד\"ל.\n<b>אך</b> הנה לפ\"ז יש להבין מה שאמר את היד הגדולה אשר עשה ה' כו' מה זה היד הגדולה ענין לאשר עשה ה' עפ\"י הנ\"ל וגם מה שאמר וירא ישראל כו' דוקא בשעת קריעת י\"ס דאדסמיך לי' קאי' דכתיב והמים<sup data-n=\"2682\">21</sup> להם חומה כו' וירא<sup data-n=\"2683\">22</sup> ישראל את מצרים מת על שפת הים וירא ישראל את היד הגדולה כו' מה ענין זה לקריעת י\"ס דוקא.\n<b>אך</b> הענין הוא דהנה יש להבין תחלה מהו ענין קרי\"ס בהיות מבואר בענין קריעת י\"ס בכתוב למעלה דכתיב ויט<sup data-n=\"2684\">23</sup> משה כו' ויולך ה' את הים ברוח קדים כו' וישם את הים לחרבה כו' ויש להבין מהו זה שאמר לחרבה<sup data-n=\"2685\">24</sup> דוקא שהוא ענין תכלית היבישו' עד שלא נמצא שם שום לחלוחיו' כלל וכלל כו' דהנה ידוע מארז\"ל דכל<sup data-n=\"2686\">25</sup> מה שיש ביבשה יש בים כו' וידוע<sup data-n=\"2687\">26</sup> שים ויבשה למעלה נק' עלמא דאתכסיא ועלמא דאתגליא וביאור הדברי' הנה כתיב יקוו<sup data-n=\"2688\">27</sup> המים כו' ותראה היבשה פי' היבשה הוא אשר ממנה נמצאו כל הנמצאי' דצח\"ם כמ\"ש תוצא<sup data-n=\"2689\">28</sup> הארץ כו' תדשא הארץ כו' וגם האדם מן העפר נברא וז\"ש הכל<sup data-n=\"2690\">29</sup> הי' מן העפר כו' והוא משום דארץ<sup data-n=\"2691\">30</sup> אולידת ועביד' פירין כמ\"ש בזוהר משא\"כ הים שלא ימצא ממנו מציאו' דצח\"ם בפ\"מ בד' יסודו' אך הים יש בו כל הנבראי' שיש ביבשה בהעלם ולא בגילוי כמאמרם כל מה כו' וכדי שיבא לידי גילוי אמר יקוו המים מתחת השמים &lt;קמו&gt;\nותראה היבשה פי' שיתצמצם ויתעלם בחי' ההעלם ויוכל לבא בחי' גילוי דיבשה להוציא כל הנמצאי' דצח\"ם כו' ודוגמא זאת הי' גם למעלה בבחי' ים ויבשה העליונים שנקוו המים העליונים שבבחי' עלמא דאתכסיא וכמ\"ש יקוו המים כו' ואח\"כ ויאמר<sup data-n=\"2692\">31</sup> אלקי' יהי אור יהי רקיע שהוא בחי' הדיבור הנק' עלמא דאתגליא הנק' ארץ למעלה כידוע וזהו ותראה היבשה כו' ועד\"ז עד רום המעלות הכל הוא בא בבחי' העלם וגילוי ים ויבשה כידוע ודרך כלל בחי' העלם הרצון הנ\"ל נק' עלמא דאתכסיא בכלל והוא שם הוי' דכת\"ר כנ\"ל ועלמא דאתגליא היינו שם הוי' המהווה כל העולמו' נק' בבחי' יבשה לגבי ים כו' וד\"ל.",[["2681","20","<b>וכמבואר במ\"א ע\"פ הראיני את מראיך</b>: ראה לעיל ע' רצב-ג."],["2682","21","<b>והמים להם חומה</b>: בשלח יד, כב."],["2683","22","<b>וירא ישראל את מצרים</b>: בשלח יד, ל."],["2684","23","<b>ויט משה כו' ויולך ה' את הים ברוח קדים</b>: בשלח יד, כא."],["2685","24","<b>לחרבה. . תכלית היבישו'</b>: ראה מכילתא כאן ובפי' זה ינחמנו."],["2686","25","<b>דכל מה שיש ביבשה יש בים</b>: ראה חולין קכז, א. ירושלמי שבת פי\"ד, ה\"א."],["2687","26","<b>וידוע שים ויבשה. . ועלמא דאתגליא</b>: ראה גם לקו\"ת צו יד, ב. סה\"מ תקס\"ג ח\"א ע' קנה. דרך חיים שער התפלה פנ\"א. שער האמונה פנ\"ב. מאמרי אדה\"א שמות ח\"א ע' חצר. וש\"נ. הנחות תקע\"ז ע' נה. וש\"נ."],["2688","27","<b>יקוו המים</b>: בראשית א, ט."],["2689","28","<b>תוצא הארץ</b>: שם א, כד."],["2690","29","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["2691","30","<b>דארץ אולידת ועביד' פירין כמ\"ש בזוהר</b>: ראה זהר בהקדמה יב, א. בראשית מו, א."],["2692","31","<b>ויאמר אלקים יהי אור יהי רקיע</b>: בראשית א, ג."]]],[2100490475,"<b>והנה</b> בשעה שהפך ים ליבשה ויעברו בנ\"י בתוך הים בחרבה כו' אע\"פ שהי' ענין זה למטה בענין גשמי שהים הגשמי נהפך ליבשה הנה מ\"מ הרי הים ויבשה הגשמיי' שרשם בים ויבשה העליוני' עד רום המעלו' ונהפך אז ים ליבשה עד רום המעלו' והיינו שבחי' ההעלם בא לידי גילוי עד רום המעלו' וכמו שנאמר למטה וישם את הים לחרבה דהיינו שלא נשאר שם שום לחלוחית כלל גם מחלקי המים שנכנס בארץ ועפר שהי' הים עליו כך עד רום המעלו' שרשי הים והיבשה נהפך הים ליבשה עד שלא נשאר גם שום רשימו בעלמא מבחי' ההעלם רק הכל בא בבחי' יבשה וכענין שהי' בראשית הבריא' דכתיב יקוו המים כו' ותראה היבשה כו' וד\"ל ואחר שראו ישראל שיכול להיו' מהעלם גילוי הבינו והשיגו אז שיוכל להיו' גם מבחי' העלם הרצון לבא בבחי' גילוי והוא להיו' מתצמצם ובא בד' אותיו' יו\"ד ה\"א כו' וזהו וירא ישראל את היד הגדולה כו' פי' היד הגדולה שהפך ים ליבשה מהעלם גילוי למטה מזה ראו אשר עשה הוי' שנעשה שם הוי' דלעילא בבחי' העלם הרצון ג\"כ כי הכל טעם א' הוא וד\"ל (והיינו ששייך זה לקריעת י\"ס דוקא והיינו שארז\"ל ראתה<sup data-n=\"2693\">32</sup> שפחה על הים כו' וד\"ל).\n<b>וזהו</b> ויראו העם את ה' ויאמינו בה' ובמשה עבדו. דהנה בחי' ראיה לא שייך אלא בדבר הנגלה ונראה לעין כל וזהו ויראו את הוי' פי' היינו בחי' הוי' דלתתא המהווה כל העולמות מפני שהוא בחי' עלמא דאתגליא לכך יתכן בו בחי' ראיה כי יוכל לבא בבחי' ההשגה וההתבוננות והוא להיות ששם הוי' זה מקרוב הוא כי הוא כח הפועל האלקי כו' ועד\"מ אדם שעומד לפני מלך ב\"ו כל שעומד מקרוב יותר יותר יהי' לו יראה ועיקר היראה הפנימי' הוא יראה<sup data-n=\"2694\">33</sup> בושת כשמתבייש ומתבטל לגמרי ממציאותו והוא רק כל הקרב קרב יותר יהי' בחי' ירא בושת יותר וה\"ז מצד ההתגלות דוקא מקרוב<sup data-n=\"2695\">34</sup> אבל מרחוק לא שייך בחי' היראה בושת כלל ולכך יראה<sup data-n=\"2696\">35</sup> אותיו' ראיה כי ענין א' לראיה עם היראה שכל שהוא בכלל ראיה הוא בא לידי בחי' יראה והיינו ויראו שהי' להם בחי' יראה בושת משם הוי' הנגלה דוקא אבל בשם הוי' הנסתר שהוא בחי' הוי' שבהעלם הרצון כנ\"ל לא שייך בחי' יראה אחר שאין שם בחי' ראיה והשגה כלל כי נסתר ונעלם הוא למעלה מעלה מן ההשגה ואינו נראה ומושג כלל ולכך נק' עלמא דאתכסיא בכלל כנ\"ל לכך נאמר בו ויאמינו בהוי' כלומר בשם הוי' זה הנסתר לא הי' להם רק בחי' &lt;קמז&gt;\nאמונה בלבד שהאמונה היא למעלה מן ההשגה והשכל ולהיותו נסתר האמינו בו באמונה שלמעלה מן הטעם כו' ושניהם אמת דהיראה הי' להם בשם הוי' דלתתא והאמונה בשם הוי' דלעילא וד\"ל.",[["2693","32","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ."],["2694","33","<b>יראה בושת</b>: תקו\"ז בהקדמה ה, ב. ת\"ז תכ\"ח."],["2695","34","<b>יראה. . מקרוב</b>: ראה מאמרי אדה\"א בראשית ע' רמב. קונטרסים ע' רפב. ובהנסמן בהנ\"ל."],["2696","35","<b>יראה אותיות ראיה</b>: ראה סידור שער הל\"ג בעומר שו, א. שערי אורה מ, א ובהערה 19."]]],[2100490476,"<b>וזהו</b> שאנו אומרים בש\"ע הגדול הגבור והנורא ולכאורה אינו מובן למה לא אמר והגבור כמו שאמר והנורא אך הענין הוא מטעם הנ\"ל דבחי' ההתגלות דוקא מביאה לידי יראה שיראו ממנו ואז נקרא בשם נורא דכשהוא מקרוב דוקא יריאים ממנו ביותר כנ\"ל ואז אימתו מתפשטת ביותר ונק' נור\"א אבל כשהוא בהסתר והעלם אין יריאים ממנו ולא נק' נור\"א כו' וכך למעלה כדי שיקרא הוא ית' בשם נורא הוא ע\"י בחי' ההתגלות דוקא וזאת ההתגלות היא בחי' צמצום לגבי עצמותו שהרי הוא נק' סתימו<sup data-n=\"2697\">36</sup> דכל סתימין כו' ע\"כ אמר והנורא מפני שכדי שיקרא נורא צ\"ל נמשך בבחי' צמצום ההמשכה בתחלה כמו וי\"ו שמורה צמצום ההמשכה שראשו יו\"ד והולך ומתקצר למטה כידוע עד שנק' נור\"א שהוא בבחי' ההתגלות מקרוב כנ\"ל וד\"ל.\n<b>ובמשה</b> עבדו פי' משה<sup data-n=\"2698\">37</sup> הוא בחי' הדעת כידוע וענין בחי' הדעת<sup data-n=\"2699\">38</sup> הוא בחי' ההתקשרות וכמ\"ש והאדם ידע<sup data-n=\"2700\">39</sup> כו' והוא בחי' התקשרות המשפיע במקבל כמ\"ש במ\"א ולכך נק' רעיא<sup data-n=\"2701\">40</sup> מהימנא כי הוא מז' הרועים המפרנסים<sup data-n=\"2702\">41</sup> לכללות נ\"י כידוע אך מה שנקרא בשם רעיא מהימנא דהיינו שהוא רועה<sup data-n=\"2703\">42</sup> נאמן וכמ\"ש בכל<sup data-n=\"2704\">43</sup> ביתי נאמן הוא כו' הענין הוא משום דהוא בחי' הממוצע לחבר ולקשר בחי' שם הוי' דלעילא הנ\"ל בשם הוי' דלתתא כי הדעת<sup data-n=\"2705\">44</sup> הוא בחי' הממוצע כידוע וזהו שאמר אנכי<sup data-n=\"2706\">45</sup> עומד בין הוי' וביניכם כו' והיינו שהוא הממשיך בחי' הוי' שבהעלם הרצון לבא בכנ\"י בבחי' גילוי וא\"כ הרי האמונה באה לידי ראיה בהתגלות כי מה שלא השיגו בראי' רק באמונה הביאם לידי ראי' והשגה וכמ\"ש בזוהר<sup data-n=\"2707\">46</sup> דאוליף רזא דמהימנותא להם כו' ולכך נק' רועה נאמן פי' נאמן הוא מלשון אמונה והמקבל האמונה נק' נאמן בלשון נפעל והוא הי' רועה נאמן שהי' ממשיך לכנ\"י בחי' אמונה זו שבהעלם כו' דהיינו שהי' זן ומפרנס את כנ\"י באמונה זו להיות להם למזון וחיות בבחי' השגה וטעם כמ\"ש לאהבה<sup data-n=\"2708\">47</sup> את ה' אלקיך כי הוא חייך ממש כו' וזהו ע\"ד ורע\"ה אמונה כו' ולכך נאמר במשה לא<sup data-n=\"2709\">48</sup> כן עבדי משה בכל ביתי נאמ\"ן הוא דהיינו בחי' האמונה שהיא בבחי' העלם הרצון שאינו מתגלה למטה בהשתלשלו'",[["2697","36","<b>סתימו דכל סתימין</b>: זהר בהקדמה ב, א. ועוד."],["2698","37","<b>משה הוא בחי' הדעת</b>: ראה תניא פמ\"ב."],["2699","38","<b>הדעת הוא בחי' ההתקשרות</b>: ראה תניא פ\"ג. פמ\"ב."],["2700","39","<b>והאדם ידע</b>: בראשית ד, א."],["2701","40","<b>רעיא מהימנא</b>: ראה זהר וירא קו, א. שמות ח, ב. ועוד. פתיחתא דאיכ\"ר כד. ילקו\"ש איכה סוף רמז תתקצז."],["2702","41","<b>מז' הרועים המפרנסים</b>: ראה תיקונים לז\"ח קד, א."],["2703","42","<b>משה. . רועה נאמן</b>: ראה פדר\"א פמ\"ב. אסת\"ר פ\"ז פסוק יג. פתיחתא דאיכ\"ר כד. זהר שמות כא, א."],["2704","43","<b>בכל ביתי נאמן הוא</b>: בהעלותך יב, ז."],["2705","44","<b>הדעת הוא בחי' הממוצע</b>: ראה ע\"ח שער (לד) תיקון הנוקבא פ\"ג. תניא ספ\"ג. ספמ\"ג."],["2706","45","<b>אנכי עומד בין הוי' וביניכם</b>: ואתחנן ה, ה."],["2707","46","<b>בזוהר דאוליף רזא דמהימנותא</b>: ראה זהר תרומה קסא, א."],["2708","47","<b>לאהבה את הוי' אלקיך</b>: נצבים ל, כ."],["2709","48","<b>לא כן עבדי משה</b>: בהעלותך יב, ז."]]],[2100490477,"כנ\"ל וד\"ל וזהו שארז\"ל דיראה<sup data-n=\"2710\">49</sup> לגבי משה מלתא זוטרתא היא כו' דשם הוי' דלעילא שבבחי' העלם הכתר לא שייך שם בחי' היראה אחר שהוא נסתר ונעלם מפני שהוא למעלה מן ההתגלות כנ\"ל וע\"כ היראה שם מלתא זוטרתא רק במה שמושג ונגלה ששייך שם היראה כנ\"ל שם מדרגת היראה מדרגה גבוה לפי אופן הקירוב כל<sup data-n=\"2711\">50</sup> הקרב קרב יותר יותר יש בו היראה פנימי' אבל לגבי משה שנק' נאמן באמונה שהוא למעלה מן ההתגלו' אין היראה חשובה כלום כי אין ערך כלל בין ב' הויו' הנ\"ל וכמ\"ש ויקרא הוי' הוי' ופסיק טעמא בנייהו כנ\"ל וד\"ל וזהו ויאמינו בהוי' דלעילא ובמשה עבד\"ו שהוא הרועה הנאמן להביא להם בחי' אמונה זו בבחי' גילוי מן ההעלם וגם הביאם והגביהם לקשרם ולחברם למעלה באמונה זו כי העלם לבחי' הוי' דלעילא כמו הרועה שישא את הצאן כו' ולכך אמר להם &lt;קמח&gt;\nואתם<sup data-n=\"2712\">51</sup> תחרישון בבחי' הביטול במציאות כי הביאם והעלם לעלמא דאתכסיא בשעת קריעת י\"ס ששם בחי' השתיקה כמ\"ש ואחרי<sup data-n=\"2713\">52</sup> הרעש כו' קול דממה דקה כו' ולכך אז דוקא ישיר משה ובני ישראל כי גם ישראל עם משה נתעלו לומר כי<sup data-n=\"2714\">53</sup> גא\"ה גא\"ה כו' לפי שהי' רעיא מהימנא כנ\"ל וד\"ל.\n<b>וזהו</b> הפך<sup data-n=\"2715\">54</sup> ים ליבשה בנהר יעברו ברגל שם נשמחה בו. הנה נשמחה להבא משמע שעתידי' אנו לשמוח בו ולא עכשיו והלא כבר הי' קריעת י\"ס והל\"ל שם שמחו בו כו', אך הענין הוא להיות ידוע שענין השמחה<sup data-n=\"2716\">55</sup> הוא ענין הגילוי מן ההעלם כמו שנראה לעין בשמחתו של אדם שיגלה כל מצפוני לבבו והוא מפני שהשמחה היא ההתגלות והנה עתה בזמן הגלות כנ\"י משועבדים בשיעבוד הפרנסה ובהסתרת חומריות העולם עם חומריות הגוף כו' והסתרה זו מצד הגוף גורמת שלא יוכלו לבא לבחי' שמחה שהוא בחי' ההתגלות כדי שעי\"ז יבא למעלה ג\"כ בחי' שמחה עליונ' בשם הוי' דלעילא הנ\"ל כמ\"ש ישמח<sup data-n=\"2717\">56</sup> הוי' כו' והשמחה עליונה גורמת בחי' גילוי ההעלם דהיינו שיתגלה שם הוי' שבהעלם ומפני הסתרת חומריות עוה\"ז למטה אין אתעדל\"ת למטה לעשות אתעדל\"ע בבחי' שמחה זו כו' וע\"כ אין עכשיו בכנ\"י רק בחי' האמונה בשם הוי' דלעילא הנ\"ל שהוא בבחי' ההעלם והסתר ולא בבחי' ההתגלות כנ\"ל אבל לעתיד דוקא נא' שם נשמחה בו שיבאו לבחי' שמחה זו כו' דהנה גם לעתיד יהי' בחי' קריעת י\"ס כמו בזמן יצ\"מ ואדרבה ביתרון מעלה ומדרגה שהרי נא' לעתיד והכהו לז' נחלים כו' והיתה מסלה לשאר עמו כו' ולעתיד הרי נא' (ישעי' י\"א) והחרים לשון ים מצרים והכהו<sup data-n=\"2718\">57</sup> לז' נחלים לז' בקיעות כו' והיתה מסלה ממש לילך בחרבה כו' כיום עלותו מארץ מצרים כו' וזהו בנהר יעברו ברגל דהל\"ל",[["2710","49","<b>דיראה לגבי משה מילתא זוטרתא היא</b>: ברכות לג, ב. וראה גם שערי אורה מא, ב ובהנסמן בהערות שם."],["2711","50","<b>כל הקרב קרב יותר</b>: ראה ג\"כ דרך מצותיך כט, ב. ובכ\"מ."],["2712","51","<b>ואתם תחרישון</b>: בשלח יד, יד."],["2713","52","<b>ואחרי הרעש</b>: מלכים-א יט, יב."],["2714","53","<b>כי גאה גאה</b>: בשלח טו, א."],["2715","54","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["2716","55","<b>השמחה. . הוא ענין הגילוי</b>: ראה ג\"כ תו\"ח ויצא קג, ב ובהערה 12."],["2717","56","<b>ישמח הוי'</b>: תהלים קד, לא."],["2718","57","<b>והכהו לז' נחלים</b>: ישעי' יב, טו."]]],[2100490478,"עברו ברגל לשעבר ולמה יעברו לשון להבא אלא על העתיד נא' שיעברו בז' בקיעות והדריכם שם בנעלים וע\"כ אמר שם נשמחה בו נשמחה לשון עתיד ושם דוקא נשמחה בו כו' כי הנה לעתיד כתיב כי<sup data-n=\"2719\">58</sup> עין בעין יראו כו' פי' בחי' סובב כ\"ע הכללי שהוא בחי' העלם הרצון הנ\"ל יבא אז בבחי' גילוי מן ההעלם והיינו שיתגלה שם הוי' דלעילא ויתחברו ב' ההויו' הנ\"ל ואשר עכשיו הוא רק בבחי' ההעלם מקיף וסובב את כל ההשתלשלו' דאבי\"ע וכמ\"ש ומתחת<sup data-n=\"2720\">59</sup> זרועו' עולם כו' בא יבא אז למטה בבחי' גילוי בעין השכל בהשגה וראי' בכללו' נ\"י וזהו כי עין בעין יראו עין דשכל דכללו' נ\"י יראו בעין המקיף הסובב הכללי והוא ענין התחברות עין בעין דב' הויו' הנ\"ל הוי' דלעילא עם הוי' דלתתא כי הכל ענין א' הוא וד\"ל וע\"כ יהי' אז ענין קריעת י\"ס להפוך ים ליבשה כי בזה מתגלה ההעלם דעלמא דאתכסיא בא בבחי' עלמא דאתגליא כמבואר למעלה בענין וישם את הים לחרבה כו' ויהי' אז בז'<sup data-n=\"2721\">60</sup> בקיעות נגד ז' המדות שברצון שכולם יבקעו ויומשכו מן ההעלם לגילוי וזהו והכהו לז' נחלים כו' וזהו שם נשמחה בו שם דוקא נשמחה בבחי' השמחה המביאה בחי' ההתגלות מן ההעלם ופי' בו בעצמות המאציל שהוא נסתר עכשיו ואינו אלא רק בבחי' האמונה בלבד כו'. ומה שהזכיר עבר ועתיד בפסוק אחד דהפך ים ליבשה &lt;קמט&gt;\nלשעבר משמע ובנהר יעברו ברגל כו' להבא משמע הענין הוא משום דהיום<sup data-n=\"2722\">61</sup> לעשותם ולמחר לקבל שכרם דהאמונה דעכשיו היא רק לעשות לשם הוי' למעלה בהעלם הרצון להיות נמשד ביו\"ד ה\"א כו' ע\"י צמצום והתפשטות שלמטה בסור מרע ועשה טוב כנ\"ל כי באתעדל\"ת אתעדל\"ע כמאמר רוח אייתי רוח כו' והוא ע\"י ביטול וצמצום הרצון למטה להיות מבטל א\"ע ורצונו מפני רצון ה' כך למעלה מבטל א\"ע ומצמצם א\"ע כי להיות בחי' רצון למעלה א\"א כ\"א ע\"י צמצום כנ\"ל ואח\"כ התפשטות הרצון בבחי' ה\"א כו' אבל למחר לקבל שכרם שיהי' גילוי שם הוי' שברצון העליון למטה כי עכשיו אינו אלא למעלה בבחי' העלם המקיף כו' ולע\"ל יתגלה למטה וזהו שם נשמחה בו ומשום שלעתיד לא יהי' בחי' הסתר כלל מצד הגוף וכמ\"ש בלע<sup data-n=\"2723\">62</sup> המות לנצח ואת<sup data-n=\"2724\">63</sup> רוח הטומאה אעביר כו' וד\"ל.\n<b>וזהו</b> שארז\"ל יפה<sup data-n=\"2725\">64</sup> שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב כו'. דהנה ענין העוה\"ב הוא אשר הנשמות נהנין מזיו כו' שבא בבחי' השגה שהוא בחי' התפשטות אורך ורוחב כו' וביו\"ד<sup data-n=\"2726\">65</sup> נברא העוה\"ב הוא בחי' הצמצום של אור האלקי בתחלה כו' ובו נברא העוה\"ב מאין ליש כו' וזהו בעולם הבריאה ועד\"ז יובן למעלה ג\"כ והוא בעולם הנאצל שהיו\"ד הוא הצמצום בבחי' האצי' והה\"א התפשטות כו' וכידוע שכללות עולם האצי' הוא רק שם הוי' א' היו\"ד<sup data-n=\"2727\">66</sup> בחכמה והה\"א בבינה כו'",[["2719","58","<b>כי עין בעין יראו</b>: ישעי' נב, ח."],["2720","59","<b>ומתחת זרועו' עולם</b>: ברכה לג, כז."],["2721","60","<b>בז' בקיעות</b>: ראה ג\"כ תו\"ח בשלח [הוצאת קה\"ת — תשס\"ג] קנח, א. מאמרי אדה\"א הנחות תקע\"ז ע' נו."],["2722","61","<b>דהיום לעשותם ולמחר לקבל שכרם</b>: ואתחנן ז, יא. ראה עירובין כב, א."],["2723","62","<b>בלע המות לנצח</b>: ישעי' כה, ח."],["2724","63","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["2725","64","<b>יפה שעה א' בתשובה</b>: אבות פ\"ד מי\"ז."],["2726","65","<b>וביו\"ד נברא העוה\"ב</b>: מנחות כט, ב."],["2727","66","<b>היו\"ד בחכמה</b>: ראה זהר בראשית לא, א. (רעיא מהימנא) ויקרא יז, א. תקו\"ז בהקדמה ו, ב. אגה\"ת פ\"ד."]]],[2100490479,"וזהו בפרט ובכלל היו\"ד באצי' והה\"א בריאה כו' והיו\"ד נק' חיי העוה\"ב שמחי' העוה\"ב מאין ליש כו' אבל יפה תשובה ומע\"ט בשעה אחת בעוה\"ז מכל חיי העוה\"ב והטעם הוא לפי ששם הוי' זה שממנו נמשך חיי עוה\"ב בעולם הבריאה הוא שם הוי' דלתתא הנ\"ל שמהווה כל העולמות וגם שם הוי' דאצי' בכלל זה אחר שהאצי' נאצל מהעלם לגילוי ובהכרח שיבא ע\"י בחי' ד' אותיו' צמצום והתתפשטות כו' ואמנם ע\"י תשובה ומע\"ט שהוא בחי' צמצום והתפשטות שנעשה למטה עי\"ז כנ\"ל בסור מרע בתשובה ועשה טוב במע\"ט כו' נעשה עי\"ז שם הוי' דלעילא שבבחי' ההעלם הרצון מטעם הנ\"ל ואין ערך כלל בין ב' ההויו' כנ\"ל שהרי פסיק טעמא בנייהו כו' לכך יפה שעה א' בתשובה ומע\"ט בשניהם דוקא ובעוה\"ז דוקא מכל חיי העוה\"ב וד\"ל.\n<b>ובזה</b> יובן ג\"כ מה שארז\"ל מאן<sup data-n=\"2728\">67</sup> דלא כרע במודים אינו קם בתחיית המתים ולכאורה מה שייכות יש לכריעה במודים עם תח\"ה אך הענין הוא שיש ב' מדרגו' א' בחי' הודאה והב' בחי' ברכה וידוע ההפרש אשר ביניהם שהברכה<sup data-n=\"2729\">68</sup> הוא בחי' ההמשכה מן ההעלם לגילוי וזה א\"א כ\"א מצד הדביקות שם והוא ע\"י השגה ותפיס' כו' אבל ההודאה הוא בחי' ביטול במציאות שאין ההשגה מגעת לשם רק שמודה בהודאה כו' והוא בחי' הצמצום וביטול עצמותו שהוא בחי' היו\"ד ואח\"כ יכול להמשיך הברכה בבחי' התפשטות כמ\"ש מן המצר<sup data-n=\"2730\">69</sup> קראתי כו' ענני במרחב יה כנ\"ל ולפי שהגילוי מן העלם דשם הוי' דלעילא לעתיד יהי' בזמן תח\"ה דלכך יחיו המתים משום שיתגלה בחי' סובב כ\"ע הכללי דקמי' כחשיכ'<sup data-n=\"2731\">70</sup> כאורה כו' וכמ\"ש ומתחת זרועות עולם כו' כמ\"ש במ\"א ע\"כ אמרו &lt;קנ&gt;\nדמי שלא כרע במודים עכשיו שהוא בחי' ההודאה והביטול לא יקום בתח\"ה להיות בו גילוי ההעלם דסובב למטה כו' אחר שלא הי' בגופו בחי' ביטול בכריעה והשתחווי' כו' כי היום לעשותם ולמחר לקבל שכרם שהוא גילוי בחי' סובב כ\"ע כו' שתלוי' בתשובה ומע\"ט דעכשיו כנ\"ל וד\"ל. ובזה יובן ג\"כ מה שארז\"ל דמאן דלא כרע במודים לאחר זמן שדרתו נעשה נחש כי<sup data-n=\"2732\">71</sup> סטרא דמותא שליט בי' כמ\"ש בזוהר וד\"ל)<sup data-n=\"2733\">72</sup>.\n<b>וזהו</b> אז ישיר משה ובני ישראל את השירה הזאת כו' אשירה לה' כי גאה גאה כו'. פי' כי גאה גאה היינו בחי' ב' הויו' הנ\"ל הוי' דלתתא נק' גאה למטה בעלמא דאתגליא דאבי\"ע בכלל וכמ\"ש ה'<sup data-n=\"2734\">73</sup> מלך גיאות לבש כו' והוי' דלעילא שבהעלם הרצון נק' גאה<sup data-n=\"2735\">74</sup> גאה ות\"א גיאה על גוותניא כו' להיות כי פסיק טעמא בנייהו ואין",[["2728","67","<b>מאן דלא כרע במודים</b>: ראה בבא קמא טז, סע\"א."],["2729","68","<b>שהברכה הוא בחי' ההמשכה</b>: ראה גם סידור שער התפלה כג, א. שער החנוכה רפ, ג. שערי אורה לב, א. שערי תשובה כו, א."],["2730","69","<b>מן המצר קראתי</b>: תהלים קיח, ה."],["2731","70","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["2732","71","<b>כי סטרא דמותא שליט בי' כמ\"ש בזהר</b>: ראה זהר שלח קסד, א. סידור שחרית לה, ג. שער הל\"ג בעומר שג, ד."],["2733","72","<b>וד\"ל)</b>: בגוכתי\"ק חסר התחלת המוסגר."],["2734","73","<b>ה' מלך גיאות לבש</b>: תהלים צא, א."],["2735","74","<b>גאה גאה ות\"א גיאה על גוותניא</b>: בשלח טו, א. וראה ת\"א שם."]]],[2100490480,"ערך כלל ביניהם כנ\"ל אבל משה שהוא בחי' הדע\"ת הממוצע כנ\"ל בפי' ובמשה עבדו לכך הי' ביכולתו להעלו' גם לכנ\"י עמו ושישירו עמו יחד השירה הזאת שהוא לומר כי גאה גאה מפני שההעלם בא לידי גילוי על ידו וזהו אז ישיר משה ובנ\"י אז דוקא בשעת קריעת י\"ס שהאמינו בהוי' דלעילא ובמשה עבדו שהוא רועה הנאמ\"ן ולכך ישיר משה ובנ\"י יחד כו' ובאד\"ר מבואר בפירוש שבמשה דוקא תלוי' המשכת ההעלם דכתר לגילוי כו' כי מה שכתוב ויקרא הוי' הוי' כו' משמעו' הפשוט דויקרא זה קאי על שם הוי' שהזכיר בסמוך ויעבור<sup data-n=\"2736\">75</sup> ה' על פניו כו' ויקרא הוי' כו' שהקדב\"ה קרא הוי' הוי' כו' אבל באד\"ר<sup data-n=\"2737\">76</sup> מפרש בהדיא דויקרא זה קאי על משה דוקא דאחר שעבר ה' על פניו אז ויקרא משה הוי' הוי' כו' ע\"ש וא\"כ קריאה זו דהוי' הוי' מן ההעלם לגילוי במשה תליא מלתא והיינו לפי שנק' רעיא מהימנא כנ\"ל וזהו שאמר אז ישיר משה ובנ\"י דוקא משה עם בנ\"י והוא העיקר בדבר שהרי לא אמר אז ישירו משה ובנ\"י אלא ישיר לשון יחיד לפי שנכללו בנ\"י במשה לפי שהוא העיקר מטעם הנ\"ל וד\"ל.",[["2736","75","<b>ויעבור ה' על פניו</b>: תשא לד, ו."],["2737","76","<b>באד\"ר מפרש. . דויקרא זה קאי על משה</b>: ראה נשא קלח, א. תרגום ירושלמי עה\"פ. פדר\"א ספמ\"ו. מאמרי אדה\"א ח\"ב ע' תלד."]]],[2100490481,"<h3>ויסע משה</h3>\n<b>בעזר\"ה</b>\n<b>ויסע</b><sup data-n=\"2738\">1</sup> משה<sup data-n=\"2739\">2</sup> את ישראל מים סוף מדבר שור כו'. הנה לשון ויסע משמע שהסיעם<sup data-n=\"2740\">3</sup> בעל כרחם לפי שכאשר ראו והשיגו בבחי' ההעלם דשם הוי' דלעילא הנ\"ל בשעת קריעת י\"ס שהים נעשה לחרבה כו' והם נתעלו אז להיו' בבחי' התקשרו' ממש בשם הוי' זה ע\"י משה שהעלה אותם וחיבר &lt;קנא&gt;\nוקישר אותם שם ע\"כ לא רצו כלל ליסע ולנתק א\"ע ממדרגה הגבוה הזאת שהיא ההתדבקו' בבחי' עצמו' אור א\"ס שהוא בחי' סובב כ\"ע בכלל כנ\"ל ובאמת צריך שיהי' בחי' גילוי אור א\"ס למטה בעלמא דאתגליא ע\"י תורה ומע\"ט כידוע כמ\"ש<sup data-n=\"2741\">4</sup> כי לא לתוהו ברא' לשבת יצרה כו' וכמ\"ש במ\"א ולזה הי' כל עיקר הכונה של המאציל כדי שיהא לו דירה<sup data-n=\"2742\">5</sup> בתחתונים",[["2738","1","<b>ויסע משה</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (לא, א).\nמאמר זה באריכות נדפס בתו\"ח בשלח [הוצאת קה\"ת — תשס\"ג] קמט, ד. — ד\"ה וירא ישראל. ומקבילו בתו\"א בשלח סא, ד.\nוראה מאמרי אדה\"א בשלח ע' קלד ומקבילו בתו\"א שם סב, ב.\nוראה גם אוה\"ת תשא ע' א'תתקצח. מסעי ע' א'שפג.\nמאמר זה הוא המשך לד\"ה לפנ\"ז וירא ישראל את היד הגדולה."],["2739","2","<b>ויסע משה את ישראל</b>: בשלח טו, כב."],["2740","3","<b>שהסיעם בעל כרחם</b>: מכילתא הובא ברש\"י שם."],["2741","4","<b>כי לא לתוהו ברא'</b>: ישעי' מה, יח. וראה לקו\"ת שלח מ, ד. ברכה צו, ג."],["2742","5","<b>דירה בתחתונים</b>: ראה תניא רפל\"ו. וראה הנסמן בליקוט פירושים לשם."]]],[2100490482,"דוקא כידוע וזהו שאמר ויסע משה את ישראל מי\"ס שהסיעם משם בע\"כ והורידם לבחי' עלמא דאתגליא אע\"פ שלא רצו כו' ומדבר שור הוא בחי' עלמא דאתגליא כי פי' שור<sup data-n=\"2743\">6</sup> מלשון ראיה והבטה הוא כמו אשורנו<sup data-n=\"2744\">7</sup> ולא עתה כו' והיינו שחזר משה והסיעם מעלמא דאתכסיא הנק' טורי<sup data-n=\"2745\">8</sup> חשוכא והוא בחי' העלם הרצון לבחי' עלמא דאתגליא וזהו מים סוף מדבר שור כו' וד\"ל ואח\"כ ויבאו<sup data-n=\"2746\">9</sup> מרתה כו' כי בעלמא דאתגליא מתחיל שרש עה\"ד טו\"ר כידוע ויש שרש וראש שם ליניקו' החיצונים הנק' מים המרים כמ\"ש בזהר<sup data-n=\"2747\">10</sup> דאית מיין כו' מים צלילן מיין מתיקין ואית מיין מרירן כו' ולא יכלו לשתות מים ממרה כי מרים הם כמ\"ש רגליה<sup data-n=\"2748\">11</sup> יורדות מות והיא בחי' מל' דנוגה שנק' מר ממות וכמ\"ש ומוצא<sup data-n=\"2749\">12</sup> אני מר ממות את האשה כו' וכתיב ראה נתתי לפניך החיים והטוב ואת המות והרע ובחרת בחיים כו' להיותה תכלית הסיגים ושמרי הדינין הקשין ולכך נק' שמה מר\"ה מ\"ר ה\"א כו' ויצעק<sup data-n=\"2750\">13</sup> אל ה' ויורהו ה' עץ וישלך אל המים וימתקו פי' הורה ה' לו בחי' עץ החיים שלמעלה מעה\"ד טו\"ר כו' ובו נמתקו כל הדינין הקשי' שנאחזי' בעה\"ד כו' והשלכה זו מעץ החיים לעה\"ד ירידה גדולה היא אך בשביל המתקו' הדינין שם הושלך עץ מעץ החיים כו' וד\"ל.\n<b>ונמצא</b> מובן מנסיעה זאת שהסיעם בע\"כ מים סוף מדבר שור שהוא ירידה לעלמא דאתגליא ובנסיעה הראשונה די\"ס היו בבחי' עלי' והרי יש כאן עלי' וירידה ואח\"כ באו מרתה הי' כאן ג\"כ ירידה ואח\"כ עלי' בהמתקת הדינין בעץ החיים כו' ובנסיעה שאחריה לאלימה היתה בחי' עלי' שבאו שם ומצאו י\"ב עינות מים ושבעים תמרים כו' ובנסיעה שאחריה במדבר סין הי' בהם בחי' ירידה ממדריגה שהרי נא' שם וילונו<sup data-n=\"2751\">14</sup> כל עדת כו' מי יתן מותנו במצרים כו' כי הוצאתם אותנו אל המדבר הזה להמית וכו' ועד\"ז הי' כל המ\"ב מסעות שלהם הכל בדרך עלי' וירידה כמבואר למעיין בהן והענין הוא לפי שבחי' שם מ\"ב הי' במ\"ב מסעו' שלהם כידוע<sup data-n=\"2752\">15</sup> ומבואר בכתבי האריז\"ל ובחי' שם מ\"ב הוא הולך ואור הכל בדרך עלי' וירידה לפי שהוא עולה בבחי' הגבורו' שהוא בבחי' רצוא ושוב וכמו ע\"ד דוגמא מעפיפת העופות בכנפיהם שהכנף מנדנד למטה ולמעלה כו' וכך במלאכי' כתיב ובשתים<sup data-n=\"2753\">16</sup> יעופף בבחי' רו\"ש וזהו ענין הלוך<sup data-n=\"2754\">17</sup> ונסוע הנגבה שנא' באברהם וגם כאן היה בכללו' שם מ\"ב שהן שש כנפים בפרט במלאכי' וכך הי' נוסעי' בבחי' עלי' וירידה",[["2743","6","<b>שור מלשון ראיה והבטה</b>: ראה ג\"כ תו\"ח תולדות קנח, ד."],["2744","7","<b>אשורנו ולא עתה</b>: בלק כד, יז."],["2745","8","<b>טורא חשוכא</b>: ראה זהר פינחס רמט, ריש ע\"ב."],["2746","9","<b>ויבאו מרתה</b>: בשלח טו, כג."],["2747","10","<b>בזוהר דאית מיין</b>: ראה זהר נח סו, א. שמות ו, א."],["2748","11","<b>רגליה יורדות מות</b>: משלי ה, ה."],["2749","12","<b>ומוצא אני. . מר ממות</b>: קהלת ז, כו."],["2750","13","<b>ויצעק אל ה' ויורהו ה' עץ. . עץ החיים</b>: בשלח טו, כה. ראה ס' הבהיר (סנ\"ב) סקס\"א. מאמרי אדה\"א דברים ח\"א ע' קח. וש\"נ."],["2751","14","<b>וילונו כל עדת. . להמית וכו'</b>: בשלח טז, ב. ג."],["2752","15","<b>כידוע ומבואר בכתבי האריז\"ל</b>: ראה זהר תרומה קלב, ב. פרדס שער (כא) פרטי השמות פי\"ב. פי\"ג. לקו\"ת מסעי צב, ב."],["2753","16","<b>ובשנים יעופף</b>: ישעי' ו, ב."],["2754","17","<b>הלוך ונסוע הנגבה</b>: לך לך יב, ט."]]],[2100490483,"כו' שהי' משה מנהיגם עפ\"י שם זה לפעמי' בבחי' עלי' ולפעמים בבחי' ירידה כו' והוא לפי אופן המדה שבשם אם חסד שבחסד או גבורה שבחסד וכידוע שהמדות כלולים זה מזה ע\"כ הי' נסיעתם פעם בבחי' חסדים ופעם בבחי' גבורות וכמו בנסיעה דמרה הי' בבחי' גבורה שבחסד וכיוצא ולכך נמתקו המים שם ונק' גבורות ממותקו' כו' וכמבואר פרטי המסעו' לי\"ח וד\"ל ובזה &lt;קנב&gt;\nיובן ג\"כ מה שלפעמים הי' נסיעתם בבקר ולפעמים בערב וכמ\"ש בבקר<sup data-n=\"2755\">18</sup> נעלה הענן כו' כי עפ\"י<sup data-n=\"2756\">19</sup> ה' יחנו ועפ\"י יסעו הכל בשם מ\"ב זה ולפעמי' הי' הנסיעה ביום שהוא בבחי' החסדים כמ\"ש כי<sup data-n=\"2757\">20</sup> חסד אל כל היום ולפעמים הי' נוסעי' בלילה שהוא בבחי' הגבורות והכל ע\"י משה שהי' מסיעם עפ\"י שם הוי' והוא שם מ\"ב בכלל וד\"ל.",[["2755","18","<b>בבקר נעלה הענן</b>: ראה נשא י, יא."],["2756","19","<b>עפ\"י ה' יחנו</b>: בהעלותך ט, כ."],["2757","20","<b>כי חסד אל כל היום</b>: תהלים נב, ג."]]],[2100490484,"<h3>ביאור הדברים ע\"פ וקבל היהודים</h3>\n<b>בעזר\"ה שבת פ' </b>\n(ביאור<sup data-n=\"2758\">1</sup> שני לדרוש דפורים)\nלהבין שרשי הדברים הנאמרים בפורים ע\"פ וקבל<sup data-n=\"2759\">2</sup> היהודים אשר החלו לעשות כו' ע\"ש. הנה שרש ענין נעשה<sup data-n=\"2760\">3</sup> ונשמע שאמרו בשעת מ\"ת יתפרש בשני דרכים, הדרך הא' הוא שהמצות שקיבלו עליהם שהם בחי' הכלים לאורו' גרמו שיבאו האורו' ויתפשטו בכלים ואם לא המצות שהן הכלים לא היו האורו' מתפשטי' כלל וכלל כו' ויובן זה בהקדים תחלה מהו ענין אורו' וכלים דהנה רמ\"ח<sup data-n=\"2761\">4</sup> מ\"ע רמ\"ח איברים דמלכא הן והוא בחי' ריבוי הכלים דז\"א כמו אור החסד הוא מתפשט בריבוי הכלים כמו חסד שבחסד וגבורה שבחסד כו' ועד\"ז בגבורה חסד שבגבורה כו' וכאשר באה התחלקו' זאת בבחי' רת\"ס שהוא בחי' עי\"מ נגדלי' יותר עד שכל מדה כלולה מט'<sup data-n=\"2762\">5</sup> פעמי' ט' ג\"פ שהוא גי' פ\"א ג\"פ שעולה רמ\"ג וה' החסדי' השרשיי' המגדילי' בכלל עולה רמ\"ח כמבואר בכתבי האריז\"ל בפרטו' ענין הגדלה זו, ואמנם כדי שיהי' חיבור וקישור כ\"כ פרטי' אורו' בריבוי כלים כאלה זהו בא מסיבת הכלים דוקא שכל מה שמתחלקי' ונעשי' בריבוי יותר יותר יתפשט בהן האור בריבוי כו'.\n<b>ויובן</b> דבר זה בהקדים תחלה כלל אחד שכל בחי' אור אינו אלא בחי' השפעה והמשכה בלבד ולא שהוא עצם המהות כמו שהוא שהרי נק' אור שאינו אלא",[["2758","1","<b>ביאור שני לדרוש דפורים</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק (1025 לא, ב). ראה לקמן ע' שצו הנחת ר\"מ בן אדה\"ז.\nנו\"א נדפס בתו\"א צז, א."],["2759","2","<b>וקבל היהודים</b>: אסתר ט, כג."],["2760","3","<b>נעשה ונשמע</b>: ראה משפטים כז, ד."],["2761","4","<b>רמ\"ח מ\"ע רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שערי תשובה עב, ג הערה 17."],["2762","5","<b>מ\"ט פעמים ט'. . שעולה רמ\"ג</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"ו. הנסמן בשערי תשובה מב, ב הערה 13."]]],[2100490485,"ענין זיו שהוא בא בבחי' התפשטות בלבד וכן הוא או' וירא<sup data-n=\"2763\">6</sup> אלקי' את האור כי טוב ואין טוב אלא ענין השפעה והמשכה כי מטבע<sup data-n=\"2764\">7</sup> הטוב להיטב כו' והאור והטוב הכל ענין א' וד\"ל, והמופת לזה יובן מאור זה הגשמי שהרי ידוע שיש ד' יסודו' ארמ\"ע ויסוד האש גבוה מכולן ומעמדו בגובה האויר למעלה כו' וידוע שיש<sup data-n=\"2765\">*7</sup> חקירה בין הפלסופי' אם המהות של האש היסודי הוא כמו האור הנראה לנו בשלהבת עץ השורף ודולק או במהות אחר ודחו זאת הסברא שאם הי' במהות אור שלהבת הרי הי' מאיר אורו בכל האויר עד הארץ גם באישון לילה ואפילה לאחר ששקעה השמש כו' אלא מוכרח לומר שהוא עצם חשוך כו' ובאמת עיקר הענין הוא שאור זה הנאחז בעץ הדולק הוא בא בבחי' השפעה והמשכה ע\"כ הוא אור &lt;קנג&gt;\nנגלה בממשות אבל אש היסודי להיותו בחי' העצם והמהות של שלהבת רשפי אש הנמצאי' מאתו למטה ע\"כ איננו בבחי' אור ממשי כלל ואינו במהו' אור מאיר כלל אלא הוא כח דק רוחני למעלה מבחי' אור מאיר אך מי הוא הגורם שיבא ממנו האור ויאיר בבחי' ממשו' הענין הוא שזהו דוקא כשיש בחי' מקבל שיקבל האור ויתפעל ממנו אזי יומשך האור ויאחז בו ויאיר בו כמו העץ שנשרף בהיותו בחי' מקבל להתפעל מן השלהבת ע\"כ זהו הסיבה שיתאחז בו השלהבת ואינו מתאחז בו אלא כל זמן שהעץ מתפעל שהוא קבלת האור בתוך תוכו שהרי כאשר יכלה וישרף העץ מסתלק האור והשלהבת משום שאין לו בחי' מקבל שיקבל אותו ובלתי מקבל לא יבא השפע ואם הי' האור עצם ומהות ולא בחי' השפעה לא הי' תלוי אור המשכתו במקבל דוקא אלא מפני שאין האור אלא בחי' השפעה והמשכה כנ\"ל לכך כשיש מקבל שיתפעל מהשפעתו יומשך בו ואם לאו חוזר למקורו והוא עצם האש היסודי שאינו במהו' אור מאיר כלל כו' וזהו שאנו רואים גם באור המאיר יש בו התפשטו' והסתלקו' תמיד לפי שהעץ יש בו ב' דברים א' הכלה ונשרף כבר שגורם ההסתלקו' והב' מה שיש בו עדיין לקבל האור והוא הגורם ההמשכה וההתפשטות כו' וד\"ל, והנמשל מדוגמא זו יובן למשכיל למעלה בענין אורו' וכלים העליוני' שאין בחי' האור בא מן המאציל אלא כשיש כלי לקבל ומחמתו יבא דוקא ואם אין בחי' כלי שיתפעל ויקבל אינו נמשך ומאיר כלל אלא כלול הוא בעצמו' המאציל שממנו מסתעפי' האורו' עד\"מ הסתעפו' האור הגשמי למטה מן האש היסודי כו' וכמ\"ש<sup data-n=\"2766\">**7</sup> במ\"א באריכו' ע\"פ כי ה' אלקיך אש אוכלה הוא ע\"ש וד\"ל וא\"כ מובן שסיבת ריבוי האורו' ג\"כ אינו אלא מסיבת ריבוי הכלים דוקא וזהו שרש ענין שאמרו נעשה ונשמע פי' נעשה בחי' כלים במצות שהן רמ\"ח איברי' כו' ואז ממילא ונשמע שהוא בחי' התפשטו' והמשכו' האורו' בכלים מטעם הנ\"ל וכידוע",[["2763","6","<b>וירא אלקי' את האור כי טוב</b>: בראשית א, ד."],["2764","7","<b>מטבע הטוב להיטב</b>: ראה מאמרי אדה\"א קונטרסים ע' ה. וש\"נ."],["2765","*7","<b>שיש חקירה בין הפלסופי'</b>: ראה תו\"א מג\"א צז, א — ויש חקירה בין החוקרים במהותו. במאמרי אדה\"א ויקרא ח\"ב ע' תע בשם הרמב\"ם [מו\"נ ח\"ב פ\"ל] ”דיסוד האש הרוחני אינו אלא אור דק מאד וחשוך גם לא אויר חם\". וראה בהנסמן לשם. ובע' תנ כ' ”כי הפילוסופים אומרים כי יסוד האש אינו אש ממש רק אויר דק שאי אפשר עליו לומר שהוא אש ממש\". וראה במים רבים תרל\"ו פרק קו בשם ספרי המחקר שאש היסודי אינו אויר אשר יחי' בו האדם. וראה בספר הערכים-חב\"ד ח\"ב ערך אויר."],["2766","**7","<b>וכמ\"ש במ\"א באריכות ע\"פ כי ה' אלקיך אש אוכלה הוא</b>: דברים ד, כד. תו\"א שם. וראה ביאוה\"ז להצ\"צ ח\"ב ע' תתרמז."]]],[2100490486,"דענין שמיעה הוא ענין קבלה כמו הסכת<sup data-n=\"2767\">8</sup> ושמע ישראל כי השמיעה באזן הוא ענין קבלת הדברי' דהיינו שנאספי' ונקבצין ונקלטי' בתוכו כמו האזינו השמים כו' ולכך פי' שמיעה יתפרש גם בענין אסיפה וקיבוץ ממש כמו וישמע<sup data-n=\"2768\">9</sup> שאול את העם וכיוצא וגם כאן הענין הוא שנקבצו ונאספי' ריבוי אורו' בריבוי כלים ולכך אמרו נעשה ונשמע כלומר ונקבל האורו' בכלים שנעשה כי עיקר סיבת אסיפת אור בכלי אינו אלא מצד הכלי דוקא כנ\"ל לכך נעשה ואח\"כ נשמע ממילא כו' וד\"ל.\n<b>ובזה</b> יובן מה שאמרו במשנה ולא<sup data-n=\"2769\">10</sup> עם הארץ חסיד דלכאורה אינו מובן מה ענין החסידו' דוקא שע\"ה לא יגיע אליה הלא גם לתורה לא זכה כו' אך הנה מבואר שם בענין אברהם שקיים<sup data-n=\"2770\">11</sup> כל התורה כו' ואעפ\"כ לא קיים בפ\"מ שהרי פעם אמרו שלא זכה לתורה כו' אלא הענין הוא דבאברהם נא' הלוך<sup data-n=\"2771\">12</sup> ונסוע בבחי' רצוא ושוב כו' כמבואר שם והוא בחי' אור בכלי ג\"כ כמ\"ש כי<sup data-n=\"2772\">13</sup> אתה תאיר נרי כו' משום דכתיב נר<sup data-n=\"2773\">14</sup> אלקי' נשמת אדם ואור אלקי מאיר בו והוא בחי' כלי לאור האלקי כו' והנה נשמת אברהם היתה נשמה גבוה מאד שהרי האבו'<sup data-n=\"2774\">15</sup> הן המרכבה שהוא בחי' מרכבה לאורו' דאצי' ממש כו' ע\"כ הי' אור נשמתו יכול להיו' בחי' כלי לקבל האור &lt;קנד&gt;\nהאלקי לשכון בו ממש כמו למעלה בבחי' אורו' וכלים דאצי' והיינו ע\"י מדת אהבה במס\"נ וביטול במציאות שהי' בנשמתו עי\"ז הי' יכול לקבל האור שהוא בחי' אור חסד דאצי' כידוע שאור החסד למעלה הוא בחי' האהבה כמו שידוע בפי' ואהבת פי' או\"ר כי גי' של ואהבת<sup data-n=\"2775\">16</sup> ב\"פ אור (וגם ה' החסדי' הנ\"ל המגדילים לכלים הן ה' אורו' ה' פעמי' ויאמר כו' אור) אך אח\"כ כשירדו הנשמות הנמוכות בעולם ולא היו יכולים להיות בחי' כלי לאור האלקי עד שיהי' מתפשט מחמתן כנ\"ל לכך ניתנה להם התורה והמצות להיות להם בחי' כלים בנשמתם לאור האלקי ע\"י המצות שיקיימו בפ\"מ שהמה מלובשים בענינים גשמיים ויכולים לקבל על ידם האור דוקא ולא ע\"י אור נשמתם באוי\"ר שלהם כי נמוך הוא כו' וזהו שאמרו שאברהם קיים כל התורה ר\"ל ברוחניות אחר שגם על ידי נשמתו נמשך כל פרטי האורות בכלים ברו\"ש כמו שע\"י המצות כו' אך אעפ\"כ לא קיים המצות בפ\"מ בגשמיות כו' והיינו שאמרו ולא ע\"ה חסיד, פי' חסי\"ד הוא בחי' מקבל החסד כי היו\"ד שבתיבה זו מורה על בחי' קבלת אור החסד בעצמו ולכך נק' חסי\"ד ולא חס\"ד, ואינו נקרא חסי\"ד לקבל אור חסד דאצי' שהוא כללו' כל המשכו' האורות כמ\"ש יומם<sup data-n=\"2776\">17</sup> יצוה ה' חסדו והוא יומא דאזיל<sup data-n=\"2777\">18</sup> עם כולהו יומין כו' כמ\"ש בזוהר אלא דוקא כשמקיים כל פרטי המצות ויש",[["2767","8","<b>הסכת ושמע ישראל</b>: תבוא כז, ט."],["2768","9","<b>וישמע שאול</b>: שמואל-א טו, ד."],["2769","10","<b>ולא עם הארץ חסיד</b>: אבות פ\"ב מ\"ה."],["2770","11","<b>שקיים כל התורה</b>: קידושין פב, א."],["2771","12","<b>הלוך ונסוע בבחי' רצוא ושוב</b>: לך לך יב, ט. וראה זהר לך פ, א. פד, א."],["2772","13","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."],["2773","14","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["2774","15","<b>האבו' הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["2775","16","<b>ואהבת ב\"פ אור</b>: ואתחנן ו, ה. פע\"ח שער הק\"ש פכ\"ג. סידור האריז\"ל במקומו. תניא ספמ\"ג."],["2776","17","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט."],["2777","18","<b>דאזיל עם כולהו יומין כמ\"ש בזוהר</b>: ראה זח\"ג קג, א-ב. קצח, ב. ובהנסמן בסה\"מ תש\"ח ע' 144 הערה כח."]]],[2100490487,"לו בחי' ריבוי הכלים לקבל האור כי מסיבת הכלי יבא האור דוקא והיינו ע\"י המצות שנק' כלים וכמ\"ש כי<sup data-n=\"2778\">19</sup> נר מצוה ותורה אור אם מקיים המצות שנק' נ\"ר אז יאיר האור בו ונק' חסי\"ד ואם לאו אינו נק' חסי\"ד וד\"ל.\n<b>והדרך</b> השני בפי' נעשה ונשמע ולא ע\"ה חסיד הנ\"ל הוא מצד שהכלים שרשם גבוהים מן האורות ע\"כ ביכולתם דוקא להמשיך האור בכלים כו'. וביאור ענין זה יובן בהקדים תחלה ענין הידוע בשבירת הכלים דרפ\"ח ניצוצי' שנפלו מעולם התוהו גבוהים במעלה יותר מבחי' התיקון וכמ\"ש ואלה<sup data-n=\"2779\">20</sup> המלכים אשר מלכו בארץ אדום לפני מלוך מלך לבני ישראל שהן ז' מלכי' דתוהו שקדמו למלך לישראל שהוא בחי' התיקון ולכך נפלו רפ\"ח ניצוצי' כ\"כ למטה מטה עד רגלי העשי' וכו' כידוע עד\"מ<sup data-n=\"2780\">21</sup> אבן הנופלת מן החומה שכל שתפול מן הגובה ביותר יותר תתפשט נפילתה לעמק מטה כו' ולזה הטעם אנו רואים שהצומח והדומם של המאכלים יחיו מהם נפש האדם בחי' המדבר אע\"פ שבחי' המדבר גבוה מבחי' הצומח כו' אלא לפי שהמאכל שרשו מבחי' התוהו שקדם לתיקון וכמ\"ש<sup data-n=\"2781\">22</sup> במ\"א ע\"פ כי לא על הלחם כו' כי על כל מוצא פי ה' כו' והנה ידוע דכל המצות מעשיות נעשים הכל מדברים שנפלו בשבירת הכלים כמו תרומות ומעשרות מתבואה שצומחת ממזל דנוגה וכן כל כיוצא בזה כמו צמר הציצית וקלף התפילין שהן מבע\"ח גשמיים כו' ואף גם מצות ת\"ת שהוא ברוחניות הדיבור הרי הדיבור גשמי מהבל דנוגה כו' ואף גם כל הכוונו' שיש לנפש האדם במעשה המצות ג\"כ מבחי' נוגה הוא שהרי הכונה בנפש הוא לפי אופן המעשה בלבד והרי התלבשותה בחומר הגופני ע\"י כחות גופניי' להתעטף בטלית ואע\"פ &lt;קנה&gt;\nשהנפש עצמה מבחי' התיקון היא אבל כח הכונה במעשה המצוה הוא מבחי' הלבושי' שלה בנפש הבהמי' וע\"כ מעשה המצו' נק' לבושי' לנשמה בג\"ע כידוע וד\"ל ואמנם מפני ששרש רפ\"ח ניצוצי' שבנוגה הוא מבחי' התוהו שקדם לתיקון כנ\"ל ע\"כ המצות שנעשו מהם גבוהי' יותר מן הנשמה שהיא בבחי' התיקון וע\"כ ביכולתם גם לעורר למעלה מקור האורו' שיומשך למטה ויאיר האורות בכלים לפי שהכלים שהן נעשי' רמ\"ח איברי' דמלכא למעלה כמ\"ש אלה<sup data-n=\"2782\">23</sup> המצות אשר יעשה אותם האדם האדם דלעילא כידוע שרשם גבוהי' מבחי' האורו' שבבחי' אדם זה דאצי' שהוא שם מ\"ה דתיקון הנק' מלך ישראל כידוע מטעם הנ\"ל וזהו וחי בהם שיחי' ויקבל חיו' וקיום מהם ע\"ד דוגמא שהצומח יחי' נפש האדם למטה כנ\"ל וד\"ל. ובכל זה מובן יותר לשון רז\"ל במה שאמרו ע\"פ<sup data-n=\"2783\">24</sup> וישמור משמרתי דאברהם קיים כל התורה כו' ולפעמי' אמרו דלא זכה לתורה כו' דשניהם אמת דמצד נשמתו שהי' בחי' כלי לאור כנ\"ל קיים כל התורה ברוחניו' דהיינו",[["2778","19","<b>כי נר מצוה ותורה אור</b>: משלי ו, כג."],["2779","20","<b>ואלה המלכים אשר מלכו באדום</b>: וישלח לו, לא."],["2780","21","<b>עד\"מ אבן הנופלת</b>: ראה הנסמן לקמן ע' תא."],["2781","22","<b>וכמ\"ש במ\"א ע\"פ כי לא על הלחם</b>: עקב ח, ג. וראה לקו\"ת צו יג, ב. שלח, לו, ג. ובכ\"מ."],["2782","23","<b>אלה המצות אשר יעשה אותם</b>: חיבור ב' כתובים — בחוקותי כז, לד. אחרי יח, ה."],["2783","24","<b>ע\"פ וישמור משמרתי דאברהם קיים כל התורה</b>: תולדות כו, ה. קידושין פב, א."]]],[2100490488,"להוסיף אורו' בכלים למעלה כו' שזהו כללו' הכונה במצות וזהו וישמור משמרתי אבל במעשה המצות בגשמיות לעשותם מדברים גשמיים דנוגה לא קיים ולהיות שהן מבחי' התוהו שקדם לתיקון וגבוהי' יותר גם מנשמת אברהם שהי' מבחי' התיקון לזה אמר שלא זכה לתורה ומצות כי זכייה גדולה הי' לנשמתו על ידם כדי שתעלה ברום המעלות שגבוה מן האורו' דשם מ\"ה כו' ומצד נשמתו לא הי' אלא בחי' מקבל לאורו' דשם מ\"ה דתיקון כו' וד\"ל.\n<b>וזהו</b> הדרך השני בפי' נעשה ונשמע כלומר נעשה המצות בבחי' עשי' בגשמיות דנוגה ששרשם מתוהו שקדם לתיקון כנ\"ל ואזי ממילא נשמע שיומשכו האורות בכלים כי הכלי קדמה בשרש לאור והוא מבחי' התוהו שקדם לתיקון עד שמחמת הכלי נמשך האור ובא וכידוע דמעולם התוהו הוא שנמשך להיות בחי' עולם התיקון וד\"ל וזהו ג\"כ ענין המאמר ולא ע\"ה חסי\"ד, חס\"ד הוא בחי' שם מ\"ה דתיקון וחסי\"ד הוא להיות בחי' כלי לזה כמו אברהם<sup data-n=\"2784\">25</sup> שהי' נק' איש החסד והוא המשכו' האורו' בכלים בכלל כנ\"ל אבל ע\"ה שחסר מן המצות בקיום גשמי מדברים שבנוגה דוקא אינו נק' חסיד כי אין לו כלים למעלה מבחי' נוגה שיעורר מבחי' התוהו שקדם לתיקון להיות המשכות האורות בכלים כו' וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן שרש ענין המבואר שם ע\"פ<sup data-n=\"2785\">26</sup> כי תרכב על סוסיך כו' ב\"פ<sup data-n=\"2786\">27</sup> ס\"ג הוא גי' סו\"ס ויש ב' מיני סוס א' מלמטה למעלה המתנשא והמתגאה כו' והב' מלמעלה למטה כו' ע\"ש דהנה ידוע בספרי<sup data-n=\"2787\">28</sup> הקבלה ההפרש בין ימות החול לשבת דבימות החול ירידת ז\"א בבי\"ע ללקט ניצוצי' כו' יום הא' מאור החסד ויום הב' מבחי' גבורה כו' ובשבת הוא זמן עלי' דזו\"נ ותחלה יש להקדים הענין הידוע בע\"ח<sup data-n=\"2788\">29</sup> דמכל הברורים דרפ\"ח כו' הוא נעשה היחוד דמ\"ה וב\"ן כי שם ב\"ן הוא המברר למטה כו' ועולה הבירורי' בבחי' מ\"ן ואזי יורד בחי' מ\"ד לברר המ\"ן וכו' וכל זה קודם שנשלם שלימות הברורי' דרפ\"ח דהיינו כמו עכשיו בזמן הגלות אבל כשיושלם הברורי' דשם ב\"ן בשלימות כמו לעתיד אז יהי' מעלת שם ב\"ן גבוה משם מ\"ה וזהו מ\"ש<sup data-n=\"2789\">30</sup> &lt;קנו&gt;\nאשת חיל עטרת בעלה עטר\"ת לשם מ\"ה שנק' בעלה<sup data-n=\"2790\">31</sup> דמטרוניתא כידוע כי משם ב\"ן עולה להיות בחי' שם ס\"ג שלמעלה משם מ\"ה והטעם הוא לפי שעיקר השבירה דרפ\"ח הי' בשם ס\"ג דבינה בז\"ת דאימא כו' ונפלו בבחי' שם ב\"ן להתברר וכשיושלם בירורם יעלו לשרשם הקדום בבחי' ס\"ג דאימא כו' ובכל שבת יש קצת הארה מעין לעתיד ע\"כ יש בכל שבת מעין עלי' דשם ב\"ן",[["2784","25","<b>אברהם שהי' נק' איש החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["2785","26","<b>ע\"פ כי תרכב על סוסיך</b>: חבקוק ג, ח."],["2786","27","<b>ב\"פ ס\"ג הוא גי' סוס</b>: ראה תו\"ח בשלח רכו, א. וש\"נ."],["2787","28","<b>בספרי הקבלה ההפרש בין ימות החול לשבת</b>: ראה זח\"ג טז, ב. ריז, ב."],["2788","29","<b>בע\"ח. . היחוד דמ\"ה וב\"ן</b>: ראה ע\"ח שער (ה) טנת\"א, פ\"א."],["2789","30","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד."],["2790","31","<b>בעלה דמטרוניתא</b>: ראה זהר שלח קסג, ב. תזריע מב, ב."]]],[2100490489,"שיהי' לעתיד וזהו ענין עליו' העולמות בשבת בכלל שהוא עליי' המל' להיות בבחי' הבינה הוא שם ס\"ג שלמעלה ממ\"ה כו' וזה בא מצד הברורי' דרפ\"ח דשם ב\"ן מברר כל ימות החול ועולי' לשרשם בשבת ונעשים יותר גבוהים מבחי' התיקון דמ\"ה להיותם מבחי' התוהו דקדם לתיקון כנ\"ל וד\"ל וזהו ענין ב\"פ ס\"ג הא' בחי' ס\"ג שהוא עלי' והתנשאות מלמטה למעלה כו' וס\"ג ב' בירידה מלמעלה למטה כו'.\n<b>דהנה</b> בחי' בינה<sup data-n=\"2791\">32</sup> נק' בזוהר עלמא דחירות ונק' יובלא עילאה כמ\"ש וקראתם דרור<sup data-n=\"2792\">33</sup> כו' והיינו מפני שאין לחיצונים יניקה שם כלל וכלל ויש להבין הטעם למה. אך הענין הוא דיש בבחי' בינה ב' הפכי' א' בחי' עלי' והסתלקו' למעלה והב' בחי' ירידה והמשכה למטה מטה כו' והוא מ\"ש בקן צפור שלח<sup data-n=\"2793\">34</sup> תשלח את האם שהוא בחי' עלי' והסתלקו' למעלה וכתיב והאם<sup data-n=\"2794\">35</sup> רובצת על האפרוחי' כו' שהוא בחי' ירידה והמשכה למטה כו' וידוע דפי' אם הוא בחי' בינה<sup data-n=\"2795\">36</sup> שנק' אם הבנים כו' וזהו שבשם ס\"ג דאימא ניקוד דשם הוי' שבו נקוד בשם אלקי\"ם שהן ב' הפכי' הוי' הוא בחי' חסדי' ואלקי' הוא בחי' גבורו' מפני שבחי' העלי' והסתלקו' שיש באימא הוא בחי' אלקי' מבחי' הגבורו' ובחי' הירידה וההמשכה שיש באימא הוא מבחי' החסדי' דשם הוי' וע\"כ שם הוי' שבאימא נקוד הוא בניקוד אלקי' וד\"ל.\n<b>ולהבין</b> ביאור כל הדברים הללו מה הוא בחי' עלי' והסתלקו' שבבינה ומה הוא בחי' הירידה וההמשכה שע\"ז נא' שלח תשלח האם והאם רובצת כו' הנה יש להקדים תחלה ענין א' הידוע בע\"ח<sup data-n=\"2796\">37</sup> דכל המקיפי' בבינה כו' ולכאורה אנו מוצאים שכל הא\"פ בבינה הם שהרי השכלת והבנת השכל נק' בינה והוא אשר נתפס בהשגה בבחי' א\"פ ולמה אמר שכל המקיפי' בבינה כו', אך הענין הוא דשניהם אמת דהנה אנו רואי' בחושי הטבע של השכל שיש בכחו לסבול דבר שהוא שונאו בתכלית ולהיות מעיין בו כאילו הדבר נאהב אצלו כמו שאנו רואים שיוכל אדם לעיין בכל השגת שכלו בדבר השנאוי לציירו בדמיון מחשבתו תמיד ואע\"פ שישנא אותו הדבר תכלית השנאה יוכל לעיין ולהתבונן עליו הרבה והרי בהתבוננות זאת מקיף הוא לאותו הדבר כידוע שכל שכל המשיג וחושב באיזה דבר המושג אותו הדבר נתפס בשכל המשיגו ונעשה מוקף מכל צד מן השכל המשיגו והשכל מקיפו מכל צד כו' וא\"כ גם כשמשיג וחושב בדבר השנאוי הרי אותו הדבר השנאוי מוקף בשכל והשכל וההתבוננו' מקיפו מכל צד כו' ויש להפלא לכאורה אחר שהדבר שנאוי בלבו ששם משכן המדו' והמדות נמשכי' מן השכל כידוע וא\"כ\n&lt;קנז&gt;",[["2791","32","<b>בינה נק' בזוהר יובלא עלאה</b>: ראה זהר תצוה קפג, א. תקו\"ז תל\"ב. פרדס שער (כג) ערכי הכינויים מערכת יובל. רמ\"ז (במקדש מלך קלו, ב) ר\"פ וארא."],["2792","33","<b>וקראתם דרור</b>: בהר כה, י."],["2793","34","<b>שלח תשלח את האם</b>: תצא כב, ז."],["2794","35","<b>והאם רובצת על האפרוחי'</b>: שם ו."],["2795","36","<b>בינה שנק' אם הבנים</b>: תהלים קיג, ט. זח\"א ריט, א. זח\"ב פד, א. פה, ב. פרדס שער כג (שער ערכי הכינויים) ערך אם הבנים. וראה לקו\"ת שמע\"צ פח, ד."],["2796","37","<b>בע\"ח דכל המקיפי בבינה</b>: ראה ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א. וראה גם פי\"ג, ספי\"ד. שער סדר אבי\"ע (שמ\"ז) פ\"א."]]],[2100490490,"ראוי שגם השכל לא יסבול אותו הדבר השנאוי בלב כו' אלא מוכרח לומר שיש ב' מדרגו' בשכל א' אשר בא אורו בהשפעה למדו' שבלב והב' אשר הוא מופלא ומובדל על המדות בבחי' מקיף שאינו יכול להתיישב בהם בבחי' א\"פ אלא בבחי' מקיף בלבד והוא הכח שיש בשכל לחשוב ולהתבונן גם בדבר השנאוי בלבו כו' וכך יובן למעלה בבחי' בינה דאצי' שנק' אם הבנים שהן בחי' המדו' דז\"א כידוע שבחי' א\"פ המתיישב במדו' הוא אשר נשפע בהם בבחי' המשכה והתפשטו' והן בחי' המוחין שבמדו' עליונו' שהמדו' מקבלי' מהן ונמשכי' למטה בגילוי להיות בבחי' מדות ממש באהבה ושנאה כמו לאהוב את בנ\"י כמ\"ש אהבתי<sup data-n=\"2797\">38</sup> אתכם אמר ה' ולשנוא את אוה\"ע וכמ\"ש ואת<sup data-n=\"2798\">39</sup> עשו שנאתי בבחי' מדת השנאה ממש כו' ואע\"ג דאמר דאת עשו שנאתי הנה בבחי' השכל והתבוננות יכול להתפס ולהיות מוקף שם מכל צד כמשל הנ\"ל שיוכל אדם לעיין בדבר השנאוי כו' שאע\"פ שמצד השכל שמלובש במדת השנא' אינו יכול לסובלו אבל במחשבה שבבינה שבבחי' מקיף על המדו' יכול להתפס כי מטעם הנ\"ל שהוא מובדל ומופלא על המדו' מזה הטעם עצמו הוא שיכול להקיף הדבר השנאוי במדו' שבלב והכל ענין א' הוא דלפי ערך רוממו' המקיף כך ערך ירידתו למטה לסבול גם מה שמנגד בתכלית למדות כו' כענין שממית<sup data-n=\"2799\">40</sup> בידים תתפש כו' וד\"ל.\n<b>וכידוע</b> בס\"י<sup data-n=\"2800\">41</sup> דעומק רום ועומק תחת שניהם מכח אחד נמשכו דלפי ערך עומק רום כך ערך עומק תחת דכל שגבוה יותר יותר יוכל להשפיל א\"ע כו' וד\"ל וזהו מה שנא' במכו' בכורות במצרים ועברתי<sup data-n=\"2801\">42</sup> בארץ מצרים אני ולא מלאך כו' שהוא מפני שמ\"ט<sup data-n=\"2802\">43</sup> שערי טומאה דמצרים הוא היותר תחתון מכל ע\"כ א\"א לבא שם כ\"א היותר עליון כי לפי ערך רום כו' אך מה שאמר זה לענין מכת בכורות דוקא וכמ\"ש ועברתי בארץ מצרים והכיתי כל בכור כו' הענין הוא דדוקא משום הכאה זו לכלות הבכורות הוצרך לומר אני ולא מלאך כו' כי הנה מ\"ש בע\"ח דבכל ו' ימות החול יורדי' האורות דז\"א ללקט ניצוצו' כו' ענין לקיטת ניצוצו' הללו אינו ענין ניצוח גמור לאהפכא<sup data-n=\"2803\">44</sup> חשוכא לנהורא מרע לטוב אלא רק ללקט ניצוצי הקדושה מחלק הטוב שנפל ברע כו' והטעם הוא לפי שהרע עצמו לא יוכל להתברר ע\"י המדו' בלבד אחר שיש לז' מדו' רעות שרש אחיזה במדות דקדושה כענין הידוע במאמר אברהם<sup data-n=\"2804\">45</sup> שיצא ממנו ישמעאל מותרי<sup data-n=\"2805\">46</sup> החסד כו' אלא הבירור להפך ולכלות הרע לגמרי מכל וכל צריך להיות מלמעלה מבחי' המדו' שאין לחיצוני' שום שרש",[["2797","38","<b>אהבתי אתכם אמר ה'</b>: מלאכי א, ב."],["2798","39","<b>ואת עשו שנאתי</b>: מלאכי א, ג."],["2799","40","<b>שממית בידים תתפש</b>: משלי ל, כח."],["2800","41","<b>בס\"י דעומק רום</b>: פ\"א, מ\"ה."],["2801","42","<b>ועברתי בארץ מצרים אני ולא מלאך</b>: בא יב, יב. ספרי תבוא ו, ח. זהר (מהנ\"ע) וירא קיז, א. הגש\"פ."],["2802","43","<b>שמ\"ט שערי טומאה דמצרים</b>: זהר חדש ר\"פ יתרו. וראה לקו\"ש חי\"ז ע' 88."],["2803","44","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["2804","45","<b>אברהם שיצא ממנו ישמעאל</b>: ראה פסחים נו, א."],["2805","46","<b>מותרי החסד</b>: ראה תו\"א כו, א. קיט, ד. תו\"ח נח סד, ד."]]],[2100490491,"שם כלל וכלל והוא בחי' המקיף שעל המדו' הנ\"ל והוא אשר יכול לירד כ\"כ למטה עד בחי' מותרי המדו' שיש יניק' למדות דקליפה שם יניק' ולבררם ולהפך אותם מן הקצה לקצה וכמ\"ש לעתיד ואת<sup data-n=\"2806\">47</sup> רוח הטומאה אעביר כו' וזהו ע\"י בחי' אור אימא מבחי' המקיף דוקא והמשל בזה ידוע ע\"ד אם הבנים למטה שלא ירחץ צואת הבן רק האם דוקא כמאמר תבא<sup data-n=\"2807\">48</sup> האם ותקנח צואת בנה כו' וכמ\"ש במ\"א שזהו מ\"ש אם רחץ ה' צואת כו' א\"ת<sup data-n=\"2808\">49</sup> אִם אלא אֵם כו' וזה הכח שיש לבינה למטה הוא רק מצד הכח העצם שיש לה למעלה בהיותה בחי' מקיף על המדו' לסבול גם הדבר השנאוי ע\"כ גם למטה אע\"פ שנא' ואת עשו שנאתי יוכל לסבול אותו &lt;קנח&gt;\nכמו בזמן הגלות ולבררו עי\"ז לעתיד כמ\"ש ואת רוח הטומאה כו' משא\"כ למדות עצמן שאין ביכולתם זה מטעם הנ\"ל שיש לחיצוני' אחיזה בהם כו' וזהו שאמר ועברתי בארץ מצרים והכיתי כל בכור כו' דכדי להכות כל בכור להעביר רוח הטומאה ממש אין זה אלא ע\"י אני בעצמי ולא ע\"י מלאך וידוע דאני הוא בחי' מקיף כמ\"ש אני<sup data-n=\"2809\">50</sup> ראשון ואני אחרון כו' וד\"ל.\n<b>ובכל</b> הנ\"ל יובן מ\"ש שלח תשלח את האם וכתיב והאם רובצת על האפרוחי' כו' שאינם ב' ענינים הפכיים אלא הכל ענין א' הוא והא בהא תליא כו' דהנה מבואר למעלה דלעתיד יתעלה שם ב\"ן ויהי' בבחי' ס\"ג וזהו עטרת<sup data-n=\"2810\">51</sup> בעלה כו' והוא בחי' ס\"ג דבינה שהוא בחי' עלי' והסתלקו' דהיינו בבחי' הרוממות וההתנשאות בבחי' העצמות למעלה מעלה עד שאין כל ההשתלשלו' שנמשכו מן המדו' דז\"א בבי\"ע תופסים מקום כלל וכלל וכענין שממית בידים תתפש כו' וכמאמר שגוים<sup data-n=\"2811\">52</sup> מרקדין בהיכלו והוא שותק הן הן גבורותיו כו' שהוא מפני העדר תפיסת מקום כו' כמ\"ש במ\"א והוא בחי' פנימי' בינה הנק' עולם החירו\"ת יובלא עילא' שאין לחיצונים שרש ואחיז' שם כלל מפני עוצם הרוממות וכמ\"ש ואתה<sup data-n=\"2812\">53</sup> מרום לעולם ה' כי הנה אויבך יאבדו כו' וזהו וקראתם<sup data-n=\"2813\">54</sup> דרור לעבדים שיצאו חפשי מעבדו' לחיצונים דהיינו שלא יהיו נק' עבדים כידוע<sup data-n=\"2814\">*54</sup> שי' כתרין דנוגה נק' עבדים וכמ\"ש כי<sup data-n=\"2815\">55</sup> ימכור בתו לאמה לא תצא כעבדים כו' אלא יהיו נק' בני חורין כו' מפני שאז כתיב לא<sup data-n=\"2816\">56</sup> ירעו ולא ישחיתו כו' שיבטלו המזיקין שנאחזי' ממותרי הפסולת של הדינים הקשין שנמשכי' מהמדות דקדושה כו' כענין ארי'<sup data-n=\"2817\">57</sup> כבקר כו' וגר<sup data-n=\"2818\">58</sup> זאב עם כבש כו' כדוגמא שהי' בתיבת נח שהי' בכל החיות המזיקין בחי' ביטול וארי' כבקר היו שוין כו' לפי",[["2806","47","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["2807","48","<b>תבא האם ותקנח צואת בנה</b>: ראה במדב\"ר פי\"ט, ח. תנחומא חוקת ח."],["2808","49","<b>א\"ת אִם אלא אֵם</b>: פע\"ח (שער השבת) שי\"ח, פ\"ג."],["2809","50","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["2810","51","<b>עטרת בעלה</b>: משלי יב, ד."],["2811","52","<b>שגוים מרקדים בהיכלו. . הן הן גבורותיו</b>: ראה יומא סט, ב. ילקו\"ש נחמי' רמז תתרמא."],["2812","53","<b>ואתה מרום לעולם</b>: תהלים צב, ט."],["2813","54","<b>וקראתם דרור</b>: בהר כה, י."],["2814","*54","<b>כידוע שי' כתרין דנוגה נק' עבדים</b>: ראה ג\"כ תו\"ח ויצא קג, ב ובהערה 12."],["2815","55","<b>כי ימכור בתו לאמה</b>: משפטים כא, ז."],["2816","56","<b>לא ירעו ולא ישחיתו</b>: ישעי' יא, ט."],["2817","57","<b>ארי' כבקר</b>: ראה ישעי' יא, ז. סה, כה."],["2818","58","<b>וגר זאב עם כבש</b>: ישעי' יא, ו."]]],[2100490492,"שתיבת<sup data-n=\"2819\">59</sup> נח הי' מבחי' בינה שנק' עולם החירות ונח<sup data-n=\"2820\">60</sup> וג' בניו הוא בחי' יסוד אבא כו' וכמ\"ש במ\"א וד\"ל וזהו מצד הברורי' דרפ\"ח שנפלו בשם ב\"ן ועולי' לשרשם הקדום בבחי' ס\"ג כנ\"ל וזה יש בכל שבת קצת מעין זה בעליות העולמות כנ\"ל והיינו בחי' סוס הראשון שעולה מלמטה למעלה מעלה בבחי' עילוי אחר עילוי ברום המעלות והוא ענין ההתנשאו' והרוממות בכלל וזהו מ\"ש שלח תשלח את האם שיש בבחי' אם דהיינו בחי' בינה הסתלקות ועליו' שהוא בחי' ההתנשאות והרוממות ונק' עולם החירות כנ\"ל ובחי' סוס השני הוא שם ס\"ג השני בפרט בבחי' בינה עצמה שנמשך מזה הכח עצמו להיות יורד ונמשך למטה מטה מאד וכמבואר למעלה בענין בחי' מקיף של המדו' שהוא בעצמו הכח להיות נשפל כ\"כ לסבול גם הדבר השנאוי כו' ע\"ד שנא' ועברתי בארץ מצרים והכיתי כל בכור כו' אני ולא מלאך כו' משום דלפי ערך עומק רום ערך עומק תחת כנ\"ל וכמאמר תבא האם דוקא ותקנח צואת בנה כו' שדוקא עי\"ז נתהפך הרע מכל וכל ולכך יבטלו המזיקין כנ\"ל בתיבת נח וד\"ל.\n<b>וזהו</b> מ\"ש והאם רובצת על האפרוחים כו' דהיינו שיורדת ונמשכת עד למטה מטה מאד עד\"מ הגדפין דאם הרובצת על האפרוחים שמגינה עליהם עד גם מתחתיתם כו' והיינו ענין ופרוס עלינו סוכת שלומך כו' משום דמבחי' מקיף דאימא נעשה &lt;קנט&gt;\nבחי' לבוש לשמור כנ\"י מכל קטרוגי החיצונים גם בזמן הגלות שכנ\"י בתחתית המדריגה כמ\"ש יונתי<sup data-n=\"2821\">61</sup> בחגוי הסלע בסתר המדריגה כו' בע' שרים כמאמר גלו<sup data-n=\"2822\">62</sup> לאדום שכינה עמהם כו' אבל משום דקדב\"ה<sup data-n=\"2823\">63</sup> בגלותא דוקא אסתלק לעילא לעילא שהוא בחי' הרוממות וההתנשאות הנ\"ל שהוא בחי' פנימי' בינה שזהו המאמר דגוים מרקדין בהיכלו והוא שותק הן הן גבורותיו בחי' הסתלקות בעילוי אחר עילוי כו' כנ\"ל ע\"כ היא הנותנת דוקא שיוכל לירד ג\"כ מטה מטה גם להגין עליהם מכל צד מחיצונים ואדרבה בזמן הגלות הוא עיקר הזמן שמברר רפ\"ח שבנוגה לאהפכא חשוכא לנהורא מרע לטוב ממש עד שלעתיד כתיב לא ירעו ולא ישחיתו כו' והוא מובן יותר עפ\"י הנ\"ל בענין והכיתי כל בכור דכדי לכלות לגמרי צריך להיות דוקא ממקום הגבוה מן המדות והוא מבחי' ס\"ג דבינה שהוא בבחי' עלי' והסתלקות מן המדות והיינו ענין דקדב\"ה שהוא ז\"א אסתלק כו' והוא עצמו הכח בירידתו כ\"כ למטה כי הא בהא תליא דוקא וד\"ל וזהו שרש ענין הנ\"ל בענין שלח תשלח האם כו' שהוא בחי' השם דהוי' נקוד בניקוד אלקי' כו' וד\"ל.\n<b>וזהו</b> וקבל היהודים אשר החלו לעשות כו' דהנה ב' מיני סוס הנ\"ל הוא מ\"ש כי תרכב על סוסיך אזי מרכבותיך ישועה לכלות החיצוני' מבחי' אור אימא דוקא",[["2819","59","<b>שתיבת נח הי' מבחי' בינה שנק' עולם החירות</b>: ראה תו\"ח נח מו, א. נו, ג-ד. אוה\"ת נח ע' קצז."],["2820","60","<b>ונח וג' בניו הוא בחי' יסוד אבא</b>: ראה לקו\"ת להאריז\"ל בראשית ו, ח. ר\"פ נח."],["2821","61","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד."],["2822","62","<b>גלו לאדום שכינה עמהם</b>: ספרי בהעלותך י, לה. ס\"פ מסעי. מכילתא בא יב, מא. ועוד. וראה מגילה כט, א."],["2823","63","<b>דקדב\"ה בגלותא</b>: ראה זהר ויגש רי, א. בשלח נח, ב. ויקרא כ, א. אחרי עה, רע\"א."]]],[2100490493,"כו' והנה בזה מובן מ\"ש וסוס<sup data-n=\"2824\">64</sup> אשר רכב עליו המלך ולבוש מלכו' אשר לבש בו המלך כו' כי ע\"י הסו\"ס שהן ב\"פ ג\"ס בגי' ס\"ג שהן ב' שמות דס\"ג בבינה כנ\"ל דהא בהא תליא כו' הרי מובן שעי\"ז יוכל להיות סיבת קישור וחיבור האורו' בכלים הנק' לבושי' דהנה לבוש מלכו' ידוע שגם המצות נק' לבושי' והן נעשי' מברורי' דרפ\"ח כו' שנתבררו משם ב\"ן ועולי' הם לשרשם הקדום בבחי' ס\"ג הראשון דאימא שהוא בחי' עלי' והתנשאות כנ\"ל ע\"כ היא הנותנת דוקא שירדו האורות למטה מטה דהיינו בלבושים דמעשה המצות שכולן מבחי' נה\"י דאימא שיורדי' ומתלבשי' ונעשי' מוחי' לזו\"נ עד גם שיורדי' בבי\"ע והכל מבחי' נה\"י דאימא וזהו שנק' לבוש מלכות אשר לבש בו המלך שהוא בחי' אור אבא שנק' מלכא עילאה כידוע וד\"ל והיינו בחי' הסוס אשר רכב עליו המלך שהוא ב\"פ ס\"ג שעי\"ז ממילא יבא לבוש מלכות אשר לבש בו המלך והוא שם הוי' שבאימא שנא' בו והאם רובצת על האפרוחים כו' ולפי שכל המקיפים מבינה וכמבואר למעלה בענין והכיתי כל בכור כו' וניקוד אלקי' שבו הוא בחי' עלי' והסתלקו' שגורם ירידה זו אח\"כ והיינו כי תרכב על סוסיך כו' וד\"ל.\n<b>והנה</b> ידוע שכאשר נכנסו ישראל לארץ לא כבשו הכל בבת א' אלא מעט מעט כמ\"ש מעט<sup data-n=\"2825\">65</sup> מעט אגרשנו מפניך כו' וכל ימי השופטי' עד דוד ושלמה לא הי' כיבוש שלם וגם אח\"כ לא הי' שלוות ישראל בשלימו' מן אוה\"ע שסביבות א\"י כמבואר בכתובי' שלא הי' אפי' זמן אחד שהיו בנ\"י בתכלית השלימות העליון וגם בימי שלמה דאמרו בזוהר דקיימא<sup data-n=\"2826\">66</sup> סיהרא באשלמותא כו' עדיין לא היו במעלה העליונה האמיתי' כמו שיהי' לעתיד &lt;קס&gt;\nשהרי עדיין הי' אז שליטה גדולה לאוה\"ע אלא שהיו נכנעים לישראל ולא שנתבטלו ממציאותם לגמרי ע\"ד שיהי' לעתיד דכתיב ואת רוח הטומאה אעביר כו' והענין הוא לפי שגם בשעת קבלת התורה בהר סיני לא הי' בחי' תכלית שלימות המעלה בכנ\"י ואע\"פ שארז\"ל ישראל<sup data-n=\"2827\">67</sup> שעמדו בהר סיני פסקה זוהמתן כו' שהוא זוהמא<sup data-n=\"2828\">68</sup> של נחש הקדמוני אבל חזר קצת אותה הזוהמא בעון העגל וכמ\"ש ויתנצלו<sup data-n=\"2829\">69</sup> בני ישראל את עדיים מהר חורב ואע\"ג דמשמע דבשעת מ\"ת קיבלו העדיי\"ם בשלימות אבל הענין הוא דאותן העדיים המה בחי' ב' כתרים שנעשי' לז\"א ע\"י אור אימא וכמ\"ש בעטרה<sup data-n=\"2830\">70</sup> שעטרה לו אמו דהיינו דוקא בשעת מ\"ת כידוע ואותן העטרות והכתרים נתנו להם בשעה שאמרו נעשה ונשמע דוקא כידוע וענין נעשה ונשמע מבואר למעלה שהוא ענין הכנסת האורות בכלים שזהו פי' שמיעה<sup data-n=\"2831\">71</sup> לשון אסיפה וקיבוץ כו' ואין אסיפת האורות בכלים אלא ע\"י שאמרו נעשה שהוא בחי' כלים דרפ\"ח כו' וכנ\"ל מפני שהכלים שנעשים משם ב\"ן",[["2824","64","<b>וסוס אשר רכב עליו המלך</b>: אסתר ו, ח."],["2825","65","<b>מעט מעט אגרשנו מפניך</b>: משפטים כג, ל."],["2826","66","<b>דקיימא סיהרא באשלמותא</b>: שמו\"ר פט\"ו, כו. ועוד."],["2827","67","<b>ישראל שעמדו בהר סיני פסקה זוהמתן</b>: שבת קמו, רע\"א. זח\"א נב, ב."],["2828","68","<b>זוהמא של נחש הקדמני</b>: ראה שבת קמו, א. בחיי שמיני יא, ל."],["2829","69","<b>ויתנצלו בני ישראל</b>: תשא לג, ו."],["2830","70","<b>בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא. תענית כו, ב."],["2831","71","<b>שמיעה לשון אסיפה וקיבוץ</b>: ראה שמואל-א טו, ד. לקו\"ת האזינו עב, ב. שה\"ש מה, ב. מאמרי אדה\"א דברים ח\"ד ס\"ע א'קעד ואילך. ובכ\"מ."]]],[2100490494,"עולים לשרשם בבחי' ס\"ג דאימא והוא בחי' הכתר הראשון ואח\"כ בירידתו באותו הכח למטה והוא שם ס\"ג השני הוא בחי' כתר השני והכל בחי' אור אימא והיינו בעטרה שעטרה לו אמו כתר א' מבחי' אור חוזר וכתר השני מבחי' א\"י והכל מכח א' כי הא בהא תליא כנ\"ל.\n<b>וזהו</b> פי' עדיי\"ם שני כתרים, ואמנם לא הי' זה האור מן העטרות נכנס בכנ\"י בבחי' הכלים שלהם בהתיישבות גמורה אלא רק היה בבחי' כתר ומקיף עליהם בלבד שהרי לא עשו רק הכנה בנפשם לקבל המצות וכאמרם נעשה לשון להבא שהוא ענין העתיד כלומר שעתידים אנו לעשות כלים משם ב\"ן המתברר כו' וע\"כ גם העטרות שנעשי' מהם בבחי' מקיפי' דבינה כנ\"ל עדיין לא נכנס בהם בהכנסה והתיישבות גמורה אלא שהי' התעוררו' הכניסה בשלימות והי' האור מוכן ליכנס בנשמתם מעט מעט עד שהי' מתיישב האור בהם בהתיישבות גמורה כו' וזהו הטעם שלא הי' כיבוש א\"י בבת א' אלא מעט מעט כמ\"ש מעט מעט אגרשנו מפניך כו' כי למעלה עדיין לא הי' התיישבות האורות בכלים ממש בתכלית אלא רק התחלת הכניסה והי' נכנסי' מעט מעט כו' לכך למטה ג\"כ מעט מעט אגרשנו כו' ועד\"ז הי' האור הולך ונכנס מעט מעט בכללות נ\"י ע\"י מעשה המצות כל ימי השופטים והזקנים עד דוד ושלמה וגם בימיהם לא הי' שלימות התיישבות האורות בכלים למעלה עד לעתיד מפני שהי' עדיין יניק' לחיצוני' מזמן עון העגל וגם בשעת מ\"ת שפסקה מהן זוהמא של נחש כו' והיו כנ\"י בבחי' חירות משיעבוד מלכיות אם לא עון העגל כמארז\"ל חרות<sup data-n=\"2832\">72</sup> א\"ת חרות אלא חירות והוא בחי' יובלא עילאה דבינה הנ\"ל שנק' עולם החירות וכמ\"ש וקראתם דרור כנ\"ל מ\"מ לא הי' בחי' התיישבות האורות בכלים בהם בשלימות אלא רק שעשו הכנה בלבד לזה באמרם נעשה ונשמע כנ\"ל וע\"כ עדיין הי' מקום ושרש ליניקו' החיצונים ואע\"פ שמצד עצמם היו ראוי' שכבר הכינה נפשם באמרם נעשה אבל בחי' השמיעה הנ\"ל לא נתקיים מצד החטא דעגל וכו' ולכך נא' להם מעט מעט אגרשנו כו' עד לעתיד וד\"ל.\n&lt;קסא&gt;\n<b>וזהו</b> וקבל היהודים את אשר החלו לעשות, דבפורים נתקיים את אשר החלו לעשות בשעת מ\"ת דהיינו שאז הוא שנתיישב האור בכלי שלהם בתכלית ההתיישבות בבחי' עצמיו' בהם שלא יהי' כדוגמא זו רק לעתיד כנ\"ל וזהו את אשר החלו לעשות לפי שהי' ההתחלה של כניסת האורות בכלים בשעת מ\"ת והיו נכנסין מעט מעט כו' כנ\"ל עד שבזמן מרדכי ואסתר דוקא הוא שקבלו היהודים את אשר החלו לעשות בשעת מ\"ת וגמרו תכלית הכניסה הנ\"ל עד שנתיישבו האורות בכלים בתכלית וד\"ל. והטעם לזה למה בפורים דוקא זכו למדרגה גדולה כזאת שלא זכו כל ימי היותם בארץ כנ\"ל, הענין הוא מטעם מס\"נ<sup data-n=\"2833\">73</sup> שהי' להם כל אותה השנה כמבואר",[["2832","72","<b>חרות א\"ת חרות אלא חירות</b>: תשא לב, טז. אבות פ\"ו מ\"ב. שמו\"ר עה\"פ (פמ\"א, ז)."],["2833","73","<b>מס\"נ. . כל אותה השנה</b>: תו\"א צז, א. ד\"ה בלילה ההוא תשד\"מ ס\"ו ובהערה 56 (סה\"מ מלוקט ח\"ב ע' עב)."]]],[2100490495,"שם כו'. והנה מבואר שם דהיום<sup data-n=\"2834\">74</sup> לעשותם להכניס האורות בכלים ולמחר לקבל שכרם ושכר<sup data-n=\"2835\">75</sup> מצוה הוא המצוה עצמה דהיינו התיישבות האור בכלי כי הטעם מה שהכלי יסבול האור הוא מפני שהכלי שרשו מבחי' המקיפים דבינה כנ\"ל וזהו שהכלי יסובב האור שבתוכו וכמ\"ש נקבה<sup data-n=\"2836\">76</sup> תסובב גבר כו' וזה אינו כ\"א ע\"י בחי' מס\"נ בתחלה שהוא בחי' ביטול במציאות לגמרי מכל וכל אזי ישכון בו אור א\"ס כי אין אור א\"ס שורה גם במה שהוא קצת יש ודבר וזהו שבפורים הי' בהם התיישבות האורות בכלים מצד שהי' להם מס\"נ בתחלה והיינו מ\"ש ימי<sup data-n=\"2837\">77</sup> משתה ושמחה מפני שהי' האורות מתיישבים בכלים שלהם להיות נק' ימי משתה ושמחה משא\"כ כשאין הכלי סובל האור כמו שנא' בבכי<sup data-n=\"2838\">78</sup> יבאו כו' וכמ\"ש שם וזהו וקבל היהודים ע\"י בחי' הודאה שהוא בחי' ביטול (וגם באברהם לא הי' אור אהבה אלא ע\"י בחי' ביטול ולכך נק' אברהם<sup data-n=\"2839\">79</sup> אבר מ\"ה כידוע וד\"ל).",[["2834","74","<b>דהיום לעשותם. . ולמחר לקבל שכרם</b>: ואתחנן ז, יא. ראה עירובין כב, א."],["2835","75","<b>ושכר מצוה הוא המצוה עצמה</b>: אבות פ\"ד מ\"ב."],["2836","76","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["2837","77","<b>ימי משתה ושמחה</b>: אסתר ט, כב."],["2838","78","<b>בבכי יבאו</b>: ירמי' לא, ח."],["2839","79","<b>אברהם אבר מ\"ה</b>: ראה זהר בהקדמה ד, רע\"א."]]],[2100490496,"<h3>נוסח שני: ביאור ע\"פ וקבל היהודים</h3>\n<b></b><b>ביאור<sup data-n=\"2840\">1</sup> שני על התורה דפורים</b>\n<b>להבין</b> שרשם של הדברים הנ\"ל, הנה באברהם אע\"ה אמרז\"ל שקיים<sup data-n=\"2841\">2</sup> כל התורה עד שלא ניתנה ומהו ההפרש בין ישראל שקבלו תורה מסיני ובין אאע\"ה שקיימה עד שלא ניתנה ובין ענין וקבלו<sup data-n=\"2842\">3</sup> את אשר החלו לעשות כו'. והענין הוא דהנה ידוע ששורש רמ\"ח<sup data-n=\"2843\">4</sup> מ\"ע הם רמ\"ח אברין דמלכא הוא ז\"א דאצילות שכלול מרמ\"ח אברין וכלים בהיות מתגדל בבחי' גדלות דהיינו שתחילה הוא בחי' עיבור תלת<sup data-n=\"2844\">5</sup> כלילן גו תלת, ואח\"כ בבחי' קטנות ו\"ק ואח\"כ בבחי' גדלות שכלול מט\"ס וכאו\"א כלולה מט'<sup data-n=\"2845\">6</sup> פעמים ט' עולה פ\"א ויש בו ראש תוך סוף כלי פנימיות תיכוניות וחיצוניות הרי ג' פעמים פ\"א עולה רמ\"ג וה\"ח המגדילים אותם עולה רמ\"ח מ\"ע והרי הם הרמ\"ח פיקודין דעשה שנמשכה מרמ\"ח אברי ז\"א שהאורות דז\"א מלובשים בתוך רמ\"ח כלים שלו, וכמו\"כ המ\"ע הם בחי' הכלים להשראות האורות שנמשכים מאא\"ס ב\"ה ע\"י קיום האדם אותם.",[["2840","1","<b>ביאור שני על התורה דפורים</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 735 קכט, א.\nוראה לעיל ע' שפה הנחת כ\"ק אדה\"א."],["2841","2","<b>שקיים כל התורה</b>: משנה סוף קידושין."],["2842","3","<b>וקבלו את אשר החלו לעשות</b>: אסתר ט, כג."],["2843","4","<b>רמ\"ח מ\"ע הם רמ\"ח אברין דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא פ\"ד. רפכ\"ג."],["2844","5","<b>תלת כלילן גו תלת</b>: ראה זח\"ב נ, א. ע\"ח שער הכללים פ\"ג. פע\"ח שער חהמ\"צ פ\"א."],["2845","6","<b>מט' פעמים ט'</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"ו. הנסמן בשערי תשובה מב, ב הערה 13."]]],[2100490497,"<b>והנה</b> מודעת זאת דהאורות אין להם קיום בלעדי הכלים דהיינו כשמתלבשים בתוך הכלים אז מאירים בבחי' גילוי והשראה בתוכם להיותן נקראין בשם אורות מצד ההארה והגילוי וההתפשטות שלהם בתוך הכלים אבל זולתי הכלים אזי האורות מסתלקים למקורם עצם המאור אוא\"ס ב\"ה בבחי' העלם והתכללות שאז אינם נקראים בשם אורות כלל מצד התכללותן בעצם המאור בתכלית ההעלם והתכללות בלי פירוד והתחלקות כלל אבל כשנאצלים ממקורן עצם המאור ונתפשטו בתוך הכלים אז ניכר בהתפשטות וגילוי להיותם מתוארים בשם אורות וכמו עד\"מ האש היסודי השמימי שהוא תחת השמים ואעפי\"כ לא יאר הלילה והיינו מפני שעצם יסוד האש אינו בהיר ומאיר כ\"א עצם חשוך זולתי כשנאחז בכלי בפתילה או בעצים אז מבריק ומאיר מצד סיבת התפשטות והאחיזת בהכלי שהכלי גורמת סיבת הגילוי והתפשטות האור המאיר מעצם האש היסודי שנתפשט בה אבל בכלות השמן והפתילה או העצים אז מסתלק האור למקורו עצם היסוד האש השמימי שהוא עצם חשוך מצד העדרו מהכלי כו', ולכן אף בעוד הפתילה קיימת טבע אור הוא להלהיב למעלה למעלה בתנועות רו\"ש מצד שחפיצה להתכלל במקורה אש היסודי ולהפרד מהפתילה הוא הכלי שנאחזת בה כך חקרו חכמי הפילוסופים וצדקו דבריהם בזה. ומזה נוכל לצייר בשכלנו להבין דרך משל ומליצה למעלה מעלה בהאורות עליונים המתלבשים בתוך הכלים דע\"ס הנאצלים שעיקר הקיום של האורות והגילוי וההתפשטות שלהם עד שמתוארים מצד זה בשם אורות הוא מצד הכלים שנתפסין ומלובשים בתוכן אבל זולתי הכלים היו האורות מסתלקים למקורם עצם המאור החשוך אשר בו נאמר ישת<sup data-n=\"2846\">7</sup> חושך סתרו כנודע ולכן א\"א להיות קיום להאורות בלתי הכלים כנ\"ל וד\"ל.\n<b>והנה</b> זהו שאמרז\"ל קיים א\"א ע\"ה כל התורה עד שלא ניתנה דהיינו שורש הרמ\"ח מ\"ע שהם אברים וכלים דז\"א שבהן נתלבשו האורות דז\"א ואברהם הי' שורש נשמתו גבוה מאוד נעלה מבחי' ז\"א דאצילות ולכך נאמר בו ויסע<sup data-n=\"2847\">8</sup> הלוך ונסוע הנגבה לאתקשרא באתר' ונעשה נשמתו בעצמו בחי' כלי להשראות האורות דז\"א שהי' מתלבשים ברמ\"ח מצוות שהם הכלים דז\"א ולכן קיים התורה עד שלא ניתנה ונתלבשו האורות בכלים דרמ\"ח מ\"ע מצד היות נשמתו עצמה נעשה כלי קיבול לקבל האורות של רמ\"ח מ\"ע לתוכו זהו ע\"י הליכתו<sup data-n=\"2848\">9</sup> בקודש למעלה מעלה ברו\"ש שיעלו ויגיע למדריגה זו שיהי' נשמותיהן עצמן בחי' כלים ראוין לקבל שפע האורות דז\"א כו', ולכך נאמר וירד<sup data-n=\"2849\">10</sup> הוי' על הר סיני וירד דווקא למטה שירדו האורות דז\"א בסתר המדריגות להתלבש ברמ\"ח כלים הם רמ\"ח מ\"ע דנוגה דבי\"ע מצד שא\"א להיות קיום להאורות עצמן בלעדי הכלים וא\"א לקבל אותם זולתי ע\"י הכלים הם מ\"ע ע\"י הצדקה וכדומה ממשיך אור החסד עליו למטה וע\"י התפילין מוחין דז\"א כו'. וכמארז\"ל ולא<sup data-n=\"2850\">11</sup> ע\"ה חסיד, פי' חסיד הוא העובד מאהבה לה'",[["2846","7","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["2847","8","<b>ויסע הלוך ונסוע הנגבה</b>: לך לך יב, ט."],["2848","9","<b>הליכתו. . ברו\"ש</b>: ראה זהר לך פ, א. פד, א."],["2849","10","<b>וירד הוי' על הר סיני</b>: יתרו יט, כ."],["2850","11","<b>ולא ע\"ה חסיד</b>: אבות פ\"ב מ\"ה."]]],[2100490498,"שנמשך אחריו כמים באהבה וחסד שמפני זה נק' בשם חסיד זה א\"א להמצא בע\"ה הריקני מהתורה ומצוות שלא אפשר להיות מתקיים בחי' אור האהבה והחסד לה' בלי כלי הם המצות מעשיות ועסק התורה שבהן דווקא נתלבשו האורות עליונים וכל האורות שמאירים בלב כנ\"י להאיר בלבבם באור האהבה או היראה נמשך הוא ונסתעף מבחי' האורות המלובשים בהכלים של המצוות דווקא לכן הע\"ה הריק מתו\"מ א\"א לו להיות חסיד כי מאין תמצא בו אור האהבה מאחר שאינו מלובש בכלי המצוות ובלעדי הכנת הכלים א\"א להגיע לאורות המלובשים בהם כנ\"ל.\n<b>עקב</b> אברהם רוח אחרת היתה עמו שהיתה נשמתו מז\"א דאצילות ונעשה הוא בחי' כלי להשראת האורות עליונים דז\"א בנשמתו שנסעה ממטה למעלה בבחי' רו\"ש כמ\"ש הלוך ונסוע הנגבה וד\"ל. ולכך אמרו ישראל מקודם<sup data-n=\"2851\">12</sup> נעשה ואח\"כ נשמע כי תחילה צריך להמשיך שפע האורות עליונים שיתלבשו בתוך הכלים דז\"א שלמטה הם רמ\"ח מ\"ע אברין דמלכא שזה מ\"ש וירד ה' על הר סיני כו' ואז ונשמע בחי' מקבל השפע של האורות הנמשכים מבחי' הכלים דווקא ע\"י קיום המצוות מעשיות דווקא משא\"כ בלעדי זאת א\"א האורות עצמן ממקורם טרם התלבשותן בתוך הכלים כ\"א מבחי' הכלים הם נשפעים לבי\"ע ע\"י אתעדל\"ת בהכלים שלמטה כנ\"ל וד\"ל.\n<b>אך</b> יש עוד טעם שני לסיבת הצטרכות הכנות הכלים שלמטה בקיום המצוות מעשיות קודם המשכות האורות שלזאת הקדימו נעשה לנשמע וכן מארז\"ל ולא ע\"ה כו' זולת הטעם הראשון והיינו בהיות ידוע ששורש המצות מעשיות שנלקחים מנוגה דבי\"ע הוא מבחי' שם ב\"ן דאצי' שנפלו בו הניצוצין דתוהו דרך שבירה משם ס\"ג דתוהו וכידוע מ\"ה דתיקון הוא המברר את רפ\"ח ניצוצין דב\"ן להחזירן לשרשן שם ס\"ג כמקדם השבירה. והנה בעולם האצי' נעשה היחוד והתכללות דמ\"ה וב\"ן ביחוד אמיתי שעי\"ז מתבררים הניצוצין מב\"ן וחוזרים בבחי' מ\"ן לשרשם שם ס\"ג שאז לאחר ששבים לשרשם שם<sup data-n=\"2852\">13</sup> ס\"ג הם למעלה משם מ\"ה המברר בסוד אשת חיל עטרת בעלה, שהמתברר מתעלה להיות עטרת בעלה שם מ\"ה המברר כנודע, אך זהו ההפרש בין אצילות לבי\"ע שעולם האצילות הוא כלול מהמזיגות והיחוד והתכללות דמ\"ה וב\"ן יחדיו כנ\"ל, משא\"כ בי\"ע שכל עיקר התהוותם הוא מבחי' שם ב\"ן דאצילות מקורם בחי' רמ\"ח ניצוצין דתוהו שנפל בו דרך שבירה ששרשם הוא שם ס\"ג שלמעלה משם מ\"ה כנ\"ל.\n<b>ועם</b> כ\"ז יובן היטב הטעם השני שמצטרך להכנות הכלים של המ\"ע טרם השמיעה והבנה הוא קבלת האורות לתוכן שזהו שאמרו נעשה דווקא והדר ונשמע (כמו וישמע<sup data-n=\"2853\">14</sup> שאול, הסכת<sup data-n=\"2854\">15</sup> ושמע כו') וכן כוונת רז\"ל באמרם ולא ע\"ה חסיד זולת הטעם הראשון מצד שהאורות אין להם קיום בלעדי הכלים כי לא זו בלבד מצד שהאורות",[["2851","12","<b>מקודם נעשה ואח\"כ נשמע</b>: ראה משפטים כד, ז."],["2852","13","<b>שם ס\"ג הם למעלה משם מ\"ה</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"א."],["2853","14","<b>וישמע שאול</b>: שמואל-א טו, ד."],["2854","15","<b>הסכת ושמע</b>: תבוא כז, ט."]]],[2100490499,"שיהי' להם כלים שיתלבשו והם היו נמשכין אליהם מהכלים עליונים שנתלבשו בהן האורות דווקא מה דלא סגי בלא\"ה כנ\"ל, שגם זה אמת אלא אף זו שמצד הכנת הכלים שלמטה במ\"ע שנלקחים מבירורי נוגה דבי\"ע ששרשם מב\"ן דאצילות שנפלו בו דרך שבירה מס\"ג יגיעו לתוס' אורות יותר מהגיעתם להאורות עצמן כי האורות הנעלמים בהכלים דהיינו גודל עוצם מעלות שרשו הוא הגבה שלמעלה אפי' מבחי' האורות המלובשים בתוכם ולכך יקר מעלת הכלים עצמן על האורות שבהן מצד שרשם עד שהוצרכו ישראל להקדים נעשה לנשמע ולזה אמחז\"ל ולא ע\"ה חסיד שאף שיש בו אור האהבה והחסד המסותרת בלבבו אך הוא פחות הערך לגבי האורות הנעלמים בהכלים דתו\"מ ומאחר שהוא ריק מתו\"מ לא נחשב למאומה בחי' אור האהבה הפשוטה בלי כלי שכפי שיעור ערך נפשו ורוחו ונשמתו בלבד וד\"ל.\n<b>והנה</b> ע\"פ הקדמה זו בסידור ב' הטעמים שונים בשבח הכלים שורש המ\"ע יובן היטב ענין ההפרש בין ב' בחי' סוסים (שנז'<sup data-n=\"2855\">16</sup> לעיל בתורה דפורים) כמ\"ש כי<sup data-n=\"2856\">17</sup> תרכב על סוסיך מרכבותיך ישועה דכולא חדא מלתי' היא והיינו הך דהיינו שהטעם הראשון שנזכר בשבח הכלים מצד קיום אורות עליונים שאין להם קיום בלתי התלבשותן בתוך הכלים ולכן הוצרכו ישראל להקדים נעשה לנשמע בכדי שיוכנו הכלים העליונים דז\"א שיתלבשו האורות בהן דז\"א ולאחר התלבשותן בכלים דז\"א דאצילות נמשכים האורות מתוך הכלים דז\"א דווקא לנש\"י דבי\"ע להתלבש בהכלים גשמים דבי\"ע במ\"ע אברין דמלכא כו', זהו בחי' ומדריגת הסוס הא' מלמטה למעלה בבחי' עלי' הגבה למעלה לשורש שרשן של המצוות שבהן מלובשים אורות עליונים לשורש שרשן בחי' שם ס\"ג דאצילות שהוא בחי' בינה<sup data-n=\"2857\">18</sup> ונק' יובל עלמא דחירו דכתיב דרור יקראו דחירות ממה\"מ חירות משיעבוד למל' מפני ששם אין החיצונים יכולים לינק כי השבירה הי' בז' תחתונות בלבד אבל לא בג\"ר שא\"א להם לינק ולהגיע שם מצד שדוחה ומסמא עיני החיצונים כי מבינה<sup data-n=\"2858\">19</sup> דינין מתערין מינה והיא בעצמה כולא רחמים דהיינו שהיא בחי' שם הוי' בניקוד אלקים שבעצמה היא מלאה רחמים וחסדים אך רק נשמות ישראל בלבד אבל לא לאוה\"ע והחיצונים היא בבחי' דין וגבורה שזהו הניקוד שבשם אלקים<sup data-n=\"2859\">20</sup> שממדת הגבורה (העצם הוא בחי' שם הוי' בחי' רחמים (וכמ\"ש<sup data-n=\"2860\">21</sup> בזוה\"ק פ' אחרי מות ע\"ש וכמ\"ש במ\"א).\n<b>וביאור</b> הענין דהנה כתיב בקן צפור והאם<sup data-n=\"2861\">22</sup> רובצת על האפרוחים כו' שלח<sup data-n=\"2862\">23</sup> תשלח את האם והבנים תיקח לך, והיינו כי בינה נק' בשם אלקים חיים",[["2855","16","<b>(שנז' לעיל בתורה דפורים)</b>: ע' רמז."],["2856","17","<b>כי תרכב על סוסיך</b>: חבקוק ג, ח."],["2857","18","<b>בינה ונק' יובל עלמא דחירו</b>: נסמן לעיל ע' שצ."],["2858","19","<b>מבינה דינין מתערין מינה</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א."],["2859","20","<b>אלקים שממדת הגבורה</b>: ראה זהר יתרו פג, ב. וראה לקו\"ת תזריע כג, ג. ובהנסמן שם בהמ\"מ."],["2860","21","<b>וכמ\"ש בזוה\"ק פ' אחרי מות</b>: סה, א. וראה זהר ויקרא יא, א. רש\"י ר\"פ בראשית."],["2861","22","<b>והאם רובצת על האפרוחים</b>: תצא כב, ו."],["2862","23","<b>שלח תשלח את האם</b>: תצא שם, ז."]]],[2100490500,"שזהו ב' הפכים תרתי דסתרי אהדדי כי אלקים הוא מדת הדין שהוא בחי' הסתלקות למעלה וחיים היא בחי' המשכה והתפשטות החיים למטה, אך באמת שניהם אמת ויתכונו בבחי' בינה דאצילות אם הבנים הם המדות דאצילות שנק' בנים כידוע והיינו שיש בה בחי' הגבורה והסתלקות למעלה ובחי' התפשטות למטה בבחי' חסדים זה לישראל וזה לאוה\"ע ולכן נק'<sup data-n=\"2863\">24</sup> אלקים וחיים, וזהו שלח תשלח את האם זהו הסתלקות שלה למעלה שלא ינקו החיצונים כנ\"ל, והאם רובצת על האפרוחים זהו לנשמות ישראל דכתיב אם<sup data-n=\"2864\">25</sup> הבנים שמחה שהיא מתפשטת בבחי' השראה ורביצה על האפרוחים שהוא מקור החיים שלהם ולכך הוי' בנקוד אלקים כנ\"ל, וכ\"ז יגיע כנ\"י אליה ע\"י הכלים דתומ\"צ מעשיות שנלקחו מבירורים דרפ\"ח ניצוצין דב\"ן שמתבררים ע\"י מ\"ע וחוזרים לשרשן בחי' שם ס\"ג הוא בינה דאצילות בבחי' או\"ח והעלאת מ\"ן זהו הסוס הא' העולה מלמטה למעלה כי סוס<sup data-n=\"2865\">26</sup> בגימטרי' ב\"פ ס\"ג כנ\"ל, וכ\"ז השיגו ישראל ע\"י אמירתם נעשה ונשמע שירד הוי' על ה\"ס בירידה דווקא שיתלבשו האורות בכלים שאז בהכנות הכלים להאורות שישרו בהם יתעלו הכלים למעלה בשרשם שם ס\"ג כי כל העולמות הם בבינה דאצילות כנודע משא\"כ בלעדי הכלים לא היו מגיעין בהאורות עצמן שבהן לשם ס\"ג עלמא דחירות כו' אבל א\"א ע\"ה עקב רוח אחרת היתה בו שהיתה נשמתו מז\"א דאצילות נעשית היא בחי' כלי ראוי' לקבל שפע האורות ועלה ממדריגה למדריגה הלוך ונסוע עד הגעתו לשם בעצמו בלא הכלים שלמטה לכן אמרז\"ל קיים אאע\"ה כל התורה כולה עד שלא ניתנה אפי' ערוב תבשילין מצד הגעתו לשורש המצוות מלמטה למעלה ברו\"ש מה שלא היו מגיעים בנ\"י כ\"א ע\"י המ\"ע דווקא לשרשם כנ\"ל וד\"ל.\n<b>אך</b> הסוס השני הוא הסוס<sup data-n=\"2866\">27</sup> אשר רכב עליו המלך שנמשך מלמעלה למטה בבחי' ירידה גדולה משם ס\"ג לבחי' עשי' שלמטה זהו מצד בחי' הטעם השני שנת' לעיל ובזה אמרז\"ל באאע\"ה היפוך הענין שלא ניתנה התורה לו מצד שיצא ממנו ישמעאל כנ\"ל ואין זה סותר למה שנת' לעיל.\n<b>והענין</b> הוא דהנה שם ס\"ג הוא שורש כל המקיפים כי כל המקיפים נמשכים מבינה הוא שם ס\"ג דאצילות והיינו דכאשר צריך להעביר<sup data-n=\"2867\">28</sup> רוח הטומאה ואת הקליפות והחיצונים מן הארץ לגמרי להיות שובר<sup data-n=\"2868\">29</sup> אויבים ומכניע זדים לגמרי אא\"ל זאת בלתי המשכות המקיפים דווקא משם ס\"ג שורש המקיפים למטה להעבירם מן הארץ שזהו הכלל שכל<sup data-n=\"2869\">30</sup> דבר היותר גבוה יורד במורד יותר למטה",[["2863","24","<b>נק' בשם אלקים וחיים</b>: ראה זהר יתרו סח, ב ובהגהות הרח\"ו שם."],["2864","25","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["2865","26","<b>סוס בגימט' ב\"פ ס\"ג</b>: נסמן לעיל ע' שפט."],["2866","27","<b>הסוס אשר רכב עליו המלך</b>: אסתר ו, ח."],["2867","28","<b>להעביר רוח הטומאה</b>: זכרי' יג, ב."],["2868","29","<b>שובר אויבים ומכניע זדים</b>: תפלת שמו\"ע."],["2869","30","<b>שכל דבר היותר גבוה יורד. . למטה</b>: ראה תו\"ח בראשית כה, א ”הכלל בכ\"מ שכל הגבוה\". פא, ד ”כלל א' הידוע\". וראה שערי אורה שער הפורים נח, א. סה, א. סה\"מ מלוקט ח\"א ע' סז. וראה מאמרי אדה\"א שמות ח\"ב ע' שמח ”כלל הגדול בכ\"מ\". נביאים וכתובים ע' עט וע' קמה. ובכ\"מ. וראה לקמן ע' תח הערה 40."]]],[2100490501,"כמשל הלבינה הנופלת מראש החומה שנופלת בריחוק מקום מאוד למטה הריחוק יותר מנפילת הלבינה שבשיפולי החומה שנופלת<sup data-n=\"2870\">31</sup> מקרוב סמוך לחומה כמ\"ש במ\"א וכמארז\"ל ועברתי<sup data-n=\"2871\">32</sup> בארץ מצרים אני ולא מלאך כו' אלא הקב\"ה בכבודו ובעצמו ירד למצרים דהיינו מפני שמצרים<sup data-n=\"2872\">33</sup> היתה ערות הארץ ומצטרך להכניע את רוח הטומאה והקליפה ולהעבירנה מן הארץ לגמרי לשבור אויבים ולהכניע זדים ירד הקב\"ה הם המקיפים דס\"ג בעצמו למצרים להכניע הזדים ע\"י מכות בכורות כמ\"ש והכה<sup data-n=\"2873\">34</sup> הוי' את כל בכור בארץ מצרים כו' וכתיב וסכסכתי<sup data-n=\"2874\">35</sup> מצרים במצרים מפני שהמקיפים עליונים דווקא מצד שהם נעלים וגבוהים מאוד נעלה יכולים להיות נשפלים במורד למטה מטה להקיף אפי' את העורף דקליפה בכדי להעבירם מן הארץ כמ\"ש ידך<sup data-n=\"2875\">36</sup> בעורף אויביך כמשנ\"ת לעיל.\n<b>והגם</b> שאפי' הפנימים יכולים לישפל כ\"כ למטה בהשרים עליונים לברר בירורים כמו יום ראשון נשפל מדת החסד שבחסד כו', הנה ירידתו הוא רק ללקוט ניצוצי הטוב שבהן ולברר בירורים אבל לכלותם ממש א\"א בלעדי שיקיפו אותם מאחורי העורף וזה א\"א להאור פנימי לשפול כ\"כ למטה זולתי להמקיפים דס\"ג כמ\"ש ועברתי בארץ מצרים כו' וכמ\"ש אם<sup data-n=\"2876\">37</sup> רחץ ה' את צואת בנות ציון א\"ת<sup data-n=\"2877\">38</sup> אִם אלא אֵם רחץ כמרז\"ל תבוא<sup data-n=\"2878\">39</sup> אמו ותקנח את בנה דהיינו אימא עילאה שם ס\"ג בינה דאצילות רחץ ומטהר לנקות ולקנח את צואת הארץ להעביר את רוח הטומאה מן הארץ לגמרי לשבור אויבים ולהכניע זדים כנ\"ל, וזהו בחי' הסוס השני אשר רכב עליו המלך למטה להעביר רוח הטומאה מן הארץ המשכת המקיפים מבחי' שם ס\"ג דאצילות למטה להיות ידך אף בעורף אויביך כו' שבזה יזכו ישראל ע\"י הכלים דמ\"ע עצמם מצד שרשם שהם למעלה מהאורות ששרשם הוא ס\"ג וזה יהי' לע\"ל שתהי' אשת חיל עטרת בעלה אז רוח הטומאה יעבור כנ\"ל ובזה אמרז\"ל שלא ניתנה התורה לאברהם מפני שיצא ממנו ישמעאל כי מהמדות דז\"א דאצי' יכולים החיצונים לינק כמו אברהם שהוא חסד דז\"א יצא ממנו ישמעאל שהוא חסד דקליפה ומכ\"ש וק\"ו שאין המדות יכולים לשפול למטה להיותם מעבירים את רוח הטומאה של הקליפות למטה כו' משא\"כ המקיפים דס\"ג נשפלים למטה יותר להקיף בעורף אויביך להכניע זדים ולהעבירם מן הארץ לגמרי ולכן מצד זה לא ניתנה תורה לאברהם כו' אבל מצד טעם הראשון שהוא קיום האורות שא\"א להתקיים בלתי הכלים שעי\"ז יתעלו",[["2870","31","<b>שנופלת מקרוב סמוך לחומה כמ\"ש במ\"א</b>: ד\"ה וידבר משה אל ראשי המטות בסה\"מ תקס\"ב ע' רלז ואילך. וראה ג\"כ דרך מצותיך קד, א ”וכנודע המשל\"."],["2871","32","<b>ועברתי בארץ מצרים אני ולא מלאך</b>: בא יב, יב. ספרי תבוא כו, ח. זהר (מהנ\"ע) וירא קיז, א. הגש\"פ."],["2872","33","<b>שמצרים היתה ערות הארץ</b>: ראה מקץ מב, ט. וראה קה\"ר פ\"א, ד."],["2873","34","<b>והכה הוי' את כל בכור</b>: ראה שמות בא יב, כט."],["2874","35","<b>וסכסכתי מצרים במצרים</b>: ישעי' יט, ב."],["2875","36","<b>ידך בעורף אויבך</b>: ויחי מט, ח."],["2876","37","<b>אם רחץ ה' את צואת בנות ציון</b>: ישעי' ד, ד."],["2877","38","<b>א\"ת אִם אלא אֵם</b>: פע\"ח (שער השבת) שי\"ח, פ\"ג."],["2878","39","<b>תבוא אמו ותקנח את בנה</b>: ראה במדב\"ר פי\"ט, ח. תנחומא חוקת ח."]]],[2100490502,"למעלה בשם ס\"ג שהוא סוס הראשון קיים אאע\"ה ג\"כ בלתי הכלים שהלוך ונסוע הנגבה וזכה להאורות עצמן בלתי הכלים מצד שורש נשמתו כו' אבל מצד מעלת הכלים על האורות לא השיג אאע\"ה שלא היו לו כלים כו' וד\"ל.\n<b>וביאור</b> הענין מבשרי<sup data-n=\"2879\">40</sup> אחזה עד\"מ בנפש האדם נראה בעליל שהמחשבה מקפת כל אברים מראשו ועד רגלו שאף בהרגל תתפשט המחשבה לפעול פעולת רצונה בהילוך ועמידה ובעיטה כנ\"ל וכן הרגשת הכאב מציפורן רגלו כו' וכדומה ובזאת ניכר ונראה שהמקיף מתפשט יותר במורד למטה מהאו\"פ דהיינו שהמדות בנפש א\"א להם להתפשט כ\"כ במורד כמו המחשבה והיינו כמו מדת האהבה א\"א לה להתלבש ולהתפשט זולתו בדבר הנחמד והאהוב לו שבדבר ההוא תתפשט המדה לאהוב הדבר ההוא ולהיותו כל מגמתה אל הדבר ההוא אבל הדבר השנאוי לו ההיפוך אל המדה א\"א שתתפשט בו ולהתלבש בו כלל כי מאחר שהוא מנגד והיפוך אלי' שהוא שנאוי ומאוס לו כו' משא\"כ המחשבה שיוכל להתפשט יותר למטה אף בדבר שחוצה לו שאין לו שייכות אליו כלל ואפי' בדבר השנאוי לו ההיפוך ומנגד לטבעו שאעפי\"כ יכול לחשוב באותיות המחשבה הדבר השנאוי ההוא ומכ\"ש הדבר שחוצה לו שאין לו שייכות אליו (כמו ענין אחר שאין בו אהבה ושנאה כו') מה שאין זה ביכולת המדה להתלבש אף בדבר שחוצה לה שאין לו בה אהבה וחשק ומכ\"ש שאין באפשרי לה להתלבש בההפכי לה המנגד לה הוא הדבר השנאוי והמאוס כו', והסיבה הוא מפני שהמחשבה הוא בחי' מקיף לכך יכולים לשפול במורד למטה יותר להקיף אפי' דבר השנאוי והמאוס כו' והמנגד לטבעה שאעפי\"כ היא מהרהרת באותיות המחשבה ומכ\"ש הדבר שחוצה לו משא\"כ המדה שהיא בחי' או\"פ שאינה יכולה לשפול במורד אפי' בדבר שחוצה לה זולתי בדבר שקרוב אלי' האהוב והנחמד לה כו' ומכ\"ש בההיפוך ומנגד אלי' כו' כך עד\"מ למעלה דכתיב ואת<sup data-n=\"2880\">41</sup> עשיו שנאתי אך בחי' המקיפים דס\"ג יכולים לישפל במורד למטה להקיף אפי' עורף אויביך אף ששונאים לו בכדי להעבירם מן הארץ כו' משא\"כ המדות דז\"א שאין יכולים לישפל כ\"כ למטה להקיף אותם כו' כנ\"ל וד\"ל.\n<b>וזהו</b> וקיבל היהודים את אשר החלו לעשות כו' פי' שעד ימי הפורים לא הי' להם פנאי עדיין שיקבלו לתוכן השפע במה שהתעוררו והתחילו לעשות בזמן מ\"ת מפני שמזמן מ\"ת עד ימי הפורים היו תמיד בצרות גדולות שלא היו במעלה העליונה כמו העגל דמדבר ופסל מיכה ועגל זהב חטא ירבעם כו' עד ימי הפורים שעשו תשובה נכונה ומסרו נפשם על קדוה\"ש בתכלית הביטול האמיתי עד שנקראו בשם יהודים מלשון יהודא הפעם<sup data-n=\"2881\">42</sup> אודה את ה' שהוא תכלית הביטול בבחי' מה שזכו לבחי' אברהם אבר<sup data-n=\"2882\">43</sup> מ\"ה ובתוס' הכלים שעשו בקיום המצוות מה שלא היו",[["2879","40","<b>מבשרי אחזה</b>: ל' הכתוב איוב יט, כו."],["2880","41","<b>ואת עשו שנאתי</b>: מלאכי א, ג."],["2881","42","<b>הפעם אודה את ה'</b>: ויצא כט, לה."],["2882","43","<b>אברהם אבר מ\"ה</b>: ראה זהר בהקדמה ד, רע\"א."]]],[2100490503,"באברהם כו' ולכך וקיבלו היהודים את השפע לתוכן שנקלט' בתוכן ממש, והיינו את אשר החלו לעשות במ\"ת שהקדימו נעשה לנשמע כו' וד\"ל."],[2100490504,"<h3>להבין ענין מה שארז\"ל אין אדם עובר עבירה</h3>\n<b>להבין</b><sup data-n=\"2883\">1</sup> ענין מה שארז\"ל אין<sup data-n=\"2884\">2</sup> אדם עובר עבירה אא\"כ נכנס בו רוח שטות כו' דהנה אנו רואים בחוש בכל דבר תאוה שיתאוה האדם הנה הגם שיהי' האדם חכם גדול בשאר הדברים יעשה שטותי' גדולי' באותו הדבר שמתאווה בו וחכמתו מסתלקת ממנו בהכרח בשעה שמתאוה לאותו הדבר יהי' הענין איך שיהי' אם במילי דעלמא אם במילי דשמיא וכו' בהכרח שיעשה שוטה לאותו הדבר באותה השעה וזה הדבר מנוסה בכל האנשי' וגם לחכמים גדולים יגיע ערך השטות בזה כמו לטפשים כאשר יעיין האדם בזה.\n<b>ולכאורה</b> יפלא דבר זה מאיזה טעם יסתלק שכלו בענין ההוא שמתאוה לו כו' אך הענין הוא לפי שנעשה האדם המתאווה אותה תאוה בחי' נוקבא לגבי אותו הדבר שמתאוה לו שהרי הוא רוצה לקבל תענוג ממנו וא\"כ הרי הוא בחי' מקבל והדבר שמקבל ממנו העונג הוא בחי' דכר משפיע וכלל גדול הוא שכל בחי' מקבל אין לו דעת שלם כידוע מארז\"ל דנשים<sup data-n=\"2885\">3</sup> דעתן קלות והוא מפני שהם בחי' מקבלי' וע\"כ בהכרח שיעשה שטות באותו הדבר &lt;קסב&gt;\nשמתאוה לו כי אין דעתו בשלימותו באותה השעה שמתאוה לאותו הדבר כי נעשה בחי' נוק' בחי' מקבל באותה השעה כו' וד\"ל והיינו מ\"ש אשרי<sup data-n=\"2886\">4</sup> איש ירא את ה' וארז\"ל אשרי<sup data-n=\"2887\">5</sup> איש ולא כשהוא אשה בחי' נוק' דגם במילי דשמייא יובן עד\"ז שכאשר הוא בחי' נוק' בעבודת ה' אין דעתו שלם בגדולת הבורא דהיינו ההתבוננות כו' וכמ\"ש וידעת<sup data-n=\"2888\">6</sup> היום והשבות כו' וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> שאין אדם עובר עבירה אא\"כ נכנס בו רוח שטות כי אחרי שמתאוה תאוה בהכרח שיבא בו רוח שטות מטעם הנ\"ל ורוח השטות הזה הוא המביא בו בחי' שכחה לשכוח על ה' שהוא היפך הדעת שהוא ההתקשרות בכח השכל בלתי נטיי' לעולם ונשים שדעתן קלות היינו שאין בהם בחי' התקשרות בכח השכל ונוחין לכך להתפתו' להיות נוטין מכח השכל וכדוגמא זו בכל אדם שעובר עבירה דעתו קלה באותה השעה והוא רוח השטות וד\"ל.\n&lt;קסג&gt;",[["2883","1","<b>להבין ענין מה שארז\"ל</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק (1025 לג, א). לענינים המבוארים במאמר זה ראה ג\"כ מאמרי אדמו\"ר האמצעי הנחות תקע\"ז ע' שכג."],["2884","2","<b>אין אדם עובר עבירה</b>: סוטה ג, א."],["2885","3","<b>דנשים דעתן קלות</b>: שבת לג, ב. וראה לקו\"ש חי\"ז ע' 149."],["2886","4","<b>אשרי איש ירא את ה'</b>: תהלים קיב, א."],["2887","5","<b>אשרי איש ולא כשהוא אשה</b>: ע\"ז יט, א."],["2888","6","<b>וידעת היום והשבות</b>: ואתחנן ד, לט."]]],[2100490505,"<h3>אם בחוקותי תלכו</h3>\n<b></b><b>בעזר\"ה שבת פ' בחוקותי</b>\nשבת פ' בחוקותי\n<b>אם</b><sup data-n=\"2889\">1</sup> בחוקותי תלכו ואת מצוותי תשמרו כו' ונתתי גשמיכם בעתם<sup data-n=\"2890\">2</sup> כו' עץ השדה יתן פריו והארץ תתן יבולה כו', הנה ארז\"ל ע\"פ זה אם בחוקותי תלכו הלואי<sup data-n=\"2891\">3</sup> בחוקותי תלכו כדכתיב לו<sup data-n=\"2892\">4</sup> הקשבתם למצותי כו' בהיות ידוע שיש בפי' ואהבת<sup data-n=\"2893\">5</sup> ב' ענינים א' ענין ציווי שמצווה שיאהוב באהבה והב' לשון עתיד והוא ענין הדבר הבא ממילא דהיינו שעתיד לאהוב ממילא* כו'.\n<b>וביאור</b> ענין ב' האהבות הנ\"ל הנה האהבה שאמר עליה לשון<sup data-n=\"2894\">6</sup> ציווי היא האהבה הנולדה מצד ההתבוננו' באחדו' ה' וכמו שהקדים לומר שמע<sup data-n=\"2895\">7</sup> ישראל כו' פי' שמע לשון ציווי הוא על ההתבוננו' כי שמע לשון הבנה הוא כידוע בפי' כי<sup data-n=\"2896\">8</sup> שומעי' אנחנו כלומר מבינים כו' וההתבוננו' הוא איך שה' אלקינו ה' אחד פי' אח\"ד ידוע אלף<sup data-n=\"2897\">9</sup> דאחד הוא אלופו של עולם אשר במחשבה<sup data-n=\"2898\">10</sup> אחת ברא ז'<sup data-n=\"2899\">11</sup> רקיעי' והארץ היינו חי\"ת<sup data-n=\"2900\">12</sup> והדלי\"ת הם ד' רוחות העולם כידוע ומזאת ההתבוננו' נולד ממילא האהבה באמרו ואהבת כו', והנה כל הפסוקי' דעד ק\"ש הוא רק אריכות ההתבוננו' בגדולת ה' והוא ענין אריכות דאחד בכדי שבק\"ש יוכל להתפעל באהבה כו' ולכאורה אינו מובן לאיזה טעם צריכה הנשמ' האלקי' לכל זה האריכו' הלא קודם",[["2889","1","<b>אם בחוקותי תלכו</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק (1025 מב, א). ובכת\"י הנ\"ל ע' קצז נמצא הגהות כ\"ק אדמו\"ר הצ\"צ על מאמר זה.\nואחר כך רשום עוד פעם הגהות בגוכתי\"ק אדמו\"ר הצ\"צ מסעיף ג' ואילך — והכוונה היא למעתיק איך לסדר גוף המאמר עם הגהות שלו — ומאמר זה נדפס באוה\"ת ויקרא כרך ב ע' תרלד ואילך. ושם ע' תשטו (וכמה הגהות הם כמו שנדפסו כאן). ומחולק לאותיות בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ.\nמאמר זה באריכות מכ\"ק אדה\"א נדפס במאמרי אדה\"א בחוקותי ע' תשלו ואילך."],["2890","2","<b>אם בחוקותי. . בעתם</b>: בחוקותי כו, ג-ד."],["2891","3","<b>הלואי בחוקותי תלכו</b>: ראה ע\"ז ה, סע\"א. איכ\"ר פתיחה ב."],["2892","4","<b>לו הקשתם למצותי</b>: ראה ישעי' מח, יח: לוא הקשבתם."],["2893","5","<b>ואהבת</b>: ואתחנן ו, ה."],["2894","6","<b>לשון ציווי. . האהבה</b>: ראה דרך מצותיך קצט, א."],["2895","7","<b>שמע ישראל</b>: ואתחנן ו, ד."],["2896","8","<b>כי שומעי' אנחנו</b>: מלכים-ב יח, כו."],["2897","9","<b>אל\"ף דאחד הוא אלופו של עולם</b>: בסידור שער הק\"ש: כמ\"ש בטור [הל' ק\"ש סס\"א. וראה בדרכי משה שם]. ובסה\"מ תקס\"ג ח\"א ע' שפח: כמ\"ש בב\"י סי' סא ד\"ה כתב סמ\"ק."],["2898","10","<b>במחשבה אחת ברא</b>: וראה לקו\"ת נשא כ, ד מציין בזהר ובמדרש. ובלקו\"ת נצבים מז, ג: ובמדרש. בסה\"מ תקס\"ב ח\"א ע' י. ע' כה. סה\"מ תקס\"ט ע' קפד בזהר בראשית. בס' הנחות הר\"פ ע' קח ובזהר פ' שמות. ובדרוש זה בלקו\"ת שה\"ש ט, ב ובזהר פ' שמות (נ\"א פ' בראשית). וראה זהר שמות כ, א. תוספות שם רעו, סע\"ב."],["2899","11","<b>ז' רקיעים</b>: חגיגה יב, ב. ראה הערת כ\"ק אדמו\"ר זי\"ע בס' שיעורים בס' התניא שער היחוד והאמונה ע' 906 הערה 3."],["2900","12","<b>חי\"ת והדלי\"ת הם ד' רוחות העולם</b>: ראה שו\"ע אדה\"ז הל' קריאת שמע ס\"ס ס\"ו."]]],[2100490506,"שבאה לגוף היתה נהנית<sup data-n=\"2901\">13</sup> מזיו כו' בלתי זה האריכות ואם מפני שבירידתה בגוף החומרי נתגשמה לכך הוצרכה לאריכות זה א\"כ למה ירדה לגוף כלל כו'.\n<b>אך</b> הענין הוא דידוע דיש ב' נפשות באיש הישראלי נפש האלקי' הנק' נר ה' כמ\"ש נר<sup data-n=\"2902\">14</sup> ה' נשמת אדם וכן כתיב כי<sup data-n=\"2903\">15</sup> אתה תאיר נרי כו' ונפש הבהמיות כו' ויש עוד בחי' ממוצע ביניהם והוא הנפש* השכלית וביאור ג' אלה הנפשות הנה נפש האלקי' חפצה ותשוקתה בטבעה להכלל במקור חוצבה באלקים כי נק' חלק<sup data-n=\"2904\">16</sup> אלוה ממש וכמשל הנר העולה מאיליו כו' וע\"ז נא' בכנ\"י בנים<sup data-n=\"2905\">17</sup> אתם כו' וברא<sup data-n=\"2906\">18</sup> כרעא דאבוה הוא ע\"כ נמשכה מצד שרשה בתמידו' למקורה בלתי שינוי לעולם כו' והנה נפש האלקי' נתלבשה בלבוש גשמי מטוב שבנוגה והוא נפש השכליו' והיינו מה שיש בכח האדם להשכיל בשכל אנושי ג\"כ בגדולת ה' ולהתפעל במוחו ואח\"כ בלבו והיינו עד שגם השכל מסכים עם טבע הנפש האלקי' ועי\"ז מתברר גם נפש הבהמיו' והגופנית שהמה המדו' הרעות לגמרי* כו' כי הנפש<sup data-n=\"2907\">19</sup> השכלית הזאת בחי' ממוצע הוא לחבר נפש האלקי' להאיר בנפש הבהמיות ולאהפכא<sup data-n=\"2908\">20</sup> חשוכא לנהורא כו' דהיינו שגם רצון הטבעי בגוף החומרי יסכים לאהבת ה' וכיוצא ולזה הטעם ירדה הנשמ' האלקי' בחומר הגופני רק לברר ולהפוך חשוכא לנהורא כו' כי הנשמה א\"צ להתברר אלא ירדה לברר לבושי נוגה כו' כמ\"ש<sup data-n=\"2909\">21</sup> בלק\"א וד\"ל.\n<b>וזהו</b> עיקר ענין ק\"ש בפסוק הראשון בפי' שמע ישראל כו' פי' שמע<sup data-n=\"2910\">22</sup> לשון הבנה והוא שיסכים גם ע\"י השכל שהוא נפש השכלית הנ\"ל וההתבוננו' היא גם בתיבת שמ\"ע עצמו דהנה &lt;קסד&gt;\nתיבת שמע<sup data-n=\"2911\">23</sup> הוא שם ע' והע' הוא ע' רבתי והענין הוא כי",[["2901","13","<b>נהנית מזיו</b>: ראה ברכות יז, א."],["2902","14","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["2903","15","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."],["2904","16","<b>חלק אלוה ממש</b>: ראה תניא פ\"ב."],["2905","17","<b>בנים אתם</b>: ראה יד, א."],["2906","18","<b>וברא כרעא דאבוה</b>: ע\"ח שער (כד) פרק הצלם פ\"א: בשם רז\"ל. יונת אלם [לרמ\"ע מפאנו] רפ\"ב (אמרו חכמים). תורת חיים סנהדרין פב, ב ד\"ה בקשו. רש\"י כתובות צב, א ד\"ה כבעל חוב: דראובן כרעי' דאבוה. תוד\"ה מקמי יבמות ג, א."],["2907","19","<b>הנפש השכלית. . בחי' ממוצע</b>: ראה סה\"מ תקס\"ד ע' קע."],["2908","20","<b>ולאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["2909","21","<b>כמ\"ש בלק\"א וד\"ל</b>: ראה תניא פל\"ז. וראה תו\"א חיי שרה טז, ג."],["2910","22","<b>שמע לשון הבנה</b>: ראה זהר (אדרא רבא) נשא קלח, ב. לקו\"ת פינחס פ, א. לקו\"ש חי\"ז ע' 112. וראה שמואל-א א, ג. ט, ו. בשערי תשובה ח\"ב חינוך מו, ג מציין: כדפרש\"י שם."],["2911","23","<b>שמע הוא שם ע'. . רבתי</b>: זהר (רעיא מהימנא) פינחס רלו, ב. ראה סידור שער הק\"ש עז, ב. אמרי בינה שער הק\"ש פ\"ו. ביאוה\"ז שופטים קכד, ב. תו\"א ויחי קה, ג."]]],[2100490507,"בחי' חיות כל הנבראי' נשמות ומלאכי' הוא רק מבחי' שם בלבד כידוע עד\"מ שם המלך שנקרא על אנשי מדינתו שבזה בלבד הוא ענין התפשטו' מלכותו עליהם וכך למעלה דכתיב מלכותך<sup data-n=\"2912\">24</sup> מלכו' כ\"ע כו' הוא רק בחי' הארת שמו ית' שבזה הוא מלכו' כ\"ע כו' וכמ\"ש במ\"א וזהו שמע שם ע' פי' כי שם זה דמדת מלכותו ית' נמשך מע' רבתי וענין הע' רבתי הוא הנק' אור שבעת הימים כמ\"ש לעתיד והיה<sup data-n=\"2913\">25</sup> אור הלבנה כאור החמה ואור החמה שבעתיים כאור שבעת הימים כו' וענין זה האור דשבעת הימים הוא בחי' המקור לכל ז' הימים העליונים דאצילות שנקראו שבעת ימי הבנין למטה והמה ז'<sup data-n=\"2914\">26</sup> ימי בראשית שנבראו בהן כל העולמות ביום הא' האיר ממדת החסד כו' וכידוע ומבחי' האור הזה נמשך כל ז' ימי בראשית בין בבחי' אצילו' והוא בבחי' ז\"א דאצי' ובין בבחי' מל' דאצי' שנק' מקור כל הנבראי' בי' מאמרו' כמ\"ש מלכותך מלכו' כ\"ע עד שנתהוו ז' רקיעי' למטה בעולם העשי' כו' וזהו הטעם שנק' בשם אור שבעת הימים ואור הלבנה שהוא בחי' מל' דאצי' נמשך מאור של ז' הימים הזה ולעתיד תתעלה מדת מל' למעלה להיות בבחי' אור ז' הימים והיינו בחי' הע' רבתי שה\"ע ז' ימים כל יום כלול מי' כלולי' בו ולהיותו במדרגה גבוה מאד למעלה מבחי' ההשתלשלו' דז' ימי הבנין לכך הע' הוא רבתי להורות על בחי' גדלותו ורוממותו למעלה* מעלה וד\"ל.\n<b>ופי'</b> שמע ישראל כי ישראל<sup data-n=\"2915\">27</sup> עלה במחשבה שהוא ב' תיבו' הוי' אלקינו שמזכיר בסמוך שהוא למעלה גם מבחי' ע' רבתי הזה (שהרי המחשבה הוא בבחי' חכמה שנק' ראשית וכמ\"ש קדש<sup data-n=\"2916\">28</sup> ישראל לה' ראשית כו' ואור ז' הימים הוא בחי' בינה<sup data-n=\"2917\">29</sup> שמקבל מחכמה ונק' תרין* ריעין) וזהו פי' שמע ישראל הוא נר ה' שעלה",[["2912","24","<b>מלכותך מלכו' כ\"ע</b>: תהלים קמה, יג."],["2913","25","<b>והיה אור הלבנה כאור החמה</b>: ישעי' ל, כו."],["2914","26","<b>ז' ימי בראשית. . ממדת החסד</b>: ראה זהר תשא לא, יז. זהר ויחי רמז, א."],["2915","27","<b>ישראל עלה במחשבה</b>: ראה ב\"ר פ\"א, ד."],["2916","28","<b>קדש ישראל לה'</b>: ירמי' ב, ג."],["2917","29","<b>בינה. . מחכמה. . תרין ריעין</b>: ראה זהר בשלח נו, א. ויקרא ד, א."]]],[2100490508,"במחשבה איך שה' אלקינו למעלה גם מאור ז' הימים הנ\"ל וכשיתבונן בכל זה אזי בא לידי ואהבת את ה' פי' את הטפל* כו' ע\"ד מ\"ש והית'<sup data-n=\"2918\">30</sup> נפש אדוני צרורה בצרור החיים את ה' אלקיך פי' צרורה בצרור עד\"מ דבר הנקשר ונצרר בצרור שצרור וקשור הוא בדבר שצוררי' בו זה בתוך זה ממש כך ישראל שעלה במחשבה צרורי' שם בתוך המחשבה זה בתוך זה ממש וז\"ש צרורה בצרור החיים שהוא בחי' המחשבה הנ\"ל והיינו* את הטפל כו' ע\"י הדביקו' באהבה ופי' בכל<sup data-n=\"2919\">31</sup> לבבך ובכל נפשך היינו בבחי' נפש הבהמיו' שנק' לב הטבעי וכמארז\"ל בשני<sup data-n=\"2920\">32</sup> יצריך כו' ובכל נפשך נפש השכלית הנ\"ל כו' וכל זה בא ע\"י ההתבוננו'* הנ\"ל וד\"ל.\n<b>ב</b><sup data-n=\"2921\">*32</sup>אך לפ\"ז צריך להבין דהלא הנשמה אלקי' עלה במחשבה קודם ירידת' לגוף וא\"כ למה ירדה לגוף לבא לאריכו' ההתבוננו' ולחזור לבא למדרגתה הקדומה להיות צרורה בצרור החיים כו' וגם למה הוצרכה להתלבש בלבוש הגופני דנפש השכלית בהתבוננו' גשמיות כו'.\n<b>אך</b> הענין הוא דירידה זאת לצורך עלייה היא לבא למדרג' יותר גבוה ממה שהיתה והיינו שתבא למדרג' האהבה הגדולה דבכל מאד\"ך בק\"ש שהיא אהבה רבה בבחי' בלי גבול כו'. כי הנה הנשמה קודם ירידתה למטה בגוף היה השגתה בבחי' גבול כמ\"ש &lt;קסה&gt;\nנודע<sup data-n=\"2922\">33</sup> בשערים בעלה בכל חד לפום<sup data-n=\"2923\">34</sup> מה דמשער בלבי' וכמארז\"ל<sup data-n=\"2924\">35</sup> בנשמו' הצדיקים שנותנין לכאו\"א מדור לפי כבודו דוקא דהיינו לפי ערך השגתו בלבד כו' משא\"כ אחר ירידתה בחומר הגופני יכולה לבא למדרגה הגבוה הרבה מכפי ערכה והיינו שיהי' בחי' התפעלו' האהבה בלתי מוגבל כלל וכלל והוא אהבת בכל מאדך כידוע וזהו רק ע\"י שבהיותה בחומר הגופני מהפכת את הנפש הבהמיו'",[["2918","30","<b>והיית' נפש אדוני צרורה</b>: שמואל-א כה, כט."],["2919","31","<b>בכל לבבך ובכל נפשך</b>: ואתחנן ו, ה."],["2920","32","<b>בשני יצריך</b>: ברכות נד, א (במשנה)."],["2921","*32","האות ב רשום בגוכתי\"ק הצ\"צ."],["2922","33","<b>נודע בשערים בעלה</b>: משלי לא, כג."],["2923","34","<b>לפום מה דמשער בלבי'</b>: ראה זהר וירא קג, ריש ע\"ב."],["2924","35","<b>וכמארז\"ל. . מדור לפי כבודו</b>: ראה בבא בתרא עה, א."]]],[2100490509,"ע\"י בחי' הממוצע הנ\"ל ואתכפיא סט\"א ואתהפכא חשוכא לנהורא כו' ועי\"ז דוקא תוכל לבא למעלה גדולה כזאת כו' וע\"ז נא' בכללו' נ\"י והי'<sup data-n=\"2925\">36</sup> מספר בנ\"י כו' אשר לא יספר פי' מבחי' מספר יבאו לידי למעלה מן המספר שהוא בחי' מאד בלי גבול ומספר והיינו כשעושין רצונו של מקום בהתהפכו' חשוכא לנהורא ומרירו למיתקא כו' שזה אינו אלא ע\"י שמלובשת הנפש האלקי' בנפש הבהמיו' דוקא וזהו ענין הירידה שהיא לצורך עלי' שהרי תתעלה עי\"ז בעילוי גדול יותר מכפי ערכה בעצם כו' וד\"ל.\n<b>אך</b> הנה יש להבין כל עיקר הטעם דהיא גופא קשיא למה תתעלה הנשמה ע\"י אתהפכא חשוכא לנהורא דוקא כו' כי מה יש ענין מעלה בהתהפכו' זו כ\"כ והענין הוא דכתיב ישת<sup data-n=\"2926\">37</sup> חושך סתרו וכמארז\"ל כברייתו<sup data-n=\"2927\">38</sup> של עולם ברישא חשוכא והדר נהורא כו' וביאור הדברים ידוע שיש ב' מדרגו' בסדרי ההשתלשלו' הא' בחי' התוהו והב' בחי' התיקון כמבואר בספרי הקבלה וכמ\"ש באד\"ר<sup data-n=\"2928\">39</sup> ע\"פ ואלה המלכים אשר מלכו בארץ אדום לפני מלוך מלך לבנ\"י פי' דאורות דתוהו היו אורות גדולים וגבוהים הרבה מבחי' אורות דתיקון אלא משום שלא יכלו הכלים לסבול האור נפלו בשבירה כו' וידוע<sup data-n=\"2929\">40</sup> שכל דבר גבוה נופל לעומק יותר כמשל אבן הנופלת מגובה החומה כו' וכמ\"ש במ\"א וזהו שנא' במלכין קדמאי' דתוהו וימלוך וימת כו' והיינו בחי' חושך העליון דכתיב ישת חושך סתרו ובנפילתו למטה מטה הוא נעשה בחי' חושך גמור הנק' חושך וצלמות כו' והוא בחי' הרע דנוגה דנפש הבהמיו' נלקחת משם ואמנם בבירור הרע לטוב ואתהפכא חשוכא לנהורא ע\"י נפש האלקי' הרי עולה הדבר המתברר לשרשו הקדום כמו שהי' קודם שנפל בשבירה כו' שהוא בחי' התוהו שקדם לבחי' התיקון דהיינו המלך לבני ישראל כו' ונעשה עי\"ז יתרון אור גדול למעלה גבוה הרבה מבחי' התיקון וז\"ש כיתרון<sup data-n=\"2930\">41</sup> או\"ר מתוך החוש\"ך מן החושך*",[["2925","36","<b>והי' מספר בנ\"י</b>: הושע ב, א."],["2926","37","<b>ישת חושך סתרו</b>: תהלים יח, כב."],["2927","38","<b>כברייתו של עולם</b>: שבת עז, ב."],["2928","39","<b>באד\"ר ע\"פ ואלה המלכים אשר מלכו</b>: וישלח לו, לא ואילך. ראה זהר (אדרא רבא) נשא קכח, א. ע\"ח שער הכללים פ\"א. שער (ח) דרוש פ\"ד."],["2929","40","<b>וידוע שכל דבר גבוה</b>: ראה סידור שחרית עא, ד. שם שער הל\"ג בעומר שג, ג. הנסמן בס' המפתחות (קה\"ת תשמ\"א) לספרי אדה\"ז בערכו. שערי אורה שער הפורים נח, א. סה, א. וראה לעיל ע' ת הערה 30."],["2930","41","<b>כיתרון אור מתוך החושך</b>: קהלת ב, יג."]]],[2100490510,"דוקא ומטעם הנ\"ל וד\"ל ולזה הטעם ניתן לכאו\"א מספר שנים כפי הצורך שצריך לכאו\"א לברר ולהפך בחי' נפש הבהמיו' דנוגה וכמ\"ש ימי<sup data-n=\"2931\">42</sup> שנותינו בהם שבעים שנה כו' וכתיב כי<sup data-n=\"2932\">43</sup> צל ימינו עלי ארץ כו' כי ימים<sup data-n=\"2933\">44</sup> יוצרו כו' וכמ\"ש<sup data-n=\"2934\">45</sup> במ\"א וד\"ל.\n<b>והיינו</b> הטעם שירידה זו לצורך עלי' הוא ע\"י התהפכו' חשוכא לנהורא כנ\"ל כי בזה דוקא יכולה הנשמה לבא לבחי' מאד בלי גבול דהיינו בחי' התוהו שהמה אורו' בחי' בלתי מוגבלי' בכלי דלכך נפלו כו' וד\"ל ובכל זה יובן מ\"ש כי<sup data-n=\"2935\">46</sup> לא יראני האדם וחי ואמרו ז\"ל בחייהם אינן רואין אבל במיתתן<sup data-n=\"2936\">47</sup> רואין פי' בחייהם אחר שלא ביררו כפי הצורך לברר מבחי' נוגה בנפש הבהמיו' כפי המספר שניתן לו כו' אינו יכול לראות עדיין במהות ועצמו' אור א\"ס ב\"ה &lt;קסו&gt;\nשלמעלה מכל ההשתלשלו' כמו שאמר למשה ג\"כ כשביקש הראיני נא כו' והשיבו כי לא יראני האדם וחי כלומר בשעה שחי מפני שעדיין לא בירר משה כפי צרכו שצריך לברר לפי ערכו כו' אך במיתתן רואין לפי שכבר נשלם כל הברורי' להפוך חשוכא לנהורא כפי הצריך לו כו' ואזי יכול האדם להשיג ולראות באלקות גם במה שלא השיג משה ע\"ה בעודו בחייו כו' וכמאמר במיתתן רואין והוא מטעם הנ\"ל לפי דמה שמגיע לבחי' מא\"ד באהבת בכל מאדך הוא דוקא לאחר שנשלם כל הבירור בשלימות משא\"כ בעודנו חי שלא נשלם כל הצורך ולכך בחייהם אינן* רואין וד\"ל.",[["2931","42","<b>ימי שנותינו בהם שבעים שנה</b>: תהלים צ, י."],["2932","43","<b>כי צל ימינו</b>: איוב ח, ט. דברי הימים-א כט, טו."],["2933","44","<b>כי ימים יוצרו</b>: תהלים קלט, טז."],["2934","45","<b>וכמ\"ש במ\"א</b>: ראה סה\"מ תקס\"ה ח\"ב ע' תתמט."],["2935","46","<b>כי לא יראני האדם וחי</b>: תשא לג, כ."],["2936","47","<b>במיתתן רואין</b>: ראה תורת כהנים ויקרא א, א. ילקו\"ש ויקרא ריש רמז תלא. במדבר רבא ספי\"ד. כלה רבתי פ\"ג."]]],[2100490511,"<b>ג</b><sup data-n=\"2937\">*47</sup>. וזהו אם בחוקותי תלכו, פי' תלכו הוא בחי' האהבה רבה דבכל מאדך הנ\"ל וכענין שנא' באברהם הלוך<sup data-n=\"2938\">48</sup> ונסוע הנגבה כו' בחי'<sup data-n=\"2939\">49</sup> מהלך הוא בבחי' א\"ס בעילוי אחר עילוי כו' דהיינו בלי גבול כנ\"ל וזהו מדרגה הגבוה שהנשמה מגיע אליה אחר שנתלבשה בגוף דוקא מטעם* הנ\"ל והיינו שאמר אם בחוקותי תלכו ואמרו ז\"ל הלואי כו' פי' הלואי שתהא הליכה זו ע\"י בחוקותי דוקא וענין חוקותי הוא לשון חקיקה וחריצה כו' עד\"מ החוקק באבן שעושה פגם וחסרון ונעשה אותו המקום שקוע כו' כך צריך לעשו' בחי' חקיקה בנפש הבהמיו' דנוגה וכמ\"ש דוד ולבי<sup data-n=\"2940\">50</sup> חלל בקרבי חלל ממש כו' והוא לאהפכא חשוכא כו' מן הקצה לקצה כו' ואזי יוכל להיו' בחי' מהלך בהליכה דאהבה רבה הנ\"ל וזהו אם בחוקותי אז תלכו ואם לאו לא* תלכו וד\"ל.\n<b>ומה</b> שאמר בחוקותי ב' חקיקות הענין הוא דע\"י שמאריך באחד בפסוקי דזמרה בהתבוננו' עד ק\"ש ממילא נשבר לבבו הבהמיו' המוטבע בגשמיות עוה\"ז שידוע המאמר דכד<sup data-n=\"2941\">51</sup> אתכפיא סט\"א אסתלק יקרא דקדב\"ה ומכ\"ש בהיפוך דכד אסתלק יקרא דקדב\"ה ממילא אתכפיא סט\"א דמאי שנא מאחר שתולה זה בזה כו' ולכך כד אסתלק יקרא דקדב\"ה בהתבוננו' באחדו' ה' ממילא אתכפיא חלק נפש הבהמיו' שבאדם כו' וזהו ענין החקיקה שנחקק לב הטבעי החומרי וכמ\"ש דוד ולבי חלל בקרבי כו' וזהו רוממו'<sup data-n=\"2942\">52</sup> אל בגרונם וחרב פיפיו' בידם פי' ע\"י ההתבוננו' ברוממו' אל באחדו' ה' כנ\"ל בשעת פסוקי דזמרה עד ק\"ש ממילא נעשה עי\"ז חרב פיפיו' לעשות נקמה בגוים הן* הע' שרים להבדילם ממקור החיים כו' והוא משום דאתכפיא סט\"א חלק נפש הבהמיו' כד אסתלק יקרא דקדב\"ה ע\"י ההתבוננות כנ\"ל וד\"ל וזהו הטעם ג\"כ שאסור<sup data-n=\"2943\">53</sup> לאכול קודם התפלה ונק' מעונן<sup data-n=\"2944\">54</sup> ומנחש כמ\"ש בזוהר לפי שמוסיף יניקה לחיצונים עי\"ז מטעם שלא נתפשט עדיין בנפש הבהמיו'",[["2937","*47","<b>ג</b>: האות ג רשום בגוכתי\"ק הצ\"צ."],["2938","48","<b>הלוך ונסוע הנגבה</b>: לך לך, יב, ט."],["2939","49","<b>בחי' מהלך</b>: ראה זהר לך פ, א. פד, א. תו\"א יתרו עג, ד."],["2940","50","<b>ולבי חלל בקרבי</b>: תהלים קט, כב."],["2941","51","<b>דכד אתכפיא סט\"א</b>: ראה זהר תרומה קכח, ב."],["2942","52","<b>רוממות אל בגרונם</b>: תהלים קמט, ו."],["2943","53","<b>שאסור לאכול קודם התפלה</b>: ראה שו\"ע אדה\"ז הל' תפלה ספ\"ט, ס\"ה."],["2944","54","<b>מעונן ומנחש</b>: שופטים יח, י."]]],[2100490512,"מבחי' נפש האלקי' הנק' נר ה' וז\"ש חדלו<sup data-n=\"2945\">55</sup> לכם מן האדם אשר נשמה באפו פי' נשמה האלקי' היא באפו עדיין ולא נתפשטה בכל חלקי הגוף שהנפש הבהמיו' בתוכו ואפי' בקומו בבקר ואמר ברכת ענט\"י לא נתפשטה בו (עד שיגיע לברכו ויאמר ברוך<sup data-n=\"2946\">56</sup> ה' המבורך ל\"ו שהן נגד נרנח\"י שבנפש האלקי' כמ\"ש בספרי הקבלה) והוא ע\"י ענין ההתבוננו' בנפש השכלי' הנק' ממוצע לחבר נפש האלקי' בנפש הבהמיו' כנ\"ל וד\"ל.\n<b>והנה</b> זהו ענין חקיקה א' וענין חקיקה השנית הוא ע\"י מעשה המצות באותן המצות שנק'<sup data-n=\"2947\">57</sup> חוקים דוקא &lt;קסז&gt;\nכמו מצות פרה אדומה וכיוצא בזה בדבר שאין השכל אנושי משיג כו' וכמו מצות ציצית ותפילין וסוכה וכיוצא משא\"כ איסור<sup data-n=\"2948\">58</sup> גניבה ואיסור מלאכה בשבת שהשכל מסכים ע\"ז והנה מצות הנק' חוקים כמאמר חוקים<sup data-n=\"2949\">59</sup> שחקקתי לך כו' שהוא למעלה מבחי' טעם ודעת אחר שלא באו בהשגה וטעם כלל הרי המה גבוהי' משאר המצות שמלובשי' בשכל וטעם ונק' חוקותי כמ\"ש מצוותי<sup data-n=\"2950\">60</sup> וחוקותי כו' וע\"כ נק' רצון ה' בלבד כי המה בחי' הרצון מצד עצמו שלמעלה מן הטעם והשכל כידוע ולזה הטעם יש ביכולת המצות הללו להפוך הרצון הזר דקליפה וסט\"א לעשות לב הטבעי חלל וחקוק בבחי' ביטול רצון זר מכל וכל כענין מ\"ש מי<sup data-n=\"2951\">61</sup> לי בשמים ועמך לא חפצתי כו' וזהו מארז\"ל בטל<sup data-n=\"2952\">62</sup> רצונך מפני רצונו מפני רצונו דוקא שהן המצות הנ\"ל שנק' חוקים שלמעלה מן השכל וד\"ל וזהו הטעם שצריך לקיים מצות ציצית ומצות תפילין קודם התפלה כדי שיחקק חקיקה בלב הטבעי ויהא מבטל רצונו הטבעי נגד רצון ה' שבמצות הללו שהמה למעלה מן השכל* כנ\"ל וד\"ל.",[["2945","55","<b>חדלו לכם מן האדם אשר נשמה באפו</b>: ישעי' ב, כב."],["2946","56","<b>ברוך ה' המבורך לעולם ועד. . נגד נרנח\"י. . בספרי הקבלה</b>: ראה פע\"ח שער (ז) הק\"ש פ\"א."],["2947","57","<b>שנק' חוקים. . מצות פרה אדומה</b>: ראה מאמרי אדה\"א ויקרא ע' תשנז — ככלאי' ושעטנז וכמצו' פרה אדומה וכה\"ג. וכן בל\"ת לא תרצח לא תגנוב ולא תנאף כו' וכה\"ג."],["2948","58","<b>איסור גניבה ואיסר מלאכה בשבת שהשכל מסכים</b>: שם: שביתה ממלאכה בשבת שהשכל מסכים ע\"ז."],["2949","59","<b>חוקים שחקקתי</b>: קידושין לט, א."],["2950","60","<b>מצוותי וחוקותי</b>: תולדות כו, ה."],["2951","61","<b>מי לי בשמים ועמך לא חפצתי</b>: תהלים עג, כה."],["2952","62","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב, מ\"ד."]]],[2100490513,"<b>וזהו</b> אם בחוקותי תלכו אם הלואי שע\"י ב' חקיקו' הנ\"ל תלכו שיבאו לאהבה דבכל מאדך הנ\"ל כי יוכל להיו' אהבה רבה גם בלתי חקיקו' הנ\"ל בלב החומרי אבל אינה נק' אהבה אמיתית כ\"א ע\"י ב' חקיקו' הנ\"ל ולכך אמרו ז\"ל הלואי בחוקותי תלכו וד\"ל.\n<b>ואת</b> מצותי תשמרו כו' ועשיתם אותם, פי' כי הנה אנו אומרים בכל ברכת המצות אשר קדשנו במצוותיו כו' ופי' אשר<sup data-n=\"2953\">63</sup> מלשון תענוג כמ\"ש באשרי כי אשרוני בנות והוא בחי' תענוג העליון שיש במצות הנק' רצון העליון. וזהו אשר קדשנו במצוותיו וז\"ש אשרי<sup data-n=\"2954\">64</sup> איש ירא את ה' במצוותיו חפץ כו' כי בחי' אשר שורה במצות וד\"ל וזהו אשר קדשנו בבחי' קדש העליון כי הנה מבואר בזוהר<sup data-n=\"2955\">65</sup> דקד\"ש מלה בגרמיה הוא כלומר החכמה מובדל ומרומם מכל ההשתלשלו' וע\"כ אין אש\"ר דעונג העליון שורה אלא בבחי' קדש ולכך קדשנו כו' והוא בחי' הארת עצמו' אור א\"ס שלמעלה מבחי' סובב וממלא כו' כי בחי' סובב וממלא לא שייך כ\"א בבחי' השתלשלו' שאז יש בחי' א\"פ וא\"מ כו' וכל זה אנו ממשיכי' ע\"י מעשה המצות מפני שהמה בחי' חכמתו ורצונו כידוע והיינו אשר קדשנו במצוותיו ע\"י מצוותיו דוקא וד\"ל.\n<b>וזהו</b> כי<sup data-n=\"2956\">66</sup> נר מצוה שהמצוה נמשלה לנר דוקא, כי הנה עד\"מ הנר יש בו השמן והאור והרי עיקר הדולק הוא השמן והאור ואין הנר אלא כלי לשמור האור הדולק בלבד ע\"י שמחזיק השמן והאור בתוכו כו' כך המצות נק' כלים לבחי' אור הא\"ס ששורה בקדש העליון כנ\"ל לשמור אורו בתוכו עד\"מ ושלא ירד למטה כו' וד\"ל, וזהו ואת מצותי תשמרו ע\"י מצוותי תשמרו לבחי' אור א\"ס שישרה בתוכם בתמידות* וד\"ל, ועשיתם אותם פי' ועשיתם מלשון הכרח כמו גט<sup data-n=\"2957\">67</sup> מעושה כו'",[["2953","63","<b>אשר מלשון תענוג כמ\"ש באשרי כי אשרוני</b>: ויצא ל, יג. ראה תקו\"ז ת\"ל (עד, ב). תל\"ט (עט, א). תו\"א שמות נג, ב. סה\"מ תקס\"ה ח\"א ע' רד."],["2954","64","<b>אשרי איש ירא את ה'</b>: תהלים קיב, א."],["2955","65","<b>בזהר דקדש מלה בגרמי'</b>: אמור צד, ב."],["2956","66","<b>כי נר מצוה</b>: משלי ו, כג."],["2957","67","<b>גט מעושה כו' וכמו וגדול המעשה</b>: גיטין פח, ב (במשנה). בבא בתרא ט, א. וראה לקו\"ש חי\"ד ע' 238."]]],[2100490514,"וכמו וגדול המעשה כו' והוא ענין כפייה והכרח כידוע וגם במצות אחר שהמה בחי' כלים לאורו' עליונים ולכך נק' רמ\"ח<sup data-n=\"2958\">68</sup> פקודי' רמ\"ח איברי\"ם דמלכא בזוהר ור\"מ ואין ערוך כלל בין נברא עם &lt;קסח&gt;\nהבורא כידוע בפי' אין<sup data-n=\"2959\">69</sup> ערוך לך כו' א\"כ האיך יומשך אור גילוי אלקות למטה בעולם הנפרד ע\"י מעשה המצות לכך אמר ועשית\"ם אות\"ם שיומשכו למטה בדרך הכרח והיינו כמו דרך דילוג מלמעלה למטה והוא לפי שאור א\"ס א\"א להתחבר עם העולמו' ע\"י שום דבר זולת המצות כי גם באברהם שהי' במדרג' הדביקו' כתיב בי' ושמי<sup data-n=\"2960\">70</sup> הוי' לא נודעתי להם כו' והוא מפני שלא זכה לתורה ומצות וגם יעקב שהי' כלול מכל המדו' והי' שלם מבחי' השלימו' דאור א\"ס שהרי נאמר ליעקב ופרצת<sup data-n=\"2961\">71</sup> ימה וקדמה כו' ובאברהם כתיב הלוך<sup data-n=\"2962\">72</sup> ונסוע הנגבה בלבד בסטרא דחסד שהוא האהבה בלבד אבל יעקב<sup data-n=\"2963\">73</sup> נק' בריח התיכון שמבריח מן הקצה לקצה מפני שעלה עד הכתר כו' אעפ\"כ לא זכה להיו' שמו' דהוי' שהוא בחי' עצמו' אור א\"ס וכמ\"ש ושמי הוי' לא נודעתי להם כו' אלא דוקא ע\"י המצות מעשיו' כי ע\"י המצות יבא ויגיע אור א\"ס למטה גם ע\"י בחי' כפי' והכרח אע\"פ שאין ערך כלל עמו כו' וזהו ועשית\"ם אות\"ם והוא מטעם הנ\"ל שהמצות המה כלים לאור הא\"ס כמ\"ש ואת מצוותי תשמרו וע\"כ ועשיתם* אותם וד\"ל.\n<b>ד</b><sup data-n=\"2964\">*73</sup>. ונתתי גשמיכם בעתם, הנה זה הכתוב מדבר בבחי' התורה שנמשל למים כמ\"ש הוי<sup data-n=\"2965\">74</sup> כל צמא לכו למים והקול שמדבר בד\"ת ומחלק ההבל בה' מוצאות הפה נמשל לגשמים שהמים שבעבים יורדים בבחי' התחלקות טיפין טיפין",[["2958","68","<b>רמ\"ח פיקודין רמ\"ח איברים דמלכא בזהר ור\"מ</b>: ראה תקו\"ז ת\"ל (עד, סע\"א). רע\"מ משפטים קיח, א."],["2959","69","<b>אין ערוך לך</b>: ברכת יוצר לשבת. וראה ביאוה\"ז בלק ק, סע\"ד."],["2960","70","<b>ושמי הוי' לא נודעתי להם</b>: וארא ו, ג."],["2961","71","<b>ופרצת ימה וקדמה</b>: ויצא כח, יד."],["2962","72","<b>הלך ונסוע. . בסטרא דחסד</b>: לך יז, א. וראה זהר לך פד, א."],["2963","73","<b>יעקב נק' בריח התיכון שמבריח מן הקצה לקצה</b>: ראה זח\"ב קעה, ב. ועוד. אוה\"ת ויחי שפה, ב. שפח, א. ועוד."],["2964","*73","<b>ד</b>: האות ד רשום בגוכתי\"ק הצ\"צ."],["2965","74","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."]]],[2100490515,"ולכך נק' גבורות<sup data-n=\"2966\">75</sup> גשמים מפני שיורדין בגבורה* כו' וע\"ז נאמר הקול<sup data-n=\"2967\">76</sup> קול יעקב דהיינו בחי' קול<sup data-n=\"2968\">77</sup> של תורה דוקא כמבואר בדברי רז\"ל ובזוהר.\n<b>וזהו</b> דכתיב כאשר<sup data-n=\"2969\">78</sup> ירד הגשם והשלג מן השמים כו' והרוה את הארץ והולידה והצמיחה כו' ונתן זרע לזורע ולחם לאוכל כו' כן<sup data-n=\"2970\">79</sup> יהי' דברי אשר יצא מפי לא ישוב ריקם כ\"א עשה את אשר חפצתי והצליח אשר שלחתיו, דהנה אנו רואים בטבע ירידת הגשם שאין הענין שמבלעדי הגשם אין בכח הארץ להגדיל ולהצמיח זרע ותבואה כלל שהרי דבר הנראה הוא לעין הרואה שיש כח הצומח בארץ להצמיח גם מבלעדי הגשם וא\"כ ירידת הגשמים אינם כחות המצמיחים בעצמם אלא המה סיבה להוציא הכח הצומח שבארץ אל פעולתו להגדיל ולהצמיח בתוספת ברכה בתוספת מרובה על עיקר הזרע כו' ואמנם מ\"מ הגשמים המה אשר פועלים בארץ ליתן תת כחה שהרי מבלעדי הגשמים אין הארץ תוציא צמח כלל כנראה בחוש והיינו שלא תתן הארץ את כחה להצמיח בכח המצמיח אשר יש בה בלתי אם לא תקבל בעצמה ממי הגשמים וזהו והרוה את הארץ ואז והולידה והצמיחה מצד כח עצמותה כו'.\n<b>והנמשל</b> מכל זה יובן בקול דתורה שנמשל למי הגשם כמ\"ש כאשר ירד הגשם כו' כן יהי' דברי אשר יצא מפי כו' והוא מ\"ש ודברי<sup data-n=\"2971\">80</sup> אשר שמתי בפיך כו' שע\"י קול זה דתורה נולד ונצמח הרצון והתשוקה בלב החומרי שנמשל לארץ בחי' מקבל ובכללו' נ\"י הוא בדרך כלל נפתח בלבבם הטבעי רצון ואהבה וכמ\"ש קול<sup data-n=\"2972\">81</sup> דודי דופק פתחי לי אחותי רעייתי פי' כאשר קול דודי דופק בקלא דאוריי' אזי אומר לכנ\"י פתחי לי שנעשה בחי' פתח פתוח בלב כנ\"י הנק' רעותא דלבא כמ\"ש ולבי<sup data-n=\"2973\">82</sup> חלל בקרבי כחלל הפתח וכענין &lt;קסט&gt;\nפתח<sup data-n=\"2974\">83</sup> לבי כו' והוא מפני שהקול דתורה נמשל לגשם וכמו שהגשם פותח פתח בארץ להוציא הכח שיש לה כך קול דתורה",[["2966","75","<b>גבורות גשמים</b>: תענית ב, א."],["2967","76","<b>הקול קול יעקב</b>: תולדות כז, כב."],["2968","77","<b>קול של תורה דוקא כמבואר בדברי רז\"ל ובזוהר</b>: ב\"ר פס\"ה, כ. זח\"א קנא, סע\"א."],["2969","78","<b>כאשר ירד הגשם</b>: ישעי' נה, י."],["2970","79","<b>כן יהי' דברי</b>: שם יא."],["2971","80","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["2972","81","<b>קול דודי דופק</b>: שה\"ש ה, ב."],["2973","82","<b>ולבי חלל בקרבי</b>: תהלים קט, כב."],["2974","83","<b>פתח לבי</b>: נוסח תפלת אלקי נצור כו' (ברכות יז, א). וראה לקו\"ת במדבר טו, ריש ע\"ג."]]],[2100490516,"עושה פתח בלב כנ\"י כו' וזהו כאשר ירד הגשם מן השמים והרוה את הארץ כו' כן יהי' דברי אשר יצא מפי כו' ופי' אשר יצא מפי דוקא כי הנה ארז\"ל כל<sup data-n=\"2975\">84</sup> היושב ושונה וקורא בתורה הקדב\"ה יושב ושונה וקורא כנגדו וכדכתיב ודברי אשר שמתי בפיך דבר\"י ממש כו' וזהו מ\"ש קול דודי דופק בקול דתורה דהיינו בכאו\"א מישראל כשיושב וקורא בתורה שהקדב\"ה יושב ושונה כנגד\"ו אותו דבר ההלכה ממש שהאדם לומד כי דבר ה' הוא שמדבר וכמ\"ש<sup data-n=\"2976\">85</sup> במ\"א בפי' ודבר\"י אשר שמתי בפיך כו' וזהו כן יהי' דברי אשר יצא מפי דוקא דהיינו מפי הקדב\"ה כשיושב ושונה כנגד כאו\"א מישראל בשעה שיושב ועוסק בתורה כו' ולא ישוב ריקם אותו הקול והדיבור שיוצא מפי הקדב\"ה כ\"א עשה אשר חפצתי כו' פי' שאומר דבר הנמשל שיהי' דומה למשל כי במשל הגשם הזכיר והרוה את הארץ והולידה והצמיחה ונתן זרע לזורע ולחם לאוכל כו' כן יהי' דברי כו' ג\"כ שיהי' נולד ונצמח בלב כנ\"י בתוספת ברכה ליתן זרע לזורע כו' כי הנה כתיב אור<sup data-n=\"2977\">86</sup> זרוע לצדיק כו' שהנשמו' זרועים המה עד\"מ בעוה\"ז בחומר הגופני כנ\"ל וירידה זו לצורך עלי' היא שתבא ותגיע עי\"ז לאהבה דבכל מאדך בלי גבול כנ\"ל מה שלא הי' בערכה כלל קודם ירידתה כנ\"ל באריכו' וזהו כ\"א עשה אשר חפצתי פי' שתבא הנשמ' האלקי' למדרג' דבכל מאדך שהוא בבחי' חפיצה ורצון העליון כי הוא בלתי מוגבל כנ\"ל והגם שזה נעשה ע\"י בחוקותי כנ\"ל אבל כדי שתוציא הכח הזה מכח ההעלם אל הפועל הגלוי הוא ע\"י קול דתורה כמשל הגשמי' והיינו מלמטה למעלה שהוא בחי' תלכו הנ\"ל וגם הנה ע\"י שתקיים מצות מעשיו' בעוה\"ז מבואר למעלה שיבא האור מלמעלה למטה כמ\"ש למעלה בענין ועשיתם אותם כו' וזהו כ\"א עשה את אשר חפצתי וד\"ל והצליח אשר שלחתיו פי' הצלחה זו הוא שיהי' אור הצומח בתוספת מרובה הרבה על עיקר הזריעה וכענין ויברכהו<sup data-n=\"2978\">87</sup> מאה שערים וכמארז\"ל כלום<sup data-n=\"2979\">88</sup> אדם זורע קב אלא להוציא כמה כורים כו' וכענין שקדם לומר במשל הגשם ונתן<sup data-n=\"2980\">89</sup> זרע לזורע כו' והוא לעתיד דכתיב בא<sup data-n=\"2981\">90</sup> יבא ברינה נושא אלומותיו כו'.\n<b>אך</b> מהיכן יש כח הגדול הזה לארץ להוציא הרבה בכפלי כפליים מחטה הזרועה כו' הנה מבואר למעלה שאע\"פ שהגשמים אינם מצמיחי' מעצמם בלבד מ\"מ המה פועלים פעולת הצמיחה בכח הצומח שיש בארץ מתחלה כך בנמשל קול דתורה שנמשל לגשם פועל פעולת זאת ההצלחה בכח הצומח שבארץ להצמיח וזהו והצליח אשר שלחתיו ומ\"מ עיקר הצלחת הצמיחה מצד כח הארץ עצמה היא אלא שגשמים פועלים בה הצלחה זו כו' והטעם למציאת כח גדול כזה בארץ הוא לפי ששרש כח הארץ למעלה מעלה היא דהיינו מבחי' עולם התהו שקדם לתיקון וכמ\"ש",[["2975","84","<b>כל היושב ושונה. . יושב ושונה וקורא כנגדו</b>: ראה תדא\"ר רפי\"ח. יל\"ש איכה רמז תתרלד."],["2976","85","<b>וכמ\"ש במ\"א בפי' ודברי אשר שמתי בפיך</b>: ישעי' נט, כא. וראה לקו\"ת ראה כ, ב."],["2977","86","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["2978","87","<b>ויברכהו מאה שערים</b>: ראה בראשית כו, יב."],["2979","88","<b>כלום אדם זורע קב</b>: ראה פסחים פז, ב. לקו\"ת האזינו עו, ד. ועוד."],["2980","89","<b>זרע לזורע</b>: ישעי' נה, י."],["2981","90","<b>בא יבא ברינה</b>: תהלים קכו, ה."]]],[2100490517,"ואלה<sup data-n=\"2982\">91</sup> המלכי' אשר מלכו בארץ כו' וכנ\"ל והמלכי' קדמאי' המה אורות בלתי מוגבלי' כנ\"ל לכך תוציא צמחה בלתי מוגבל כו' וגם בכללות נ\"י הזרועי' בחומר גופני שנלקח מן הארץ מטעם זה יבאו למדרג' דבכל מאדך כו' מה שלא הי' ביכולתם קודם ירידתם לגוף כו' וד\"ל.\n&lt;קע&gt;\n<b>וזהו</b> ונתתי גשמיכם בעתם פי' גשמיכם גשמי ברכה הנ\"ל שע\"י קול דתורה ואני הוא הנותן אותם משום דדברי הוא אשר שמתי בפיך וכענין הנ\"ל בפי' קול דודי דופק משום שהקדב\"ה יושב ושונה כנגדו כו' ופי' בעתם היינו בקובע עתים לתורה באותו העת שקובע כאו\"א כפי ערכו הרי הקדב\"ה יושב ושונה כנגדו באותה העת ונותן להאדם גשמי ברכה ע\"י קול דודי דופק כנ\"ל וד\"ל.\n<b>ונתנה</b> הארץ יבולה ועץ השדה יתן פריו, פי' הארץ הוא בחי' נפש הבהמיו' כנ\"ל ומשום דשרשה מבחי' התוהו שקדם לתיקון וע\"כ כד אתכפיא סט\"א אסתלק יקרא דקב\"ה כו' ונעשה יתרון האור מתוך החושך הרבה בכפלי כפליים מן האור הזרוע עצמו דהיינו מה שתבא לבחי' בכל מאדך כנ\"ל כי בחי' התוהו גבוה הרבה מבחי' התיקון כו' וז\"ש אשת חיל עטרת בעלה כו' וכנ\"ל שלעתיד נא' והי' אור הלבנה כו' שבעתים כאור שבעת הימים כו' (מפני שהשבירה הי' בשם ס\"ג ונפל לשם ב\"ן וכשיתברר שם ב\"ן יבא לבחי' ס\"ג שלמעלה משם מ\"ה כידוע) וזהו ונתנה הארץ יבולה כלומר תוספת העוז והכח שיש בה מצד שרשה בבחי' התוהו כו' דכתיב שם ישת חושך סתרו וכנ\"ל, ועץ השדה יתן פריו הוא ניצוץ האלקי' שנק' נר ה' כנ\"ל ונק' עץ השדה כי נמשך מעץ החיים שלמעלה מעה\"ד טו\"ר כו' יתן פריו לברר נפש הבהמיו' כנ\"ל ע\"י הממוצע כו' וכל אלה נעשה ע\"י גשמים דוקא שהוא בחי' קולות דתורה מפני שהמה הגורמי' לכל זה להיות הארץ תתן יבולה ועץ השדה יתן פריו כנ\"ל וזהו ונתתי גשמיכם בעתם ואז ממילא ונתנה הארץ יבולה וד\"ל.\n&lt;קעט&gt;",[["2982","91","<b>ואלה המלכי' אשר מלכו</b>: וישלח לו, לא."]]],[2100490518,"<h3>להבין שרשי הדברים הנ\"ל</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"2983\">1</sup> שרשי הדברים הנ\"ל. הנה מבואר<sup data-n=\"2984\">2</sup> בע\"ח בענין הצלם שניתן לאדם כו' שהוא נפש השכליו' המחבר החומר והצורה כו' ומברר ממנו כל יום מימי מספר השנים שניתן לו כו' ע\"ש. וביאור הדברים הנה כתיב ימי<sup data-n=\"2985\">3</sup> שנותינו בה\"ם שבעים שנה כו' ולכאורה יפלא מה זה שאומר לשון בה\"ם דמשמעו באותם שידועים שהמה בבחי' הפירוד מאלקות והן בחי' היכלות דנוגה כו' והאיך יבא מספר שנים ע'<sup data-n=\"2986\">4</sup> שנה דאדם בהיכלו' דנוגה, אך זה הענין מובן עפ\"י הנ\"ל משום דנפש האלקי' הנק' נר<sup data-n=\"2987\">5</sup> הוי' ירדה למטה ונתלבשה בלבושי' והיכלו' דנוגה שמעורב טו\"ר והוא הנק' צלם כמ\"ש שם בע\"ח ולבוש זה הנק' צלם מתברר גם הוא מן התערובו' טו\"ר שיש בו ע\"י שנשמה האלקי' נתלבשה בו והיינו שנק' בחי' ממוצע כי ע\"י הבירור שלו מברר הוא אח\"כ לנפש הבהמיו' שרובו ככולו רע לגמרי כי הנה הנפש השכלי' הרי יש בכחה לעשו' טוב ולמאוס ברע כמו לייגע השכל והמדו' שלה בגדולת ה' ותורתו ועבודתו וכמ\"כ להיפך שיש בה מחלק תערובו' רע כמו החכם להרע כמ\"ש חכמים<sup data-n=\"2988\">6</sup> המה להרע והכל בשכל של נפש המשכלת משום דשרשה מהיכלו' דנוגה שמעורב טו\"ר ויש להם השגה באלקו' ובחי' ביטול כו' וגם יש בהם מחלק הרע להיות בבחי' הפירוד והוא הנק' בזוהר<sup data-n=\"2989\">7</sup> ור\"מ להט החרב המתהפכת לפני עץ החיים כו' דאתהפכא פעמי' לטוב ופעמי' לרע כו' וכדוגמא זו בנפש השכלי' באדם ממש לפעמי' מתבוננת בהשגו' אלקו' ומתפעלת באוי\"ר וביטול ולפעמי' בהיפוך כו' ובהתהפכו' שלה לטוב וקדוש' נק' בירור הצלם ואז בכחה לברר גם הנפש הטבעי' החיונית שהוא כמו רוח הבהמה ממש בתאוה גופנית וכו' וזהו ימי שנותינו בהם ע' שנה שכל ע' שנה הוא ימי שנות הנפש האלקי' שבאה בהתלבשו' בבחי' הצלם הזה שמהיכלו' דנוגה וזהו בה\"ם בה\"ם ממש ובכל יום מע' שנה מברר ממנה בירור חדש עד שנשלם הבירור כפי הצורך כו' ולזה ניתנו מספר השנים לכאו\"א כפי צלמו שניתן לו כו' וזהו שתה<sup data-n=\"2990\">8</sup> עוונותינו לנגדך עלומינו למאור פניך כי כל ימינו פנו בעברתך כו' ימי שנותינו בהם כו' פי' שתה עוונתינו שמצד חלקי הרע דנפש השכלי' והבהמיו' דמקליפ' נוגה לנגדך ועלומינו אשר בהם למאור פניך כלומר שיתהפכו כולם לטוב ולקדוש' האלקי' להיות עומדי' למעלה למאור פניך כו' והתהפכו' זאת הוא ע\"י בחי' הצלם כשמברר נפש הבהמי' ומתברר גם הוא ע\"י ששוכן בו אור ניצוץ",[["2983","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק (1025 מג, א). לקמן בכרך ב' קודם חג השבועות נדפס עוד ביאור.\nהנחת המהרי\"ל ממאמר זה נדפס בלקו\"ת בחוקותי מז, ג ואילך."],["2984","2","<b>מבואר בע\"ח</b>: בלקו\"ת שם מציין — (שער כ\"ה [בדפוס שקלאוו תק\"ס ולפנינו ש' כו] פ\"א המתחיל ענין הצלם באמיתות נלע\"ד כו')."],["2985","3","<b>ימי שנותינו בהם שבעים שנה</b>: תהלים צ, י."],["2986","4","<b>ע' שנה. . דנוגה</b>: ראה ג\"כ סה\"מ תקס\"ג ח\"ב ע' תשכ. הנחה אחרת בלקו\"ת תצא לח, א."],["2987","5","<b>נר הוי'</b>: משלי כ, כז."],["2988","6","<b>חכמים המה לרע</b>: ירמי' ד, כב."],["2989","7","<b>בזוהר ור\"מ להט החרב המתהפכת</b>: בראשית ג, כד. וראה זהר ויחי רכא, ב. ע\"ח שער (מט) קליפות נוגה פ\"ג."],["2990","8","<b>שתה עוונותינו לנגדך</b>: תהלים צ, ח."]]],[2100490519,"האלקי ולזה ניתן מספר ע' שנה והיינו שמסיים ימי שנותינו בה\"ם ע' שנה בה\"ם דוקא וד\"ל.\n<b>והנה</b> ידוע בע\"ח<sup data-n=\"2991\">9</sup> בכמה דוכתי שעכשיו שם מ\"ה מברר שם ב\"ן וכמ\"ש והוא<sup data-n=\"2992\">10</sup> ימשול בך, אבל לע\"ל כשיתברר שם ב\"ן אז כתיב אשת<sup data-n=\"2993\">11</sup> חיל עטרת בעלה כו', והטעם מבואר שם לפי ששרש<sup data-n=\"2994\">12</sup> בחי' השבירה הי' בשם ס\"ג כמ\"ש כולו<sup data-n=\"2995\">13</sup> סג כו' והיינו בבחי' ב\"ן דס\"ג כמ\"ש ואלה<sup data-n=\"2996\">14</sup> המלכי' כו' וימלוך שהמלכו' &lt;קפ&gt;\nבשם ב\"ן כו' וכשיתברר לע\"ל שם ב\"ן יעלה ויבא לבחי' ומדרג' יותר גבוה גם מכמו שהי' קודם השבירה והוא שיבא במדרג' בחי' ס\"ג דס\"ג כו' ע\"ש.\n<b>וביאור</b> הדברים הנה להבין ענין שם מ\"ה המברר כו' צריך להקדים ענין מדרג' משה שאמר ע\"ע ונחנו<sup data-n=\"2997\">15</sup> מה כו' דהנה שרש נשמת<sup data-n=\"2998\">16</sup> משה היה מבחי' אור אבא כידוע, וע\"כ אמר ונחנו מה דהיינו מבחי' מ\"ה שבחכמה והוא בבחי' הביטול בתכלית כו' כמ\"ש במ\"א, אך הנה מ\"מ בחי' ביטול זה היה בבחי' אור בכלי ולא הי' בחי' ביטול במציאו' לגמרי למעלה מבחי' התלבשו' בכלי כו' שהרי היה לנשמתו חומר גופני להוליד בנים כו', והיינו מפני שהיה בבחי' אור בכלי שאינו אלא בחי' ביטול מוגבל מצד הגבלת הכלי בלבד והטעם הוא לפי ששרש נשמתו הי' ג\"כ רק מבחי' אחוריי' דאור אבא ולא מבחי' הפנימי' כי ידוע בתיבת<sup data-n=\"2999\">17</sup> משה שהוא בגי' קפ\"ד וקס\"א שהם שמו' מבחי' אחוריי' דאבא כו' והראיה לזה הוא ממה שניתן התורה על ידו והתורה היא בחי' נובלות<sup data-n=\"3000\">18</sup> חכמה של מעלה כידוע, והיינו בחי' אחוריי' בלבד לפי שעיקר ענין התורה הוא רק להבדיל<sup data-n=\"3001\">19</sup> בין טמא לטהור כו' שהוא בחי' המדו' שבשכל כשר פסול כו' וזהו ענין התלבשו' וירידות בחי' המוחי' דאבא להאיר במדות כמו להכשיר או לפסול עפ\"י השכל ולא בחי' עצמו' אור החכמה שלמעלה שהיא נק' קדש ומבואר בזוהר דקדש מלה בגרמי' כו' וד\"ל, ואמנם אעפ\"כ בחי' ביטול הי' בנשמתו אלא שהי' מבחי' החיצוניו' ועדיין הוא למעלה ממדרגת בחי' ההתלהבות שמצד ההתבוננו' הנק' אור אימא שנק' יש היפך בחי' מ\"ה דחכמה כידוע שהחכמה<sup data-n=\"3002\">20</sup> נק' אין והבינה יש כו'.",[["2991","9","<b>בע\"ח. . שם מ\"ה מברר שם ב\"ן</b>: ראה ע\"ח שער (ה) טנת\"א פ\"א. שער (י) התיקון פ\"ג. שער (מ) פנימיות וחיצוניות דרוש ה. לקו\"ת בחוקותי מז, ג."],["2992","10","<b>והוא ימשול בך</b>: בראשית ג, טז."],["2993","11","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד."],["2994","12","<b>ששרש בחי' השבירה הי' בשם ס\"ג</b>: ראה ע\"ח שער (ח) דרושי הנקודות פ\"א."],["2995","13","<b>כולו סג</b>: תהלים נג, ד."],["2996","14","<b>ואלה המלכי' כו' וימלוך</b>: וישלח לו, לא ואילך."],["2997","15","<b>ונחנו מה</b>: בשלח טז, ז."],["2998","16","<b>נשמת משה הי' מבחי' אור אבא. . כמ\"ש במ\"א</b>: ראה שער האמונה פנ\"ו. תו\"ח בשלח ריט, א."],["2999","17","<b>בתיבה משה שהוא בגי' קפ\"ד וקס\"א</b>: ראה לק\"ת (להאריז\"ל) שמות ב, י. וראה לקו\"ת פקודי ז, ד."],["3000","18","<b>נובלות חכמה של מעלה</b>: ב\"ר פי\"ז, ה."],["3001","19","<b>להבדיל בין טמא לטהור</b>: שמיני יא, מז."],["3002","20","<b>שהחכמה נק' אין והבינה יש</b>: ראה איוב כח, יד. וראה שערי אורה (לר\"י גיקטליא) שער יו\"ד קב, ב. ליקוט פירושים ומ\"מ לתניא פי\"ח. וראה פרדס שעה\"כ מערכת יש."]]],[2100490520,"<b>וזהו</b> ההפרש בין שבת ליו\"ט שבשבת נאמר מי<sup data-n=\"3003\">21</sup> כמוכה נאדר בקדש כו' כמ\"ש<sup data-n=\"3004\">22</sup> בזוהר פ' אמור כמ\"ש במ\"א וביו\"ט בחי' בינה מאיר וע\"כ המצוה ביו\"ט<sup data-n=\"3005\">23</sup> בשמחה כמ\"ש אם<sup data-n=\"3006\">24</sup> הבנים שמחה שהשמחה באה מצד ההשג' כו' ובשבת המצוה דוקא בעונג בלבד והוא בחי' עתיק' שמאיר באחוריי' דחכמה בבחי' הלבשה חיצוניו' אבל בחי' פנימיו' עתיק' שהוא מקור התענוג כמ\"ש כי<sup data-n=\"3007\">25</sup> עמך מקור חיים כו' אינו מאיר אלא בבחי' פנימי' דאור אבא, כידוע הכלל בע\"ח<sup data-n=\"3008\">26</sup> דפנימי' אבא הוא בחי' פנימי' עתיק' והכל א' כו', והענין הוא דאור העונג העליון שבפנימי' חכמה הוא בחי' ביטול האמיתי עד שאינו בא בבחי' כלי כלל וכלל וביטול זה לא הגיע משה בחייו כי יש בזה ההארה מבחי' פנימי' המאציל וכל העבודה דמשה היה בבחי' חיצוניו' דאור אבא בלבד והגם שמובדל בערך הוא מבחי' בינה מ\"מ אין לזה ערך עם בחי' פנימי' שם מ\"ה דחכמה, ולכך לא אמר רק ונחנו מה כלומר שיש מי שבטל כו' וגם כל האוי\"ר שהיו לו הגם שהיו בודאי בבחי' הביטול דחכמה ולא בבחי' התלהבות דבינה מ\"מ לא הי' בבחי' ביטול הפנימי שלמעלה מבחי' כלי לומר ונחנו מה אלא הוא בחי' התכללות ממש באור א\"ס ולא יוכל להתיישב בכלי כו' וד\"ל.\n<b>וזהו</b> שביקש משה הראיני<sup data-n=\"3009\">*26</sup> נא את כבודך פי' מבחי' פנימי' ע\"י שבבחי' פנימי' אבא שלמעלה מבחי' כלי וזהו כבודך ואין כבוד אלא חכמה כידוע אבל זהו נק' כבודך ממש והשיבו כי<sup data-n=\"3010\">27</sup> לא יראני האדם וחי כו' ואמרו ז\"ל בחייהם<sup data-n=\"3011\">28</sup> אינן רואין במיתתן רואין כו'. דהנה אמרו ז\"ל (במדרש)<sup data-n=\"3012\">29</sup> והנה טוב מאד טוב זה מלאך חיים מאד זה מלאך המות כו' &lt;קפא&gt;\nוהענין הוא משום דדוקא לאחר מיתה מפני שאינו בבחי' הכלים של הגוף אזי יוכל לראות בבחי' אור א\"ס שלמעלה מבחי' כלי אבל כל זמן שהוא חי בגוף לא יוכל לראו' אור א\"ס שלא בבחי' כלי כו' והטעם לזה מבואר למעלה משום דמברר מחשוכא לנהורא כו' ושרש הנפש הבהמיו' בעולם התוהו כו' ולהבין ביאור ושרש הדברים הנה תחלה יש להבין מהו ענין כאור<sup data-n=\"3013\">*29</sup> שבעת הימים ולמה נק' בשם אור בלבד כו'.\n<b>דהנה</b> ידוע שעיקר ההפרש בין בחי' התוהו לבחי' התיקון הוא שבבחי' התוהו<sup data-n=\"3014\">30</sup> היו האורו' גדולים מאד מאד והכלים היו קטנים לפי ערך האורות והיו רק",[["3003","21","<b>מי כמוכה נאדר בקדש</b>: בשלח טו, יא."],["3004","22","<b>כמ\"ש בזהר פ' אמור כמ\"ש במ\"א</b>: צד, א. ד\"ה זהר אמור ת\"ח בשעתא דישראל מליל שבת פ' אמור תקס\"ו (נדפס בסידור ריז, א ואילך)."],["3005","23","<b>ביו\"ט בשמחה ובשבת. . בעונג</b>: דברים טז, ד. ישעי' נח, י. וראה סה\"מ תש\"ט ס\"ע 130 ובהערת כ\"ק אדמו\"ר זי\"ע שם."],["3006","24","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["3007","25","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["3008","26","<b>בע\"ח דפנימי' אבא הוא בחי' פנימי' עתיק</b>: פרע\"ח שער הק\"ש פט\"ו. הובא בלקו\"ת נצבים מט, ד. וש\"נ. וראה המשך תרס\"ו ע' צה ואילך."],["3009","*26","<b>הראיני נא את כבודך</b>: תשא לג, יח."],["3010","27","<b>כי לא יראני האדם וחי</b>: שם, כ."],["3011","28","<b>בחייהם אינן רואין</b>: ראה תורת כהנים ויקרא א, א. ילקו\"ש ויקרא ריש רמז תלא. במד\"ר ספי\"ד. כלה רבתי פ\"ג."],["3012","29","<b>(במדרש) והנה טוב מאד זה מלאך חיים</b>: בראשית א, לא. ראה ילקוט שמעוני שם רמז טז. וש\"נ. ב\"ר פ\"ט, י. זהר בהקדמה יד, א. וראה תו\"א תשא פו, ב."],["3013","*29","<b>כאור שבעת הימים</b>: ישעי' ל, כו."],["3014","30","<b>התהו. . נקודות</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תעו ואילך. וש\"נ."]]],[2100490521,"ז' נקודות בלבד זה תחת זה כו' ובבחי' התיקון<sup data-n=\"3015\">31</sup> בהיפך שהאורות נעשי' קטנים מהכלים כי בחי' הכלים גדולים ורחבים וגם נעש' ריבוי אורות בהתכללות כו' והנה לפ\"ז נק' בחי' התוהו רק בשם אור ולא בשם כלי אחר שהעיקר שם הוא רק בחי' אור ולא כלי כי האורות שם בהתרחבות גדולה והכלים קטנים מאד כו' ובבחי' התיקון בהיפך שנק' רק בשם כלי כי הכלי מרובה מן האור כו' וא\"כ לעתיד כשיבורר עולם התוהו שנפל בשבירה כנ\"ל ששם ב\"ן יתברר ויבא לשרשו בבחי' ס\"ג כו' הרי יהי' אורו אז גדול בתכלית ההגדלה עד שלא יהי' נק' רק בשם אור ולא בשם כלי כלל כמו שהי' קודם השבירה כו' וזהו שנק' אור שבעת הימים כלומר שכולו אור וכולל אורות כל ז' הימים שהן בחי' הכלים דהיינו ז' ימי בראשית כו' הנק' שבעת ימי הבנין כו' לפי שהוא בבחי' אור דתוהו שהאור שם בתכלית הגדלו' כנ\"ל ולהיות כי יתעלה שם ב\"ן למעלה גם משרשו בב\"ן דס\"ג והוא לבחי' ס\"ג דס\"ג כנ\"ל ע\"כ אמר והיה אור הלבנה שם ב\"ן כו' שבעתיים כאור ז' הימים בערך כו' ואז נאמר אשת<sup data-n=\"3016\">*31</sup> חיל עטרת בעלה למעלה משם מ\"ה דתיקון כו' וד\"ל.\n<b>והנה</b> עוד יהי' יתרון מעלה לעתיד מלבד זה דהנה עכשיו בחי' אורות דתוהו קודם הבירור המה בלתי מוגבלים בבחי' כלי לפי ערך כידוע והוא הנק' מאד שהאדם אינו רואה אלא במיתתו כנ\"ל בפי' כי לא יראני האדם וחי כו' אבל לעתיד יוכל לראות האדם בחי' אור א\"ס שלמעלה מבחי' כלי גם בהיותו בבחי' כלי גוף והוא ענין תחיית המתים לעתיד דהנה מה דכתיב לעתיד הנה<sup data-n=\"3017\">32</sup> ישכיל עבדי כו' וגבה מאד בלי גבול דהיינו בבחי' אור דתוהו שלפני התיקון וזהו כמ\"ש למעלה בענין אור ז' הימים אעפ\"כ הנה אור זה יבא גם בבחי' כלי ולא כמו עכשיו כו' שהרי בתחיית המתים נאמר כי<sup data-n=\"3018\">33</sup> טל אורות טלך וארז\"ל<sup data-n=\"3019\">34</sup> זה הטל שעתיד להחיות בו המתים ומבואר בזוהר<sup data-n=\"3020\">35</sup> דהיינו בחי' טלא דבדולחא כו' והוא ההארה מבחי' פנימי' עתיק' שעכשיו אינו מתלבש בכלי ואפי' בכלי החכמה כנ\"ל ולעתיד יתלבש בכלי והוא טלא דנטיף מעתיקא להחיות המתים וענין התלבשותו ודאי שאינו בא דרך סדר השתלשלו' והמופת לזה הוא מובן מתוך אופן התחייה שיחיו המתים דכתיב בהו במתים<sup data-n=\"3021\">36</sup> שהחי' יחזקאל מארבע הרוחו' בואי הרוח ופחי כו' והיינו שיהי' עיקר התחיה בעצמות בלבד וכמ\"ש ועצמותיך<sup data-n=\"3022\">37</sup> יחליץ פי' מן העצמו' יחליץ ויבנה בנין הגוף עם הנפש ולא יהי' כמו גוף הנולד מזווג זכר ונקבה כלל א\"כ לא יהי' בערך הגשמת החומר הגופני שנולד מזווג גשמי דזכר ונקבה גשמיי' לא מיני'",[["3015","31","<b>התיקון. . שהאורות. . מהכלים</b>: ראה ע\"ח שער (י) התיקון פ\"ה."],["3016","*31","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד."],["3017","32","<b>הנה ישכיל עבדי</b>: ישעי' נב, יג."],["3018","33","<b>כי טל אורות טלך</b>: ישעי' כו, יט."],["3019","34","<b>וארז\"ל זה הטל שעתיד להחיות בו המתים</b>: שבת פח, ב. תניא ספל\"ו. וראה זח\"ג רפח, א. הנסמן במ\"מ הגהות והערות קצרות לשם (ע' רכד)."],["3020","35","<b>בזוהר. . טלא דבדולחא</b>: ראה זהר (אדרא רבא) נשא קכט, ב. (אדרא זוטא) האזינו רפח, א."],["3021","36","<b>במתים שהחי' יחזקאל מארבע הרוחו'</b>: ראה יחזקאל לז, ט."],["3022","37","<b>ועצמותיך יחליץ</b>: ישעי' נח, יא."]]],[2100490522,"ולא דוגמתו אחר שאור &lt;קפב&gt;\nהאלקי יכנם בעצמו' היבשי' הרי יחיו בחיי האור האלקי שנתלבש בטל המחי' ולא בחיים גשמיי' שבבשר הגשמי כמו עכשיו כו' וזהו ועצמותיך יחליץ וד\"ל והרי מובן מזה דטלא דנטיף מעתיקא נכנס ונתלבש בכלי ממש והוא בעצמו' היבשי' שיחיו על ידו ויתקיימו קיום נצחי כו' וא\"כ מה שעכשיו אין רואין אלא במיתתן והוא בבחי' מאד דוקא דהיינו בלא כלי וגבול כנ\"ל לעתיד יראו אור א\"ס שלמעלה מבחי' כלי בהיותם בבחי' כלי גוף כמו אחר התחייה, ועד\"ז יובן המאמר הנ\"ל טוב זה מלאך חיים מאד זה מלאך המות לפי שאחר מיתה דוקא יוכל האדם לחיו' מחיי החיים מבחי' מאד שלמעלה מבחי' הכלי והוא בחי' פנימי' דע\"י כנ\"ל וגם קודם התחייה יוכל לראות ולהשיג עכ\"פ בבחי' מא\"ד זה אע\"פ שאינו מתלבש בו בבחי' כלי ממש וזהו מטעם שבירר כבר כל הרפ\"ח ניצוצי' דתוהו כו' והגיע לשרשו בבחי' אור דתוהו שהוא אינו מוגבל בכלי ולכך נק' אור ז' הימים כנ\"ל והיינו שהשיבו כי לא יראני האדם וחי בחייהם אינן רואין כו' וד\"ל.\n<b>וזהו</b> ענין ק\"ש באמרו ואהבת<sup data-n=\"3023\">38</sup> את ה' כו', דהנה פי' בכל<sup data-n=\"3024\">39</sup> לבבך הוא נפש הטבעית הבהמיו' והיינו בשני יצריך כו' והוא רביעית דם גשמי שבלב שהנפש החיוני' שוכנת בה כידוע ופי' בכל נפשך הוא בחי' נפש השכלי' הנק' צלם כנ\"ל הממוצע ומחבר נפש האלקי' בנפש הבהמיו' ומברר כל הברורי' כו' וכאשר יתהפכו ויתבררו כל חלקי הרע שבהם אזי עי\"ז תגיע הנפש האלקי' למדרגה שלא הי' לה גם בעודנה צרורה בצרור החיים בג\"ע קודם בואה לגוף והוא אהבת בכל מאדך בלי גבול כי כל מאד ענינו בלי גבול וכמ\"ש הנה ישכיל עבדי ירום ונשא וגבה מאד וזהו הירידה שלצורך עלי' כנ\"ל והטעם הוא כי שרש תולדו' הנשמו' האלקי' בא מיחוד דזו\"נ כידוע ובחי' ז\"א הוא בחי' התיקון ששם האורו' במיעוט והכלים בריבוי והגדלה כנ\"ל והיינו דוקא בבחי' הגבלה וזהו כמו שאמר אליהו חי<sup data-n=\"3025\">40</sup> ה' אשר עמדתי לפניו פי' לפניו היינו קודם בואו לגוף שעמדה נשמתו לפני ה' והעמידה היתה שם בבחי' כלי וגבול ולכך נק' עמידה ולא הליכה כי כל עמידה הוא בבחי' כלי וכל הליכה הוא בלתי כלי וכמ\"ש ונתתי<sup data-n=\"3026\">41</sup> לך מהלכים בין העומדים האלה שהמלאכי'<sup data-n=\"3027\">42</sup> נק' עומדים כידוע והנשמה כשבאה לגוף דוקא אז נק' מהלך מטעם שמבררת הצלם דנוגה ושרשו מבחי' אורו' דתוהו שכולו אור ולא כלי כנ\"ל ע\"כ אז יכול האדם לבא לבחי' מאד והוא להשיג באור א\"ס שלמעלה מבחי' כלי הנק' מאד ואע\"פ שלא יראה וישיג ממש כל זמן שהוא חי כנ\"ל בפי' בחייהם אינן רואי' מ\"מ אפס קצהו מאותו האור מאיר בנפש האלקי' בכל יום בק\"ש באמרו בכל מאדך והוא ע\"י בירור הצלם דוקא משא\"כ קודם שירדה לגוף שהיתה דוקא בבחי' כלי דהיינו מבחי' התיקון כנ\"ל וד\"ל.",[["3023","38","<b>ואהבת את ה'</b>: ואתחנן ו, ד."],["3024","39","<b>בכל לבבך. . בשני יצריך</b>: ואתחנן שם. ברכות נד, א (במשנה)."],["3025","40","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז."],["3026","41","<b>ונתתי לך מהלכים בין העומדים</b>: זכרי' ג, ז."],["3027","42","<b>שהמלאכי' נק' עומדים</b>: ראה תו\"א וישב ל, סע\"א. לקו\"ת בחוקותי מה, א. ובכ\"מ."]]],[2100490523,"<b>ובזה</b> מובן מה שאמרו ז\"ל בפסוק והיה<sup data-n=\"3028\">43</sup> מספר בנ\"י כו' אשר לא יספר דכשעושין רצונו של מקום היינו שמבררי' ומהפכי' חשוכא לנהורא בבחי' צלם דנוגה הנ\"ל כמ\"ש ימי שנותינו בהם ע' שנה וכנ\"ל אזי כתיב אשר לא יספר בבלתי גבול ומספר מטעם שבחי' התוהו בשרשו בס\"ג דס\"ג כו' &lt;קפג&gt;\nלמעלה מבחי' מספר וגבול הוא כנ\"ל אבל כשאין עושין רצונו כו' ואינם מבררים כלום הרי מצד שרשם של הנשמו' הם מבחי' התיקון שהוא בא בבחי' מספר והוא ס\"ר ניצוצו' לפי שכל<sup data-n=\"3029\">44</sup> מדה מז\"א מתחלק לי' וי' לק' וק' לאלף כו' כמ\"ש בע\"ח וד\"ל. וזהו ואהבת את ה' כו' את הטפל כו' פי' להיו' טפל ובטל בבחי' הביטול האמיתי שלמעלה מבחי' כלי כענין ישראל<sup data-n=\"3030\">45</sup> עלה במחשבה כו' והוא אהבת בכל מאדך שהוא בחי' התכללו' ממש כו' וד\"ל.\n<b>וזהו</b> אם בחוקותי תלכו ב' חקיקות כו' כמ\"ש למעלה. וביאור ענין החקיקה הראשונה בפסוקי דזמרה לפני ק\"ש כו' יובן בהקדים תחלה פי' ענין פסוקי<sup data-n=\"3031\">46</sup> דזמרה דהנה הטעם שנק' בשם פסוקי דזמרה הוא מענין זמירה וכריתה כמו וכרמך<sup data-n=\"3032\">47</sup> לא תזמור כו' והענין הוא משום שע\"י פסוקי' הללו נכרתו החיצונים ונפרדו מן הקדושה כמ\"ש יתפרדו<sup data-n=\"3033\">48</sup> כל פועלי און כו' ונק' זמיר עריצים שהעריצים נזמרו ונכרתו כו' וזהו מ\"ש רוממו'<sup data-n=\"3034\">49</sup> אל בגרונם ואז נעשה חרב פיפיו' כו' להכרית יניקו' החיצונים וה\"ז ממש כמשל העושה כלי מעץ הגולם שצריך לעשות בו ב' חקיקות חקיקה הראשונה צריך לחקוק אותו מבחוץ סביב סביב ולא יהי' כמו דף ונסר עב בלתי ראוי לכלי כלל כו' ואח\"כ יחקוק בו חלל להיות חקוק בחקיקה פנימי' כדי שיהי' כלי בית קיבול כו' והנה החקיקה מבחוץ הוא בפסוקי דזמרה כשנזמרו ונכרתו החיצונים כי ע\"י רוממו' אל אשר בגרונם חרב פיפיות כו' כי כתיב סביב<sup data-n=\"3035\">50</sup> רשעים יתהלכון וכן כתיב ונוגה<sup data-n=\"3036\">51</sup> לו סביב כו' שיניקו' החיצונים סביב לקדוש' מבחוץ הוא וע\"כ צריך תחלה לחקוק מבחוץ שלא יקרב זר כו' ואז הוא ראוי להיו' כלי בית קיבול בחקיקה הפנימי' בשעת ק\"ש באמרו ואהבת כו' וביאור דבר זה יובן בעבודה שבלב בהתפעלות הנפש בשעת התפלה דהנה ע\"י ההתבוננו' בגדולת ה' בהכרח שתתפעל הנפש אבל יש בזה ב' מדרגות הא' התפעלו' אהבה ממש שנתפעל בהתבוננו' עד שנולד לו אהבה ותשוקה גדולה לדבקה בה' כו' ואמנם אין התפעלות זאת בנפש מיד שמתבוננת בגדולת ה' אלא לאחר שעה אבל מיד שמתבוננת אין לה התפעלות אהבה עדיין אלא רק שתתפעל הנפש מצד רוממו' ה' וגדולתו עד שיפול ממנה כל חלקי הרע הסובבים אותה מכל צד כמשל הנכנס להיכל המלך פנימה שמצד רוממו' המלך יפול לבבו מכל מה שהי' דבוק בו תחלה כו' וזה נק' התפעלות",[["3028","43","<b>והיה מספר בנ\"י. . דכשעושין רצונו של מקום</b>: הושע ב, א. יומא כב, א."],["3029","44","<b>שכל מדה מז\"א מתחלק לי' וי' לק' וק' לאלף כמ\"ש בע\"ח</b>: ראה ע\"ח שער (כד) פרקי הצלם פ\"א. ראה מאמרי אדה\"א קונטרסים ע' שנג. במדבר ח\"א ס\"ע פב ואילך."],["3030","45","<b>ישראל עלה במחשבה</b>: ראה ב\"ר פ\"א, ד."],["3031","46","<b>פסוקי דזמרה. . זמירה וכריתה</b>: ראה ישעי' כה, ה. זהר וילך רפד, א. לקו\"ת פקודי ח, א."],["3032","47","<b>וכרמך לא תזמור</b>: בהר כה, ד."],["3033","48","<b>יתפרדו כל פועלי און</b>: תהלים צב, י."],["3034","49","<b>רוממו' אל בגרונם</b>: תהלים קמט, ו."],["3035","50","<b>סביב רשעים יתהלכון</b>: תהלים יב, ט."],["3036","51","<b>ונוגה לו סביב</b>: יחזקאל א, כז."]]],[2100490524,"ג\"כ שהרי ענין התפעלות הוא שנתפעל וניזוז ממקומו כמו עד\"מ פעולת התנועה גשמית וכיוצא כך התפעלות הנפש שנתפעלה והופשטה מבחי' הרע הסובבי' אותה מצד ההתבוננו' ברוממו' ה' והיינו ענין החקיקה מבחוץ בלבד שהוא רק ענין הכריתה ליניק' החיצונים שלא ימנעו כניסת אור אלקי בהתפעלו' אהבה כו'.\n<b>וזהו</b> מ\"ש סבוני גם סבבוני כו' בשם ה' כי אמילם כו' והוא זמור עריצים בפסוקי דזמרה עד ק\"ש להכריתם מכל צד בכדי שיוכל אח\"כ להתפשט בנפש האלקי' בחי' אהבה האלקי' שהוא בחי' ההתפעלו' ממש דהיינו שנקודת הלב נחקק וניטל ממקומו כמ\"ש ולבי<sup data-n=\"3037\">52</sup> חלל כו' וכמ\"ש כלה<sup data-n=\"3038\">53</sup> שאירי לבבי והוא באהבה דבכל מאדך בק\"ש והיא הנק' חקיקה פנימי' עד\"מ &lt;קפד&gt;\nשחוקקים לכלי להיות בו בית קיבול כו' והוא העיקר וההתפעלו' שבפסוקי דזמרה לפני ק\"ש אינה אלא כמו הכנת הגולם בלבד שיוכל להיו' כלי בית קיבול כו' וד\"ל. ובזה יובן מה שאר\"י יהא<sup data-n=\"3039\">54</sup> חלקי מגומרי ההלל בכל יום כו' דמשמע שלא הי' גומר פסוקי דזמרה בכל יום וכן משמע במשנה שלא הזכיר הדין בפסוקי דזמרה אלא רק הברכו' שלפני ק\"ש כדתנן בשחר<sup data-n=\"3040\">55</sup> מברך שתים לפניה כו', כי התנאים צדיקי' גמורים היו מצד שרש נשמתם שהי' ממדרגה הגבוה וכידוע וע\"כ לא הי' גם חומריות גופם מסתיר אור נשמתם כ\"כ ומה גם שהי' להם מס\"נ בתמידו' והי' גופם הבהמי ג\"כ מופשט מכל דבר חומרי כי נזדכך גופם כי ביררו כל בחי' הצלם שלהם בתכלית הבירור כו' וע\"כ לא היו צריכים להאריך בפסוקי דזמרה כ\"כ להיותו רק בשביל זמור עריצים שהוא בחי' החקיקה מבחוץ בלבד והם לא היו צריכים לזה כ\"כ אבל הנה אנחנו ששרש הנשמות בדורו' האחרוני' הוא מבחי' עקביי' הנק' עקבו'<sup data-n=\"3041\">56</sup> משיחא כידוע והנפש הבהמי' מסתירי' ביותר צריך להאריך יותר בפסד\"ז כי צריך חקיקה רבה מבחוץ וד\"ל.\n<b>ועתה</b> יש להבין ענין החקיקה השנית דבחוקותי שהוא החקיקה מבפנים שע\"י המצות שנק' חוקים דוקא כמ\"ש למעלה כו', דהנה שרש כל המצות הוא מבחי' הכתר<sup data-n=\"3042\">57</sup> שהרי הם הנק' תר\"ך עמודי אור שהם תרי\"ג מצות דאוריי' וז' מצות דרבנן כידוע ובאדר\"ז<sup data-n=\"3043\">58</sup> מבואר שהמה הנק' תרי\"ג ארחי' שבגלגלתא כו'.\n<b>אך</b> מה שאמר בזוהר<sup data-n=\"3044\">59</sup> דאוריי' מחכמה עילא' נפקת אין הענין מחכמה ולא מכתר אלא הענין הוא דנפקת מחכמה אבל שרשה בכתר ושרש הענין דהנה בכתר",[["3037","52","<b>ולבי חלל</b>: תהלים קט, כב."],["3038","53","<b>כלה שאירי ולבבי</b>: תהלים עג, כו."],["3039","54","<b>יהא חלקי מגומרי ההלל בכל יום</b>: שבת קיח, ב."],["3040","55","<b>בשחר מברך שתים</b>: ברכות פ\"א מ\"ד."],["3041","56","<b>עקבו' משיחא כידוע</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' עו. קונטרסים ע' תיח. הנחות תקע\"ז ע' רג ובהנסמן בהנ\"ל."],["3042","57","<b>הכתר. . תר\"ך עמודי אור</b>: ראה רקאנטי (קרוב ל) ס\"פ לך. (ירושלים תשכ\"א כג, ג). פרדס שער (ח) מהות והנהגה פ\"ג."],["3043","58","<b>ובאדר\"ז מבואר. . תרי\"ג ארחי' שבגלגלתא</b>: ראה זהר (אדרא רבא) נשא קכט, א. קלו, א."],["3044","59","<b>בזוהר דאורייתא מחכמה עילא' נפקת</b>: זח\"ב קכא, ב. פה, א."]]],[2100490525,"עצמו יש י' ספירו' כתר שבכתר וחכמה שבכתר כו' עד מל' שבכתר כי כמו שבכל ספי' כלול מי' כמו החכמה יש בה י' ספי' כתר שבחכמה וחכמה שבחכמה כו' כך יש בכתר עצמו י' ספי' ובבחי' כתר שבכתר נבדל שם לגמרי מבחי' החכמה והוא הנק' רצון הפשוט ובזוהר<sup data-n=\"3045\">60</sup> נק' רעוא דכל רעוין ואין טעם לרצון זה אפי' טעם כמוס אין לו דהיינו בחי' חכמה שבכתר הנק'<sup data-n=\"3046\">61</sup> חכמה סתימא' דא\"א שהוא עד\"מ כמו הטעם הכמוס ונק' חכמה סתומה או תעלומו' חכמה אבל בכתר שבכתר עדיין נבדל מבחי' ח\"ס זו והיינו גם מלהיות מקור לאור חכמה דאצי' הנק' אור אבא אבל בח\"ס דא\"א שהוא בחי' חכמה שבכתר כבר מלובש הרצון הפשוט בטעם אלא שהוא נק' ח\"ס והוא עכ\"פ מקור להיות בחי' חכמה בגילוי באצילו' כו' והנה המצות ששרשן עדיין בבחי' כתר שבכתר הנק' רצון פשוט כנ\"ל אין להם טעם כלל וכלל בגילוי באבי\"ע מפני שבשרשן הראשון והוא בבחי' הכתר שאינם מלובשים עדיין שם בבחי' ח\"ס כנ\"ל והמה המצות הידועו' כמו מצות<sup data-n=\"3047\">62</sup> פרה אדומה אשר מטמא טהורי' כו' ועלי' אמר שלמה אמרתי<sup data-n=\"3048\">63</sup> אחכמה והיא רחוקה ממני וכיוצא בה יש הרבה מצות שלא נמצא להן טעם ושכל למטה כמו מצות תפילין וציצית ומל\"ת דשעטנז וכלאים וכיוצא אבל אותן המצות ששרשן מלובש בח\"ס דא\"א שהוא מקור לאור חכמה דאצי' ומשם משתלשל האור בבי\"ע עד בחי' חכמה דעשי' לכך נמצא להם טעם ושכל גם בשכל &lt;קפה&gt;\nוחכמה המושג לנו כמו מצות השבת ואיסור מלאכה בשבת משום כי<sup data-n=\"3049\">64</sup> בו שבת ואיסור גניבה וניאוף כו' ומצות צדקה וכיוצא בהם וד\"ל. והנה אותן המצות שהם למעלה מן הטעם לגמרי להיותם מבחי' כתר שבכתר כנ\"ל לפי שמעלתם בשרשם מאד נעלה ע\"כ בהם דוקא יוכל להיות בחי' החקיקה השנית הנק' חקיקה מבפנים כי בנפש הבהמיו' להיות שהיא בסוף כל ההשתלשלו' שאין עוד למטה הימנה צריך שיעשה בה חקיקת בית קיבול ממקום הגבוה ביותר דוקא וכדוגמא זו מצינו במ\"א<sup data-n=\"3050\">65</sup> שכל היותר נמוך צריך שיאיר שם ממקום היותר גבוה והיינו מ\"ש ועברתי<sup data-n=\"3051\">66</sup> בארץ מצרים אני ולא מלאך כו' דידוע הטעם משום דקליפת<sup data-n=\"3052\">67</sup> מצרים במ\"ט שערי טומא' שהוא תחתית כל המדרגו' אין ההארה שמה מהפך מחושך גדול כזה לאור כ\"א מבחי' האור היותר עליון מבחי' אני כו' וכך בנפש הבהמיו' לעשו' בה חקיקה שתוכל ליכלל באחד אינו אלא מבחי' מצות שנק' חוקותי שהם מבחי' רעוא דכל רעוין היותר עליון מכל ההשתלשלו' כו' וד\"ל. ובזה יובן מ\"ש באר<sup data-n=\"3053\">68</sup> חפרוה שרים כו'",[["3045","60","<b>ובזוהר נק' רעוא דכל רעוין</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב."],["3046","61","<b>הנק' חכמה סתימא'</b>: ראה לקו\"ת שלח מט, ג. שה\"ש מח, א. ס' מאמרי אדה\"ז ענינים בתחלתו. מאמרי אדה\"א בראשית ע' לו. תג. ויקרא ח\"ב ע' תקג. תתטז. דברים ח\"א ע' רכז. דרושי חתונה ע' תרצט. שער האמונה נא, ב. ובכ\"מ."],["3047","62","<b>מצות פרה אדומה אשר מטמא טהורי'</b>: ראה אוה\"ת חקת ע' תתד — כהובא בילקוט פ' חקת דקס\"ו ע\"ג."],["3048","63","<b>אמרתי אחכמה והיא רחוקה ממני</b>: קהלת ז, כג."],["3049","64","<b>כי בו שבת</b>: בראשית ב, ג."],["3050","65","<b>במ\"א שכל היותר נמוך צריך שיאיר שם ממקום היותר גבוה</b>: ראה תו\"א בראשית ד, א. מגילת אסתר צג, ג. ק, א. לקו\"ת שלח לח, ב."],["3051","66","<b>ועברתי בארץ מצרים אני ולא מלאך</b>: בא יב, יב. ספרי תבוא כו, ח. זהר (מהנ\"ע) וירא קיז, א. הגש\"פ."],["3052","67","<b>דקליפת מצרים במ\"ט שערי טומא'</b>: ראה תו\"א קט, ד ובכ\"מ."],["3053","68","<b>באר חפרוה שרים</b>: חוקת כא, יח. וראה לקו\"ת מטות פה, ד — וכמ\"ש בע\"ח של\"א פ\"ז ושער הירח פ\"ג ובפע\"ח שער ק\"ש שעל המטה פי\"א ופ\"ו."]]],[2100490526,"במחוקק במשענותם פי' באר הוא בחי' מל' דאצי' כללו' נ\"י ולעשות בהם בחי' חקיקה הוא בחי' בית קיבול להיו' להם התשוקה וההתכללו' הנ\"ל היינו בחי' יסוד דנוק' שהוא בחי' בית קיבול וכו' ולהיות אל<sup data-n=\"3054\">69</sup> אישך תשוקתך בבחי' ה\"ג שביסוד כו' צריך לזה שיהי' החופר והחוקק ממקום ומדרגה גבוה ביותר מטעם הנ\"ל והם הנק' שרים שהם החוקים הנ\"ל ואעפ\"כ ירדו גם הם ונתלבשו בבחי' חכמה דמשה כי כל המצות כמו מצות פרה כו' ניתנו ע\"י משה<sup data-n=\"3055\">70</sup> שהי' מבחי' מ\"ה דחכמה ולכך מחוקק<sup data-n=\"3056\">71</sup> זה משה כי בדרך כלל הרי הוא המחוקק אך שרש החקיקה הוא ע\"י המצות שנק' חוקים מטעם הנ\"ל ואם לאו נק' כנ\"י בתולה ואיש<sup data-n=\"3057\">72</sup> לא ידעה כו' ובעבודת ה' היינו כמו מי<sup data-n=\"3058\">73</sup> שלבו אטום כבתולה שהיא אטומה כו' וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> שאמרו ז\"ל אם בחוקותי תלכו הלואי אם<sup data-n=\"3059\">74</sup> בחוקותי תלכו, פי' תלכו הוא בחי' אהבה דבכל מאדך בלי גבול שנק' הליכה שהיא בלי גבול היפך העמידה כנ\"ל ואין זה אלא כשהנשמה האלקי' מלובשת בגוף דוקא מטעם הנ\"ל אך הלואי אם ע\"י ב' חקיקות הנ\"ל תלכו דוקא והוא החקיקה מבחוץ בפסוקי דזמרה שלפני ק\"ש כנ\"ל הנק' זמור עריצים וע\"י החקיקה השנית שנק' חקיקה מבפנים בבחי' ביטול הרצון ע\"י החוקים שלמעלה מן השכל כו' ואם לאו אין הליכה זו כלום, כי עד\"מ האסור בשלשלאות של ברזל האיך יוכל לילך ממקום למקום כך אם אסור וקשור בחומריו' נפש הבהמיו' ולא נחקק מבחוץ וגם הוא גולמי בפנים בלתי החוקים הנ\"ל האיך יהי' בו בחי' תלכו באהבה דבכל מאדך ולכך אמרו הלואי אם בחוקותי תלכו וד\"ל.\n<b>ואת</b><sup data-n=\"3060\">75</sup> מצוותי תשמרו ועשיתם אותם, פי' אחר שאמר אם בחוקותי תלכו כנ\"ל אמר ואת מצוותי תשמרו המצות הללו הם אשר מבחי' פנימי' דעתיקא שלמעלה גם מבחי' הרצון כי הנה ידוע דיש בחי' תענוג מלובש ברצון והוא הפנימי' לרצון ונק' חפץ ובכלל הן י\"ג חוורתי דגלגלתא שרש הרצון שבכל מצוה<sup data-n=\"3061\">76</sup> שנק' ארחי' כמ\"ש במ\"א (ע\"פ אשת חיל עט\"ב) וזהו מרומז בתיבת &lt;קפו&gt;\nאש\"ר קדשנו כו' כי אש\"ר<sup data-n=\"3062\">77</sup> זה לשון תענוג הוא כנ\"ל כי שרש המצו' מבחי' פנימי' עתיקא והוא מבחי' מל' דא\"ס ממש ולכך אמר ואת מצוותי תשמרו להיות כי בהם משתמר אור א\"ס שבבחי' פנימי'",[["3054","69","<b>אל אישך תשוקתך</b>: בראשית ג, טז."],["3055","70","<b>משה. . מ\"ה דחכמה</b>: ראה בשלח טז. ז. וראה זהר (רע\"מ) כח, א. לד, א."],["3056","71","<b>מחוקק זה משה</b>: ראה ברכה לג, כא. וראה לקו\"ת מטות פח, א."],["3057","72","<b>ואיש לא ידעה</b>: בראשית כד, טז."],["3058","73","<b>מי שלבו אטום כבתולה</b>: ראה בבא בתרא יב, ב. וראה לקו\"ת שה\"ש ב, ד. מטות פה, ד."],["3059","74","<b>אם בחוקותי. . הלואי אם בחוקותי תלכו</b>: בחוקותי כו, ג. וראה ע\"ז ה, סע\"א."],["3060","75","<b>ואת מצוותי תשמרו ועשיתם אותם</b>: המשך הכתוב בחוקותי שם."],["3061","76","<b>מצוה שנק' ארחי'</b>: תהלים כה, י. ראה זח\"ג קכט, א. וראה בביאור האריז\"ל לזהר שם. משנת חסידים מסכת אריך אנפין ספ\"ד. לקו\"ת פ' ראה כא, ד."],["3062","77","<b>אשר לשון תענוג</b>: ויצא ל, יג. ראה תקו\"ז ת\"ל (עד, ב). תל\"ט (עט, א). תו\"א שמות נג, ב."]]],[2100490527,"עתיקא וזהו כי נר<sup data-n=\"3063\">78</sup> מצוה כמו הנר שמחזיק השמן והאור כו' להיות שיש ביכולתם להיות בחי' כלי לאור א\"ס ולא בדבר אחר זולתם וע\"ד דוגמא שלעתיד יהי' בחי' [הגוף] כלי להשרא' אור א\"ס כמ\"ש למעלה בענין כי טל אורו' טלך כו' בתח\"ה וגם ע\"י מצות בהם משתמר אור א\"ס שלמעלה מבחי' כלי להיו' שוכן בכלי כו' וזהו למעלה ממדרגת תלכו שאמר תחלה אך שאומר כסדר הצריך בתחלה יהי' החקיקה כמ\"ש באר חפרוה שרים כו' במחוקק כנ\"ל ואח\"כ ואת מצוותי תשמרו לקבל האור כו' וד\"ל. ומה שאמר ואת מצוותי תשמרו ועשיתם אותם לכאורה אינו מובן ענין כפל לשון שכפל לומר עשי' אחר השימור כו', אך הנה לכאורה אינו מובן הטעם בכל פעולה מן הפעולות כשפועל האדם ועושה דבר מה למה נק' בשם מעשה דוקא ולא בלשון אחר כי לשון עושה אינו מוכרח בדקדוק לה\"ק על פעולת דבר מה אלא לשון עובד כמו ששת<sup data-n=\"3064\">79</sup> ימים תעבוד כו' בכל עבודה בשדה כו' וכיוצא ולא לשון עושה.\n<b>אמנם</b> הענין הוא דלשון עושה שם המושאל הוא ממקום אחר על הפעולה כי שרש לשון עושה הוא מלשון כפייה והכרח כמו גט<sup data-n=\"3065\">80</sup> מעושה וכן גדול<sup data-n=\"3066\">81</sup> המעשה כו' ונגזר זה מתיבת עשו<sup data-n=\"3067\">82</sup> דדי בתולייך כו' וכיוצא והוא ענין כל דבר הנמשך בעל כרחו כו' כמובן ליודעי' בדקדוק לה\"ק וגם הפעולה נמשכת בפועל בעל כרחו כי שכלו ומדותיו שמתפשטי' בשעה שפועל ועובד המה נמשכי' ומתפשטי' בדרך כפייה והכרח כי בע\"כ יתפשט השכל בצמצום הפעולה כו' ולכך נק' העובדא בכלל בשם עושה או מעשה ע\"ש בחי' ההכרח והכפיי' שיש בזה וד\"ל, וגם כאן במעשה המצות אמר ועשיתם אותם פי' להיות כי אור א\"ס שהוא מאיר בבחי' מלכו' בפנימי' עתיק מובדל ומרומם הוא בערך מכל ההשתלשלו' כו' אך ע\"י הכלי של המצוה מתצמצם ושורה בה כמ\"ש כי נר מצוה כו' עד\"מ הנר עם האור והשמן כו' ע\"כ נקרא הארה הזאת שמשתמרת במצות ג\"כ בשם עשי' למעלה כי נמשך האור בה בדרך כפייה והכרח כמשל כל עובדא שנק' בלשון עשי' מזה הטעם כנ\"ל ולכך נא' ועשיתם<sup data-n=\"3068\">83</sup> אותם ואתם כתיב כלומר אתם תוכלו לעשותם פי' להיות אור א\"ס מתלבש בהם והוא המעשה שהוא בחי' המשכה דאור א\"ס במצות בדרך הכרח כו' וזהו ועשיתם אותם וד\"ל וזהו שכפל לומר אחר השימור ועשיתם כי אינו משתמר בלתי בחי' עשי' שהוא בחי' ההכרח עד\"מ בחי' העשי' באדם התחתון למטה כנ\"ל וד\"ל.\n<b>ונתתי</b><sup data-n=\"3069\">84</sup> גשמיכם בעתם ונתנה הארץ יבולה ועץ השדה יתן פריו. הנה שרש ענין המבואר בזה למעלה שהוא קול דתורה כו' יובן בהקדים ענין מה שארז\"ל זוכה<sup data-n=\"3070\">85</sup> לתורה שניתנה בה' קולות למה ה' קולות דוקא. אך הענין הוא דזהו",[["3063","78","<b>כי נר מצוה</b>: משלי ו, כג."],["3064","79","<b>ששת ימים תעבוד</b>: יתרו כ, ט. ואתחנן ה, יג."],["3065","80","<b>גט מעושה</b>: גיטין פח, ב (במשנה)."],["3066","81","<b>גדול המעשה</b>: בבא בתרא ט, א."],["3067","82","<b>עשו דדי בתולייך</b>: יחזקאל כג, ג. ח."],["3068","83","<b>ועשיתם אותם ואתם כתיב</b>: בחוקותי כו, ג. וראה ויק\"ר לה, ו. זהר בחוקותי קיג, סע\"א."],["3069","84","<b>ונתתי גשמיכם בעתם</b>: המשך הכתוב בחוקותי שם."],["3070","85","<b>זוכה לתורה שניתנה בה' קולות</b>: ברכות ו, ב."]]],[2100490528,"בחי' ה'<sup data-n=\"3071\">86</sup> חסדי' המגדילים שהם מבחי' אור אימא וכידוע בענין ה\"ח המגדלים האילן שהוא מן המים שהם מבחי' אימא ואמנם שרשם של ה' חסדים הם מבחי' ה' גבורות דאבא כי בחי' ה\"ג דאבא נעשי' ה\"ח דאימא וזהו &lt;קפז&gt;\nפלג<sup data-n=\"3072\">87</sup> אלקי\"ם מלא מי\"ם שע\"י פלג דשם אלקים שהם ה\"ג דאבא נעשי' מלא מים דהיינו בחי' ה\"ח דאימא כו' וד\"ל.\n<b>וביאור</b> הדברים יובן ממשל מי<sup data-n=\"3073\">88</sup> הגשמים שהמה ג\"כ המגדלים כל צמיחה מצמיחת הארץ כידוע והנה עיקר ההולדה בא מכח הצומח שיש בארץ אלא שהגידול בהתפשטו' בא ע\"י מי הגשמים והדוגמא בזה הוא הולד במעי אמו שמתגדל בט' חדשי' לקומה שלימה ועיקר תולדתו ממ\"ד דטפת האב הי' רק כמו בחי' נקודה א' אלא שנתפשט אח\"כ בשהייתו בט\"ח והוא ע\"י המאכלי' שאמו אוכלת כו' ואמנם מתגדל בכמה מיני איברים שונים בהתחלקות רב וכל זה מסיבת המ\"ד דאב שהוא בבחי' טיפין טיפין וע\"כ מתפלג לחלקי' רבים אח\"כ כשנעשה ונכלל במ\"נ דאימא לגדל הולד בשהייתו בט\"ח לאיברי' חלוקים כו' ויותר מובן זה במי הגשמים המגדלי' התבואה והפירו' שהגשמים באין טיפין טיפין דוקא ואח\"כ מגדלי' המים והוא ע\"י הלחלוחי' שיונק האילן מן הגשמי' לגידול רב ועצום ולחלקים רבים ושונים כמו גוף הפירו' והעלין והעץ וכאו\"א יוצא מופרד בפ\"ע ותחלת התולדה מבחי' כח הצומח שלא הי' רק ע\"י נטיעת גרעין א' וכיוצא הרי לא הי' מתגדל הצמיחה כ\"כ ולא הי' מתחלק לחלקים רבים ושונים כ\"כ כו' וא\"כ מי הגשמים הם עיקר הסיבה לזה והוא להיותם באים מחולקי' טיפי' טיפי' כו' וזהו שנק' גבורו' גשמים שיורדים בגבורה פי' בהתחלקו' שאז דוקא כאשר ירד הגשם בארץ יקבל הארץ אותו ויתמלא מים כמ\"ש והרו\"ה<sup data-n=\"3074\">89</sup> את הארץ והולידה והצמיחה ואם לאו לא ירוה את הארץ ולא תוליד ולא תצמיח כלל כנראה בחוש הטבע בשטף מים כמי המבול שלא יתקבל כלל בארץ ויחרב הארץ וזהו מבחי' עיקר החסד וההשפעה במה שמתחלק לטיפין טיפין ונק' גבורה שבחסד וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> פלג אלקי' הן ה\"ג דאבא פי' אור החכמה הוא מבחי' המשפיע ויורד בגבורה כלומר בהתחלקות כמשל הנ\"ל בטפת האב ובמי גשמים והיינו שם אלקי' המצמצם לבא בהתחלקו' והן ה\"ג בכלל ואח\"כ כשמתקבל במקבל הנק' אימא והוא המוליד המדו' כמ\"ש אם הבנים כו' נתגדל השפע בה ונתחלק לחלקים רבים כנ\"ל והגידול הוא ע\"י בחי' ה\"ח שהן כמו המים המגדלי' כל צמיחה כו' ושרשם להגדיל בהתחלקו' כזאת הוא מפני בחי' ה\"ג של המשפיע כי ה\"ג של המשפיע נמתקו ונעשו בחי' ה\"ח במקבל וזהו פלג אלקים מלא מים וד\"ל וכך יובן למעלה בקול דתורה כו' דהנה אוריי' מחכמ' עילא' נפק' והוא בחי' אור אבא והשפע באה בבחי' ה\"ג והן חמשה קולות כמאמרם ז\"ל זוכה לתורה שניתנה בה' קולות כלומר ה\"ג כדרך מי",[["3071","86","<b>ה' חסדי' המגדילים. . ה' גבורות דאבא</b>: ראה ג\"כ לקו\"ת בחוקותי מח, א."],["3072","87","<b>פלג אלקים מלא מים</b>: תהלים סה, י."],["3073","88","<b>מי הגשמים. . המגדלים כל צמיחה</b>: ראה תענית ב, א."],["3074","89","<b>והרוה את הארץ</b>: ישעי' נה, י."]]],[2100490529,"הגשמי' שיורדי' בגבורה פי' בהתחלקו' כנ\"ל וכמ\"ש והאלקים<sup data-n=\"3075\">90</sup> יעננו בקול כלומר בקול המתחלק לכמה קולות וכמ\"ש וכל<sup data-n=\"3076\">91</sup> העם רואים את הקולות כו' ולכך ניתנה התורה ברעש ורעם גדול דהיינו בקולו' וברקים וקול שופר חזק כו' לפי שניתנה בבחי' הגבורו' דאור אבא כנ\"ל וד\"ל, אך הנה מ\"מ אמרו במשנ' משה<sup data-n=\"3077\">92</sup> קיבל תורה מסיני דהיינו בקול א' בלבד שהרי נא' יעננו בקול משמע בקול א' לפי שהיה משה מבחי' אור אבא עצמו אך אח\"כ נתחלק על ידו אותו הקול לכמה קולות ע\"י בחי' ה\"ג דאבא וכמארז\"ל דיבור<sup data-n=\"3078\">93</sup> א' נתחלק כו' כי לא הי' באפשרי &lt;קפח&gt;\nלהתקבל במקבלים כ\"א ע\"י בחי' התחלקות דוקא כמשל הגשמי' שלא נא' בהן והרוה את הארץ כ\"א כשיורד טיפין טיפין כנ\"ל וכמבואר בגמ' שכל<sup data-n=\"3079\">*93</sup> התורה משה קיבל בב\"א ואח\"כ למדה לבנ\"י פרשיו' פרשיו' כו' וד\"ל.\n<b>וזהו</b> ונתתי גשמיכם בעתם פי' גשמיכם הוא כמ\"ש כאשר<sup data-n=\"3080\">94</sup> ירד הגשם כו' כן יהי' דברי אשר יצא מפי דוקא דהיינו בהתחלקו' ה\"ג כשהקדב\"ה יושב ושונה כנגדו בקול המתחלק דוקא שאז יגדל ויצמיח פלג אלקים זה כי המקבל נעשה מלא מים כנ\"ל ועשה אשר חפצתי והצליח אשר שלחתיו כו' כלומר להגדיל בתוספת מרובה על העיקר כו' וע\"ז הוא אומר ונתת\"י שאני הנותן כי הדבר הזה תלוי דוקא במשפיע כנ\"ל וד\"ל.\n<b>ונתנה</b><sup data-n=\"3081\">95</sup> הארץ יבולה ועץ השדה יתן פריו. הנה כתיב רשע<sup data-n=\"3082\">96</sup> מכתיר את הצדיק שהצדיק בתוך והרשע מקיפו ומכתירו מכל צד כו' ויש להבין מהו ענין זה והאיך יהי' ביכולת הרשע להכתיר את הצדיק כו'. אך הענין הוא דעפ\"י סדר ההשתלשלו' כשירד השפע בעה\"ד טו\"ר נמשך התערובו' טו\"ר בכל העולמו' עד שגם בעולם הבריאה בבחי' כלים החיצונים מיעוטו רע ורובו טוב ובעולם היצי' חציו טוב כו' ובכל מקום הרע הוא סביב לטוב מקיפו מכל צד כדוגמת הקליפה עם הפרי שהקליפה מקפת לפרי שבתוכה מכל צד וכמבואר בזוהר<sup data-n=\"3083\">97</sup> דמוחא וקליפה דא לגו מן דא כו' וכך נרא' בכל הברואי' שהטוב גנוז בתוכו והרע נגלה בו מבחוץ כו' וע\"כ נאמר רשע מכתיר את הצדיק כלומר בחי' הטוב גנוז בתוך הרע והרע מקיף ומכתיר לטוב מכל צד כו' וד\"ל וכן בארץ הגשמי' אמרו בזוהר<sup data-n=\"3084\">98</sup> דטובא גנוז בגווה, פי' כי מרפ\"ח ניצוצי' שנפלו בשבירת הכלים וירד בעה\"ד טו\"ר עד למטה מטה כידוע בחי' הטוב הוא גנוז בכל דבר בתוכו והרע מקיפו כנ\"ל וכן בארץ מבחי' רפ\"ח ניצוצי' דתוהו שהגיע שם המה בהסתר והעלם בה והיינו שאמר דטוב\"ה גנוז בגווה כלומר",[["3075","90","<b>והאלקים יעננו בקול</b>: יתרו יט, יט."],["3076","91","<b>וכל העם רואים את הקולות</b>: יתרו כ, טו."],["3077","92","<b>משה קיבל תורה מסיני</b>: אבות רפ\"א."],["3078","93","<b>דיבור א' נתחלק</b>: ראה ברכות ו, ב."],["3079","*93","<b>שכל התורה משה קיבל בב\"א</b>: וראה ג\"כ תו\"א ע, ד."],["3080","94","<b>כאשר יורד הגשם</b>: ישעי' נה, י."],["3081","95","<b>ונתנה הארץ יבולה</b>: בחוקותי כו, ד."],["3082","96","<b>רשע מכתיר את הצדיק</b>: חבקוק א, ד."],["3083","97","<b>בזוהר דמוחא וקליפה דא לגו מן דא</b>: זוהר בראשית כ, א."],["3084","98","<b>בזוהר דטובא גנוז בגווה</b>: ראה זהר בראשית לז, ב. וראה לקו\"ת בחוקותי (שם) מח, א."]]],[2100490530,"בתוך תוכה גנוז בהעלם גדול מבחי' הטוב דרפ\"ח כו' וצריך מטעם זה להוציא מן ההעלם לגילוי ע\"י גשמים דוקא והוא בחי' שם מ\"ה שמבררן לרפ\"ח ניצוצי' דנפלו בשם ב\"ן כו' כי שרש הגשמי' למעלה הוא בחי' שם מ\"ה כו' וכמ\"ש מעלה<sup data-n=\"3085\">99</sup> נשיאי' מקצה הארץ והוא האידי' שעולי' מן הארץ שהוא בחי' העלא' מ\"ן ואח\"כ ברקים למטר עשה כו' שהוא בחי' מ\"ד כמ\"ש במ\"א וכל זה שהגשמי' מלחלחי' הארץ אינו אלא סיבה בלבד שהארץ תוציא כחה החזק מן ההעלם לגילוי דהיינו טובה דגניז בגווה כו' אבל לאחר שתוציא כחה תצמיח בכחה מצד עצמה מחלק הטוב דגניז בגווה כו' וא\"כ לא הועיל הגשמי' רק להסיר המונע והוא חלק הרע המכתיר וסובב לטובה דגניז בגוו' כמשל שבירת הקליפ' שממילא יגלה מה שבתוכו כו' וזהו ונתנה הארץ יבולה פי' הארץ הוא בחי' שם ב\"ן למעלה שיש בו מהטוב דתוהו בנפילת רפ\"ח כו' בהעלם גדול כנ\"ל והוא הנק' יבולה כלומר כח חזק יותר משל המשפיע מטעם דבחי' התוהו קדם לתיקון דמ\"ה כי שרש ב\"ן בס\"ג כו' וכנ\"ל אלא ע\"י שנתן הגשמי' בארץ היו רק סיבה בלבד להוציא הטוב הגנוז מן ההעלם לגילוי אבל אחר שנתברר &lt;קפט&gt;\nשם ב\"ן ונגלה בחי' הטוב הגנוז אשר בה מבחי' ס\"ג דתוהו הרי הוא למעלה משם מ\"ה כנ\"ל ויהי' עלי' המל' למעלה מבחי' ז\"א וכמ\"ש אשת חיל עטרת בעלה וכנ\"ל בפי' והי' אור הלבנה כו' עד שיהי' שבעתיים כאור ז' הימים כו' וד\"ל.\n<b>וזהו</b> ועץ השדה יתן פריו פי' עץ השדה הוא האור הצומח מן הארץ שם ב\"ן וכמ\"ש תוצא<sup data-n=\"3086\">100</sup> הארץ כו' עד ועץ עושה פרי כו' ונק' עץ השדה שהוא עץ הדעת טו\"ר לאחר שנתברר בשדה שהוא שם ב\"ן וכמ\"ש ואם<sup data-n=\"3087\">101</sup> בשדה מצאה כו' וכשמתבררת נק' חקל<sup data-n=\"3088\">102</sup> תפוחין קדישין כו' וזהו ועץ השדה דוקא יתן פריו כי מצד השלימות שנתברר שם ב\"ן יתן העץ הזה גידול פריו מצד עצמו ולא ע\"י משפיע כלל כי נגלה בארץ טובה דגניז בגווה כו' משא\"כ עכשיו קודם הבירור דכתיב והוא ימשול בך דמ\"ה מברר ב\"ן וכמ\"ש במ\"א וד\"ל ובנפש האלקי' עם נפש הבהמיו' ג\"כ ע\"ד הזה יובן כי נפש הבהמי' מכתיר לנפש האלקי' ובהסיר ממנה המקיף הרע נגלה בה האהבה מסותר' והוא טובה דגניז בה שנתברר מרפ\"ח ניצוצי' שבצלם דנוג' כו' שיגיע בה לבחי' מאד כנ\"ל בפי' טוב מאד זה מלאך המות כו' משא\"כ עכשיו הוא רק ע\"י קול דודי דופק פתחי לי שהוא המעורר שיהא לב דנוק' פתוח אבל לאחר הבירור ונתנה הארץ הוא נפש הבהמיו' יבולה מרפ\"ח כו' ואז ועץ השדה יתן פריו הוא נפש האלקי' שנשרש בנפש הבהמיו' שיתן פריו מעצמו כנ\"ל וד\"ל.",[["3085","99","<b>מעלה נשיאי' מקצה הארץ</b>: תהלים קלה, ז."],["3086","100","<b>תוצא הארץ</b>: בראשית א, כד."],["3087","101","<b>ואם בשדה מצאה</b>: תצא כב, כה."],["3088","102","<b>חקל תפוחין קדישין</b>: ראה זהר ויחי רכד, ב."]]],[2100490531,"<h3>להבין מ\"ש באיוב (מ') ואם זרוע כאל לך</h3>\n<b></b><b>(מפה\"ש<sup data-n=\"3089\">1</sup> )</b>\n<b>להבין</b><sup data-n=\"3090\">2</sup> מ\"ש באיוב (מ') ואם<sup data-n=\"3091\">3</sup> זרוע כאל לך כו' עדה<sup data-n=\"3092\">4</sup> נא גאון וגובה כו' ראה<sup data-n=\"3093\">5</sup> כל גיאה הכניעהו והדוך רשעים תחתם, טמנם<sup data-n=\"3094\">6</sup> בעפר יחד כו' וגם<sup data-n=\"3095\">7</sup> אני אודך כי תושיע לך ימינך כו'. פי' באה המענה מאת ה' לאיוב מן הסערה אם זרוע כאל לך כו' הדוך רשעים תחתם כו' דמשמע דזהו דבר שאי אפשר להיו' בלתי לה' לבדו ואין לאדם כח זה גם לצדיקים<sup data-n=\"3096\">8</sup> מופלגים והלא אנו רואים שצדיקי' יפילו לרשעי' ע\"י תפלתם כמבואר<sup data-n=\"3097\">9</sup> בכמה כתובי'.\n<b>אך</b> הענין הוא משום דשרש הצדיקי' משם מ\"ה דתיקון כידוע, ושרש הנפשו' של הרשעים המה מבחי' התוהו שנפלו בבחי' שבירת הכלים כמ\"ש הנפילים<sup data-n=\"3098\">10</sup> היו בארץ אשר<sup data-n=\"3099\">11</sup> מעולם אנשי השם, פי' מעולם התוהו שלפני בחי' התיקון וכמ\"ש ואלה<sup data-n=\"3100\">12</sup> המלכי' אשר מלכו לפני מלוך כו', והן<sup data-n=\"3101\">13</sup> תתקע\"ד<sup data-n=\"3102\">14</sup> דורו' שקדמו עד שלא הי' בחי' התיקון, והמה העזי פנים ששתלן בכל דור להתברר ע\"י שם מ\"ה דתיקון והוא ע\"י הצדיקים כו', ומאחר שבחי' התוהו גבוה הרבה מבחי' התיקון איך יהי' ביכולת הצדיקי' להשפילם וזהו שאמר לו ה' לאיוב עדה נא גאון וגובה וכל גיאה הכניעהו כו' אחר שהם למעלה ממך ואז גם אני אודך כי תושיע לך ימינך כו'.\n<b>אך</b> הנה לכאורה יש להבין בזה דהרי להצדיקי' הרי &lt;קצ&gt;\nכבר ניתן כח ועוז להפוך רע לטוב בשם מ\"ה המברר ב\"ן, וא\"כ הגם שהרשעי' מבחי' התוהו הרי ניתן בחי' תוהו להתברר ע\"י שם מ\"ה דתיקון כו', ולמה לא יהי' ביכולת הצדיקי' להשפילם והדרא קושיא לדוכתי'.",[["3089","1","<b>מפה\"ש</b>: מפי השמועה."],["3090","2","<b>להבין מ\"ש באיוב</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק (1025 מה, ב). מאמר זה בתוס' הגהות נדפס באוה\"ת וארא ע' רלא. מגילת אסתר (הוצאת תש\"נ) ע' רסד ואילך. וראה ספר המאמרים תרכ\"ז ע' רג. בשולי הגליון בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש: ע' בד\"ה ואם זרוע כאל כו' עדה נא כל גאון וגובה בספר קס\"ו, דמ\"ה ע\"ב. בספר המאמרים תרל\"ב ח\"א ע' מד מעתיק כ\"ק אדמו\"ר מהר\"ש מאמר זה. וראה שם ע' רו (בחלק הנחות)."],["3091","3","<b>ואם זרוע כאל לך</b>: איוב מ, ט."],["3092","4","<b>עדה נא</b>: שם י."],["3093","5","<b>ראה כל גיאה</b>: שם יב."],["3094","6","<b>טמנם בעפר יחד</b>: שם יג."],["3095","7","<b>וגם אני אודך</b>: שם יד."],["3096","8","<b>לצדיקים מופלגי'</b>: בסה\"מ שם נוסף: וכענין שנכנע יעקב לפני עשו."],["3097","9","<b>כמבואר בכמה כתובים</b>: בסה\"מ שם ליתא תיבות אלו."],["3098","10","<b>הנפילים היו בארץ</b>: שלח יג, לג."],["3099","11","<b>אשר מעולם. . פי' מעולם התהו</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' רכח. [ובקונ' הוספות לשם ע' רפ]. אוה\"ת בראשית (כרך ג) תקצה, א. ובכ\"מ."],["3100","12","<b>ואלה המלכים אשר מלכו לפני מלוך</b>: וישלח לו, לא."],["3101","13","<b>והן</b>: בסה\"מ שם: והן והן."],["3102","14","<b>תתקע\"ד דורו' שקדמו</b>: ראה אוה\"ת מטות ע' א'שכב: הפי' שנבראו ברוחניות נשמות ומלאכים ולא נתקיימו לבא להברא בגשמיות."]]],[2100490532,"<b>אך</b> עיקר הענין הוא דיש הפרש בזה, דכאשר הרשעים המה בשלימותם בלתי בירור עדיין לגמרי אז לא יש ביכולת הצדיקי' להשפילם ולהכניעם אבל כשהרשעים מתבררי' ויוצא מהם חלק הטוב אזי יש ביכולת הצדיקי' להכניעם ולהאבידם כו' וטעם הדברים כי כאשר המה בשלימותם הרי המה אנשי השם אשר מעולם התוהו ממש והם גבוהי' מבחי' התיקון ולא יכלו להם אותן אשר למטה מהם במדרג' אך כשמתבררי' ע\"י שם מ\"ה ויוצא מהם חלק הטוב ולא נשאר רק חלק הרע שהוא בא בשבירה הנשאר בהיכלו' החיצוני' שלמטה מטה אזי בנקל מאד שיפלו ויאבדו לגמרי וכמ\"ש כהמס<sup data-n=\"3103\">15</sup> דונג כו' כן יאבדו רשעי' כו', כי רק מצד הטוב שבהם גבוהי' המה מבחי' התיקון אבל לאחר שהוציאו מהם הטוב ונכלל בקדושה ולא נשאר רק חלק הרע אותו יוכלו בקל להאבידו כו', והיינו ענין הבירור שניתן לתוהו ע\"י שם מ\"ה דתיקון דהיינו רק ע\"י בירור דוקא כנ\"ל ולא כמו שהם בשלימותם כו'. ודוגמא לדבר בלעם הרשע שהי' מבחי' התוהו כו' ולא יכלו לו בנ\"י אך כאשר הוציא משה ממנו חלק הטוב והוא במה<sup data-n=\"3104\">16</sup> שהשים ה' דבר בפיו כו' ונעשה בחי' תורה הרבה על ידי שנשא<sup data-n=\"3105\">17</sup> משלו ויאמר כו' שהוא כל פ' בלק שניתנה למשה וישראל והפרשיו' הללו מדברי בלעם הן ונעשי' תורה לישראל ואז לא נשאר רק חלק הרע שבו ולכך אמר אחר שגמר כל דבריו הנני<sup data-n=\"3106\">18</sup> הולך לעמי כו' ויכלו לו אח\"כ והרגוהו כידוע וד\"ל ועד\"ז בכל הרשעי' וע\"ד דוגמא במה שאמרו דלמא יפוק מיני' ברא מעליא וכשהולידו אזי יוכלו להפילו וכיוצא בזה וד\"ל.\n<b>וזהו</b> שאמר ראה כל גיאה הכניעהו והדוך רשעים תחתם כלומר כמו שהם בשלימותם שהם תחתם וכי תוכל להטמינם בעפר כמו שהם כו' וד\"ל. אך הגם שאין זה ביכולת הצדיקי' אבל הוא ית' כל יכול מאחר שממנו הי' ענין השבירה והתיקון ביכולתו לעשו' מתוהו תיקון וכמ\"ש במ\"א ע\"פ מי שם פה לאדם וזהו אם זרוע כאל לך כו' שזהו שרש ענין מענה ה' לאיוב בדרך כללו' וד\"ל.",[["3103","15","<b>כהמס דונג</b>: תהלים סח, ג."],["3104","16","<b>במה שהשם ה' דבר בפיו</b>: ראה בלק כג, יב."],["3105","17","<b>שנשא משלו ויאמר</b>: ראה בלק כג, ז."],["3106","18","<b>הנני הולך לעמי</b>: בלק כד, יד."]]],[2100990049,"<h3>שאו את ראש</h3>\n<b></b><b>מאמרי אדמו\"ר הזקן בעזר\"ה שבת פ' במדבר</b>\nשבת פ' במדבר\n<b>שאו</b><sup data-n=\"3107\">1</sup> את ראש<sup data-n=\"3108\">2</sup> כל עדת בנ\"י כו' מבן עשרים שנה ומעלה כו' במספר שמות כל זכר לגלגלתם. הנה מבואר בזוהר<sup data-n=\"3109\">3</sup> בענין שרש הדגלים שלמעלה שהוא שרש כללות נ\"י המה במספר מכוון ת\"ר אלף כו' ומספר הזה למעלה תמיד הוא בהשוואה אחת לא יתוסף ולא יגרע לעולם כמובן למעיין שם בד' &lt;קצא&gt;\nדגלים העליונים הנק' ד' מחנות שכינה כו' דלסטר דרום מאת אלף ופ' אלף כו' זה המספר מכוון הוא בהשווא' א' לעולם גם הסדר של בחי' דגלים העליונים לא ישתנה אפי' כחוט השערה בתמידו' וא\"כ בהכרח לפ\"ז לומר דשרש כנ\"י למטה ג\"כ במספר ת\"ר<sup data-n=\"3110\">4</sup> אלף דוקא לא פחות ולא יותר וגם סדר השבטים<sup data-n=\"3111\">5</sup> לדגליהם מכוונים הם גם עתה למטה כמו שהם למעלה ממש דהיינו שהן י\"ב גבולי אלכסון כו' ובאים כאו\"א בשער מיוחד ובזמן מיוחד והמה י\"ב חדשים דשנה שבכל חדש מאיר שבט א' כידוע די\"ב<sup data-n=\"3112\">6</sup> חדשי",[["3107","1","<b>שאו את ראש</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (מח, א). נמצא ג\"כ בכת\"י 611 סב, ב.\nנעתק בתוס' הערות בסה\"מ תרל\"ד ע' רח (בד\"ה להבין ענין מה שבמספר שבטי ישראל). וראה ד\"ה זה מש\"פ במדבר תקס\"ד שנדפס באוה\"ת במדבר ס\"ע כט ואילך. ד\"ה זה בסה\"מ תק\"ע ע' צה. מאמרי אדה\"א במדבר ע' כה. אוה\"ת חוקת ע' תתפא."],["3108","2","<b>שאו את ראש</b>: במדבר א, ב."],["3109","3","<b>בזוהר בענין שרש הדגלים</b>: ראה זהר פקודי רנד, א. במדבר קיח, ב. ומבואר ג\"כ בשם הזוהר פקודי: בס' מאמרי אדה\"א ויקרא ח\"א ע' רכג. במדבר ח\"א ע' כה. וע' סו. ח\"ג ע' תתקנו. שער האמונה ספנ\"ד."],["3110","4","<b>ת\"ר אלף דוקא לא פחות ולא יותר</b>: בספר המאמרים תרמ\"ד ע' רסה בגוכתי\"ק: בס' תקס\"ו כי\"ק כ\"ק אדמו\"ר האמצעי זצללה\"ה דמ\"ח ע\"א ד\"ה שאו את ראש כו' מ\"ש שם בתחלתו דמספר ת\"ר אלף נש\"י הם תמיד בהשוואה לא פחות ולא יותר. י\"ל דמספר ת\"ר אלף הם שרשי נשמות ס\"ר, וכמ\"ש בלק\"ת ד\"ה את שבתותי, ומהם לא יפחת ולא יתוסף, י\"ל דהיינו דכל הנשמות דעכשיו שבשית אלפי שנין כו' הם נשמות שהיו כלולי' כבר באדה\"ר כמ\"ש בס' הגלגולים פ\"א, אבל נשמות חדשות לא יש עכשיו כ\"א לע\"ל יתגלו נשמות חדשות וכמארז\"ל צדיקי' יושבין ועטרותיהם בראשיהן, ועמ\"ש בלק\"ת בסוף שה\"ש בד\"ה כי כאשר השמים החדשים, ובפ' צו בד\"ה ואכלתם אכול, ובפ' ראה בד\"ה אחרי, ובע\"ח (ד' קארעץ) שער מ\"ב הוא שער דרושי אבי\"ע יעו\"ש, כנלע\"ד בדרך אפ\"ל."],["3111","5","<b>השבטים. . י\"ב גבולי אלכסון</b>: ראה ספר הבהיר סמ\"ב. זהר במדבר קיח, א. ובביאוה\"ז לשם פה, א ואילך."],["3112","6","<b>די\"ב חדשי השנה המה י\"ב חלקים. . בספרי הקבלה</b>: בסה\"מ תרל\"ד שם: כמבואר בספר יצירה. וראה ס\"י פ\"א מ\"א. פרדס שכ\"א פ\"ו-ח. שי\"ג פ\"ג. וראה גם (בענין י\"ב גבו\"א) ס' יצירה פ\"ה, מ\"א. ס' הבהיר אות צה. לקו\"ת מסעי צד, א. פ' ראה כג, ג. ביאוה\"ז לאדה\"א פה, א ואילך. מאמרי אדה\"א ויקרא ח\"א ע' רכה. במדבר ח\"א ע' קכד. תו\"ח שמות צו, א."]]],[2100990050,"השנה המה י\"ב חלקים שנתחלקו בחי' מוחי' שבמל' דאצי' שהיא שרש כנ\"י למעלה וכמבואר פרטי ענין זה בספרי הקבלה.\n<b>ולכאורה</b> כל זה אינו מובן שהרי אנו רואים שכללו' נ\"י היו יותר מזה המספר הרבה בכפלי כפלים גם בדורות הראשונים כמו בזמן בית ראשון וגם בימי יהושע והזקנים הרי ניתוסף ע\"ז המספר הרבה ומכ\"ש בדורות הבאים אחריהם עד לאחר חורבן בית שני שניתוסף עליהם מאה פעמים ממספר הראשון ובפרט מן הנולדי' בכל דור ודור עד זמן הזה ואיך יתכן לומר שמספר דכללות נ\"י למעלה אינו אלא מספר מכוון ת\"ר אלף כו' וגם הלא משה רבינו ע\"ה בירכם יוסף<sup data-n=\"3113\">7</sup> ה' ככם אלף פעמים<sup data-n=\"3114\">8</sup> ואיך בירכם בדבר שאין לזה שרש למעלה כו', וקושיא זו עצמה היא אשר יש להקשות על מה שנכתב בפ' זו מנין מספר שמות כל זכר ת\"ר אלף כו' דהרי התורה<sup data-n=\"3115\">9</sup> נצחית היא כידוע ובודאי נכתב מנין זה לקרותו גם<sup data-n=\"3116\">10</sup> בזמן הבא אח\"כ בכל דור שאינו אלא במספר זה דוקא ולזה אומר נשא<sup data-n=\"3117\">11</sup> את ראש דר\"ל גם עכשיו בקריאתו בתורה שאו את ראש בנ\"י שהם עכשיו במספר הזה דוקא וזה פלאי לכאורה דהלא אינם נמצאים בשום זמן כמספר הזה דוקא אלא יותר הרבה ולא לפי סדר הזה שבד' דגלים כו'.\n<b>אך</b> כל זה יובן בהקדים תחלה ענין הפסוק מה שאמר במספ\"ר שמו\"ת כו' ומהו לגלגלת\"ם כו' דהנה מה שאמר במספר שמות הוא כמו נתינת טעם למספר הזה ת\"ר אלף דוקא לפי שאין בחי' השמות עליונים באים למעלה רק במספר הזה דוקא ולא יש מספר בשמות זולת זה המספר וע\"כ לפי מספר השמות כך ימנה מספר בנ\"י למטה וזהו פי' במספר שמות כלומר לפי מספר השמות למעלה כך יהי' למטה מספר בנ\"י כו' וביאור טעם הדברים הוא לפי ששרש נשמות ישראל נולדו מבחי' יחוד זו\"נ וכידוע שי\"ב השבטים שרשם המה בז\"א וגם בבחי' נוק' דז\"א וכמ\"ש<sup data-n=\"3118\">12</sup> במ\"א ע\"פ כי שם עלו שבטים כו' וכמ\"ש<sup data-n=\"3119\">13</sup> בזוהר בכמה דוכתי וששה הקצוות דז\"א",[["3113","7","<b>יוסף ה' ככם אלף פעמים</b>: ע\"פ דברים א, יא."],["3114","8","<b>פעמים</b>: במאמרי אדה\"א במדבר שם נוסף: (ובימי דוד הי' מספרם יותר מאלף אלפים אנ\"ח)."],["3115","9","<b>התורה נצחית היא</b>: ראה גם תניא רפי\"ז. ובקו\"א שם ד\"ה ולהבין פרטי ההלכות (קס, א). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' פ (ובמ\"מ שם)."],["3116","10","<b>גם בזמן הבא</b>: ראה מאמרי אדה\"א במדבר שם: ומשמע שמספר הזה חק הקבוע גם לדורות הבאי' וכמ\"ש בזו' ע\"פ איש על דגלו באותות (בפ' פקודי). [ראה מאמרי אדה\"א ויקרא ח\"א ע' רכג. שער האמונה ס\"פ נד. אוה\"ת במדבר ע' ל]."],["3117","11","<b>נשא את ראש</b>: במדבר ד, ב."],["3118","12","<b>וכמ\"ש במ\"א ע\"פ כי שם עלו שבטים</b>: תהלים קכב, ד. וראה תו\"א ויצא כד, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיז (ובמ\"מ שם)."],["3119","13","<b>וכמ\"ש בזוהר בכמה דוכתי וששה הקצוות דז\"א. . ת\"ר אלף</b>: ראה מאמרי אדה\"א קונטרסים ע' שנג — שא' באד\"ר דו\"ק שבמל' היינו ו' אלפי' רבבו' ספיראן (כי כל ספי' דז\"א נחלקת לי' וי' לי' עד ה' פעמי' הרי עולה ת\"ר אלף שהן ס\"ר.\nוראה סה\"מ עזר\"ת ע' נו. מובא גם בשם הת\"ז [במאמרי אדה\"ז נביאים ע' ס]. ובשם ס\"י [מאמרי אדה\"א במדבר ח\"א ע' מב וע' רסג].\nראה ע\"ח שער (מב) דרושי אבי\"ע ספ\"ה. תקו\"ז (ת\"ע קלה, סע\"א)."]]],[2100990051,"הרי ידוע דכל<sup data-n=\"3120\">14</sup> מדה כלולה מי' וי' הללו מתחלקי' למאה בכלל כשמתחלקת כאו\"א לי' הרי ת\"ר בכלל וכשכאו\"א מן המאה מתחלק לי' הרי נעשה אלף ובכללם ו' אלפי' וכשכאו\"א מן האלף מתחלק לי' נעשה י' אלפי' בכל מדה ובכללם ס' אלף וכשכאו\"א מן הי' אלפי' מתחלק לי' הרי ק' אלף בכל מדה ובכללם ת\"ר אלף ובמספר הזה הרי כבר באה כל מדה ה' פעמי' בהתכללו' פ\"א מא' לי' ופ\"ב מי' לק' ופ\"ג מק' לאלף ופ\"ד מאלף לרבוא ופ\"ה מרבוא לק' אלף מפני ה' החסדי' שמגדלי' ובהכרח שיבא כל אחד במדות דבר מחודש כו' והן פרטי מספר שמות שיש במדות דז\"א בפרט דהיינו כשמתחלקי' בפרטי פרטיהם להיות בבחי' פרצוף שלם כו' והן &lt;קצב&gt;\nכולם שמו' דהוי' שכל שם דהוי' הוא בז\"א לפי שכולו בחי' חסדי' וכמ\"ש כי<sup data-n=\"3121\">15</sup> זכר חסדו ועד\"ז ממש יש מספר שמות בנוק' דז\"א בשמו' דאלקי'<sup data-n=\"3122\">16</sup> דהיינו בבחי' הדין והצמצום כו' ובכלל<sup data-n=\"3123\">17</sup> זה נק' עלמא דדכורא וזה עלמא<sup data-n=\"3124\">18</sup> דנוק' וזה נק' אדם עילא' וזה נק' אדם תתאה כמ\"ש כמים<sup data-n=\"3125\">19</sup> הפנים לפנים כן לב האדם לאדם כו' ולפי ששרש הנשמו' נולדו מיחוד דזו\"נ כמ\"ש נעשה<sup data-n=\"3126\">20</sup> אדם בצלמינו וארז\"ל<sup data-n=\"3127\">21</sup> אתם קרויים אדם כו' ע\"כ אמר במספר שמות כל זכר לגלגלתם פי' שיהי' מספר בנ\"י למטה כמו שהמה נטועים בשרש שרשם למעלה בזו\"נ ולפי ששם הוא מספר השמות מכוון במספר זה דוקא כנ\"ל לכך אמר במספ\"ר שמו\"ת כלומר לפי מספר השמו\"ת כנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין יש להבין הטעם להיא גופה למה לא יש מספר שמות למעלה בזו\"נ רק כפי מספר המכוון הזה דלמה לא היו מתכללים המדו' בהתכללות עוד הרבה פעמי' והי' המספר בכפלי כפליים כו' אך הענין הוא משום דיש בחי' ק\"ו המד\"ה למעלה מן האצי' והוא הנק' בזוהר<sup data-n=\"3128\">22</sup> משחתא כו' והוא ג\"כ בחי' בוצינא<sup data-n=\"3129\">23</sup> דקרדניתא כו' כידוע וענינו הוא מה שכך עלה ברצון המאציל להיות אורו' הנאצלים באופן זה ולא באופן זולת זה כמו שיאצל אורו' כך וכך וכלים כך וכך וכיוצא וא\"כ בהכרח שגם בחי' המספר עליהם ג\"כ כך עלה ברצון המאציל דוקא שיהיו במספר כזה דוקא לא פחות ולא יותר כו' ולכך נק' בשם קו<sup data-n=\"3130\">24</sup> המד\"ה עד\"מ אמת הבנין שבו",[["3120","14","<b>דכל מדה כלולה מי'</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"א."],["3121","15","<b>כי זכר חסדו</b>: תהלים צח, ג."],["3122","16","<b>דאלקי'. . הדין והצמצום</b>: ראה ב\"ר פל\"ג, ו. ירושלמי ברכות פ\"ט, ה\"ה. זח\"ג לט, ב. סה, א. ובכ\"מ. תניא שער היחוד והאמונה פ\"ו."],["3123","17","<b>ובכלל זה נק' עלמא דדכורא</b>: ראה ג\"כ תו\"ח ויצא קפ, א."],["3124","18","<b>עלמא דנוק'</b>: ראה לקו\"ת להאריז\"ל פ' ויצא ד\"ה סוד יעקב (ואם תדקדק)."],["3125","19","<b>כמים הפנים לפנים</b>: משלי כז, יט."],["3126","20","<b>נעשה אדם בצלמנו</b>: בראשית א, כו."],["3127","21","<b>וארז\"ל אתם קרויים אדם</b>: יחזקאל לד, לא. יבמות סא, א."],["3128","22","<b>בזוהר משחתא</b>: ראה זהר בראשית טו, א. יח, ב. תקו\"ז ת\"ה בתחלתו. זהר פקודי רלג, א. ביאוה\"ז שם נז, ד."],["3129","23","<b>בוצינא דקרדניתא</b>: ראה זח\"א טו, א. יח, ב."],["3130","24","<b>קו המד\"ה</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תקנ. וש\"נ."]]],[2100990052,"מודדין כל דבר ארכו ורחבו וכך יש בחי' קו המדה בבחי' מספר ונק' מספר כמ\"ש מונה<sup data-n=\"3131\">25</sup> מספר שהמספר הוא המונה כו' כמ\"ש בזוהר ומספר הזה הוא אשר מנה להיות מציאו' שמות דז\"א כך וכך דוקא דהיינו ת\"ר אלף בפרט ולא יותר כי כך עלה ברצון המאציל כו' וכמ\"ש במ\"א ובסמוך יתבאר הטעם למה שעלה ברצונו להיות יותר ממספר זה כו' וד\"ל.\n<b>והנה</b> ידוע מאמר רז\"ל ע\"פ<sup data-n=\"3132\">26</sup> והיה מספר בנ\"י כחול הים אשר לא ימד ולא יספר כו' ל\"ק כאן כשישראל עושין רצונו של מקום כו' וכענין שבירכם יוסף ה' ככם אלף פעמים כו', והנה מאמר זה לא בא ליישב אלא מה שקשה מרישא לסיפא בפסוק זה והוא ממ\"ש והיה מספר כחול הים ואח\"כ אשר לא ימד כו' אבל לא מיירי כלל ממספר הנ\"ל הקצוב ת\"ר אלף דלא הזכירו בפסוק זה כלל משום דזה המספר מכוון הוא תמיד למעלה בהשווא' א' ולא יתוסף ולא יגרע לעולם וגם אם יתברכו יותר מזה כו' כי הרי מספר הזה הוא מכוון מצד שכך עלה ברצון המאציל א\"כ אין להוסיף ולגרוע אפי' כחוט השערה אך מה שמתברכין בכפלי כפליים הוא רק בחי' ענפים ולא בחי' שרשים כי בחי' השרשים<sup data-n=\"3133\">27</sup> תמיד למעלה במספר מכוון ת\"ר אלף ולא פחות ולא יותר אך בחי' הענפים שמתפשטי' מן בחי' השרשים הללו יוכלו להתפשט הרבה עד אין שיעור כענין הזורע<sup data-n=\"3134\">28</sup> קב ומוציא כמה כורים או כמו ענפים ממש שמתפשטי' מן שרש האילן שיוכל להיו' מאה פעמי' מספר הענפים על השרש כו' אך השרשים אין בהם לא תוספת ולא גרעון מטעם &lt;קצג&gt;\nהנ\"ל לפי שכך עלה ברצונו והוא ע\"י בחי' הקו המודד והמונה הנק' משחתא כו' וד\"ל וזהו הטעם דלא מיירי מאמר זה מענין מספר השרשים אחר שלעולם אין בהם שינוי אלא מיירי רק בענין הברכה שהוא בחי' הענפים וע\"ז תירץ מה שקשה מרישא לסיפא דכאן כשישראל עושי' רצונו כו' דיוכל להתברך אלף פעמי' ת\"ר אלף כו'.\n<b>ועתה</b> יש להבין מהיכן יבא תוספת ברכה שהיא מרובה על העיקר בכפלי כפליים לאין שיעור כו' אך הנה לזה הוא שאמר כאן לגלגלתם כו'. דהנה ידוע דגלגלתא<sup data-n=\"3135\">29</sup> הוא בחי' כתר ובבחי' ז\"א נק' כתר דז\"א גלגלתא ובנוק' נק' כתר דנוק' בשם גלגלתא כידוע וא\"כ כשאמר לגלגלת\"ם לשון שנים רצונו בזה לשרש שרשם בבחי' זו\"נ ומפני שיש כתר א' לשניהם ואח\"כ מתחלק לשנים כו' ולכך אמר לגלגלתם כו'. וענין זה שאמר לגלגלתם היינו שיעלה ויגביה שרש נשמו' דישראל למעלה מבחי' המספר שבשמו\"ת הנ\"ל והוא בבחי' הכתר שהוא למעלה מבחי' המספר כו' וזהו שאמר שאו לשון הגבהה והתנשאות ואת ראש בנ\"י דוקא ינשא",[["3131","25","<b>מונה מספר</b>: תהלים קמז, ד."],["3132","26","<b>ע\"פ והיה מספר בנ\"י. . ל\"ק כאן כשישראל עושין רצונו של מקום</b>: הושע ב, א. יומא כב, ב."],["3133","27","<b>השרשים. . ת\"ר אלף</b>: ראה תניא פל\"ז ובהנסמן במראי מקומות לשם."],["3134","28","<b>הזורע קב ומוציא כמה כורים</b>: ראה פסחים פז, ב. (ושם: סאה)."],["3135","29","<b>דגלגלתא הוא בחי' כתר</b>: ראה לקו\"ת שלח מח, ב. דרושים לראש השנה נד, ב."]]],[2100990053,"וירומם שהוא בחי' המוחי' שלהם דוקא ולהיכן ינשאם לבחי' גלגלתם ששם המה למעלה מן המספר כו'.\n<b>וביאור</b> הדברים הנה נודע היות בחי' הכתר עצמו מובדל בערך מבחי' השתלשלו' מעילה לעילה כי מן הכתר מפני שמתפשט בג' קוין אז מתחיל בחי' המספר למנות אופן ההתכללות כך וכך כנ\"ל אבל קודם שאור הכת\"ר מתחלק לקוין עדיין אינו בבחי' מספר כלל וכמ\"ש לתבונתו<sup data-n=\"3136\">30</sup> אין מספר ולכך הכתר<sup data-n=\"3137\">31</sup> עצמו אינו נמנה בכלל י\"ס לפעמי' כו' כמ\"ש בפרדס וע\"ח וזהו שאמר שאו את ראש בנ\"י לגלגלתם דוקא לבחי' הכתר שם המה למעלה מבחי' המספר כנ\"ל ומשם יצו ה' את הברכה דוקא להיות מתברכי' בריבוי המשכות הענפים מבחי' השרשי' כהנה וכהנה כענין יוסף<sup data-n=\"3138\">32</sup> ה' ככם אלף פעמי' וכיוצא כי עיקר הברכה תלוי' בבחי' הכתר דוקא להיותו למעלה מבחי' המספר ע\"כ יבא ממנו אור השפע ג\"כ בבלתי הגבלה במספר כו' וכמ\"ש במ\"א בענין ברוך אתה הוי' כו' וד\"ל והיינו שאמרו ז\"ל דכשישראל עושין רצונו של מקום שהוא בחי' אור הכתר שבמעשה המצות כידוע אזי נא' בהן אשר לא יספר כו' וכמ\"ש במ\"א וגם כאן רצונו במ\"ש לגלגלתם שיגביהם וינשאם לבחי' הכתר כדי שמשם יברכם ה' בתוספת מרובה על העיקר מטעם הנ\"ל וד\"ל.\n<b>ומה</b> שאמר מבן עשרים שנה ומעלה דוקא ישאו את ראשו לגלגלתם כנ\"ל ולא קודם לכן כו'. הענין הוא משום דידוע בכתבי<sup data-n=\"3139\">33</sup> האריז\"ל דעד כ' שנה עדיין אין באדם מבחי' גדלו' דמוחי' דאבא אלא רק מבחי' מוחי' דאימא כו' וע\"כ אמרו ז\"ל במשנה דלמכור<sup data-n=\"3140\">34</sup> בקרקעות בנכסי אביו עד שיהא בן עשרים דוקא, ודקדק לומר בקרקעות ובנכסי אביו דוקא כי הגם שמקחו מקח וממכרו מכר בשלו מזמן קודם כמו דגם הפעוטו' מקחו מקח כו' אבל בנכסי אביו ובקרקעו' אין יכולי' למכור עד שיהא בן עשרים כו' ובטעם הזה מובן הנ\"ל משום דמוחי' דאבא הוא שעולי' ונכללי' בכתר ג\"כ ואדרבה בחי' אור אבא על היותו שרש כל ההשתלשלו' הוא העיקר בהעלאה זו ובלעדו לא &lt;קצד&gt;\nיעלה גם שום פרט מפרטי ההשתלשלו' אשר בא במספר שמות כו' אחר שהוא הכולל כולם וע\"כ<sup data-n=\"3141\">*34</sup> מבן עשרים שנה ומעלה דוקא יכולי' לישא בחי' מוחי' שלו לבחי' הכתר כי אור חכמה קרוב יותר לכתר ועולה ראשונה וגם עמו עולה כל המסתעפים ממנו כו' וכמ\"ש והחכמה<sup data-n=\"3142\">35</sup> מאין תמצא כו' משא\"כ פחות מבן כ' שאין לו מבחי' מוחי' דאבא עדיין רק מבחי' מוחי' דאימא עדיין רחוק הוא מבחי' אור הכתר ולא יוכלו להעלותו לגלגלתם כו' והיינו הטעם שאינו יוכל למכור בנכסי אביו בקרקעו' עד שיהא בן כ' כי בהיותו פחו' מבן כ' עדיין אין לו",[["3136","30","<b>לתבונתו אין מספר</b>: תהלים קמז, ה."],["3137","31","<b>הכתר עצמו אינו נמנה. . כמ\"ש בפרדס וע\"ח</b>: ע\"ח שער מוחין דצלם פ\"ה. וראה לקו\"ת שלח מט, ג."],["3138","32","<b>יוסף ה' ככם אלף פעמי'</b>: נסמן לעיל הע' 7."],["3139","33","<b>בכתבי האריז\"ל דעד כ' שנה</b>: ראה ע\"ח (שער דרושי הצלם) שכ\"ה דרוש ח. לקו\"ת במדבר ב, א. שע\"ת ז, א. שעה\"י קלג, ב."],["3140","34","<b>דלמכור. . בנכסי אביו</b>: ב\"ב קנו, א."],["3141","*34","<b>וע\"כ מבן עשרים. . לגלגלתם</b>: קטע זה נעתק בלקו\"ת במדבר ב, א — שו\"ה כו'."],["3142","35","<b>והחכמה מאין תמצא</b>: איוב כח, יב."]]],[2100990054,"מוחי' דאבא ואיך יוכל לשנות נכסי אביו שבקרקעו' שנק' נחלת אבותיו דהיינו מבחי' מוחי' דאבא שלו כי האב ממשיך מוחי' דאבא כו' כידוע דבן<sup data-n=\"3143\">36</sup> מסטרא דאבא קאתי כו' מרשות אביו לרשות אחר אם אין לו שרש אחיזה בהם עדיין אלא כשיש לו מוחי' דאבא וירית אחסתנא דאבוה כו' אזי ביכולתו לשנות ולמכור בנכסי אביו בקרקעו' כו' וד\"ל.\n<b>ואחר</b> כל זה יתורצו כל הקושיות הנ\"ל בענין הדגלים העליונים למה המה תמיד במספר א' והלא בירכם יוסף ה' כו' דהרי מבואר למעלה דהברכה היא בבחי' הענפים אבל בבחי' השרשים אין שום תוספת ולא גרעון מטעם ענין ובחי' קו המדה שכך עלה ברצון המאציל כו' וכנ\"ל. אך עדיין יש להבין למה היתה רצון המאציל באופן מדה ומספר כזה דוקא ולא יותר כו'.\n<b>אך</b> הענין יובן בהקדים ענין א' המוזכר בע\"ח<sup data-n=\"3144\">*36</sup> תמיד שהכלל בכל מקום שיורד השפע יש ב' בחי' הא' הבא בבחי' שרש והוא בא תמיד בהשווא' א' לא יפחת ולא יגרע כו' והב' הבא בבחי' תוספת ולא בבחי' שרש והוא אינו בא בהשווא' א' אלא לפעמי' יהי' בא בריבוי ולפעמי' במיעוט ותמיד יבא בשינויים כמו שאם יגרום החטא ולא יוכשר מעשה התחתונים גם אם כבר בא יסתלק אותו התוספת ומכ\"ש שמתחלה לא יאיר כו' ואין הארת בחי' התוספת כ\"א לפרקים ועתים מיוחדים כשבת ויו\"ט ור\"ח וכה\"ג כמו בחי' מלכות דאצי' שכלולה מי\"ס יש בה ב' בחי' הללו הא' הבא בבחי' שרש לצורך קיום העולמות והוא בחי' כתר שבמל' דהיינו עצם מדת מלכותו ית' אשר בהכרח שתמיד יאיר אורו וכמ\"ש לעולם<sup data-n=\"3145\">37</sup> דברך נצב בשמים שהוא בחי' כתר שדבוק באחורי ז\"א שנק' שמים כמ\"ש בע\"ח ואמנם שאר הט' ספי' שלה באים למטה בבי\"ע בבחי' תוספת והוא אשר ישתנה לפעמי' יאיר במיעוט ולפעמי' בהתרחבות ונק' ארץ טובה ורחבה כו' ויש עתים מיוחדים לזה כמו בשבת ויו\"ט ור\"ח ולא בימות החול וגם אם כבר באו למטה בבחי' תוספת אם יגרום חטא העולם יסתלק וכמ\"ש<sup data-n=\"3146\">38</sup> בזוהר ע\"פ עת לעשות לה' כו' האי עת או סלקא או נחתא כו' וכיוצא בזה בכל מקום באבי\"ע זה הכלל נוהג דמה שבא בבחי' שרש הרי הוא תמידי בהשווא' א' ואשר בא בבחי' תוספ' לפעמי' יאיר במיעוט ולפעמי' בריבוי לפי העת והזמן כו', ועפ\"י הקדמה זאת יובן גם בענין הנ\"ל במספר ת\"ר אלף שרשים בכללו' נ\"י למעלה בזו\"נ הענין הוא דכך עלה ברצון המאציל שיהא זה המספר בחי' שרש דהיינו בתמידו' בהשווא' א' לא יפחת ולא יגרע כנ\"ל ואשר יבא בבחי' תוספת הוא ענין &lt;קצה&gt;\nהברכה מה שיתברכו באלף פעמי' כמספר הזה וזה תלוי לפי העת והזמן כנ\"ל בענין בחי' התוספת אבל להיות בכנ\"י בבחי' שרש לא הי' רצון המאציל אלא דוקא במספר מכוון כזה כו' וד\"ל.",[["3143","36","<b>דבן מסטרא דאבא קאתי</b>: ראה זהר בראשית כב, ב."],["3144","*36","<b>בע\"ח</b>: ראה שער מיעוט הירח פ\"ב. לקו\"ת צו, יא, ב."],["3145","37","<b>לעולם דברך נצב בשמים</b>: תהלים קיט, פט — לעולם ה' דברך נצב בשמים."],["3146","38","<b>וכמ\"ש בזוהר ע\"פ עת לעשות לה'</b>: ראה זוהר תרומה קנה, סע\"ב — ע\"פ ואל יבא בכל עת."]]],[2100990055,"<b>אך</b> הנה עדיין יש להבין על עיקר הדבר למה היה הרצון להיו' בבחי' שרש רק כפי מספר הזה דוקא כו', התשובה בזה יובן למשכיל מטעם הכמוס לי\"ח שלטובה וחסד בשביל העולמו' דאבי\"ע הי' רצון זה להמאציל ולזאת הי' כונתו במספר מועט כזה שאם הי' בא בבחי' שרש מספר מרובה מזה היה תוספת יניקה לחיצונים הרבה והיו מחריבים כל העולמות כמ\"ש בזוהר<sup data-n=\"3147\">39</sup> דהוו מטשטשי עלמא כו'.\n<b>וביאור</b> הדברים הללו יובן בהקדים תחלה תוספת ביאור בענין בחי' שרש ובחי' תוספת הנ\"ל, דהנה להבין היטב ענין ההפרש בין בחי' שרש לבחי' תוספת הוא מובן עפ\"י ב' משלים הא' מאשר אנו רואים באדם התחתון שמעמד ומצב גופו ונפשו אשר מלובש בתוכו עם כל פרטי כוחותיה המלובשים באיברי הגוף פנימיי' וחיצוניים אין בו שינויים כלל בין זמן לזמן כמו כח הרגל להילוך וכח הראי' בעין וכיוצא בהם בכחו' הפנימי' כח השכל להשכיל והמדו' בלב כו' והאצטומכא לברר המאכל וכיוצא כולם בתמידו' כמעט בהשווא' א' לשמש בהם כל צרכי גופו הנהוגי' לו תמיד כו' אך לפעמי' אנו רואים שימצא שינויים בכחו' הפנימיי' כמו השכל והמדות מה שיתוסף בהם אור הרבה יותר מכפי השיעור והמדה הראשונה כו' כמו בעת שיעשה האדם משתה ושמחה שישמח ויגיל בלבו ויאיר אור הרבה בלבו והוא ע\"י החדוה וכן יאיר לפעמים תוספת אור הרבה בשכלו ומוחו והוא כאשר ימצא שכל וסברא חדשה כידוע עד שיאירו פניו וכמ\"ש חכמת<sup data-n=\"3148\">40</sup> אדם תאיר פניו וכענין צהבו<sup data-n=\"3149\">41</sup> פניו של רבי וכמ\"ש במ\"א אך הנה בחי' גילוי אורו' הללו בשכל ומדו' וכה\"ג אינו אלא לפרקים וגם יש בהם שינויי' לפעמי' מעט ולפעמים הרבה כפי השעה והזמן כו' והוא הנק' בחי' תוספת משא\"כ בחי' שרש הוא אשר יש מהארת הנפש בגופו בתמידו' בהשווא' לצורך הנהגות גופו תמיד כנ\"ל ואין בו שינוי כלל כו' ונמצא מובן עיקר ענין ההפרש ביניהם שבחי' אותו התוספת באור השכל והמדו' בא בבחי' פנימי' יותר והוא נק' בחי' הרוחניו' לגבי הארה הראשונה דמאחר שהיא רק בחי' חיצוניו' נק' בחי' גשמיו' לגבי פנימי' הניתוסף והוא כערך הגשמיו' לגבי הרוחניו' ממש והוא כערך החומר לגבי הצורה כידוע וע\"כ בא סיבת ההפרש הזה הנ\"ל שהתוספ' הזה מפני שהוא בחי' הרוחניו' והפנימי' לא יבא רק לפרקים לפי העת והזמן אבל בחי' החיצוניו' שהיא לצורך הנהגו' הגוף בהכרח שיהי' בא בבחי' שרש דהיינו בתמידו' בלתי שינוי וד\"ל.\n<b>והנמשל</b> ממשל זה יובן למשכיל למעלה בבחי' שרש ובחי' תוספ' שבשבת ויו\"ט וכיוצא אזי יאיר בחי' תוספ' והוא בחי' פנימי' המוחי' בזו\"נ ופנימי' האור במדו' וכה\"ג וזהו ענין השמחה ביו\"ט שנא' ושמחתם<sup data-n=\"3150\">42</sup> לפני ה' דוקא כו' כידוע שהשמחה למעלה היא בבחי' תוספת גילוי אורו' ומוחי' חדשי' מאו\"א ועד\"ז גם",[["3147","39","<b>כמ\"ש בזוהר דהוו מטשטשי עלמא</b>: ראה זהר בראשית רמג, ב."],["3148","40","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["3149","41","<b>צהבו פניו של רבי וכמ\"ש במ\"א</b>: חולין ז, א. וראה לקו\"ת צו ט, א. מסעי צג, א. ובכ\"מ."],["3150","42","<b>ושמחתם לפני ה'</b>: אמור כג, מ."]]],[2100990056,"באו\"א כו' עד שנק' בחי' הארת פנים למעלה בכלל שנא' ג'<sup data-n=\"3151\">43</sup> פעמי' בשנה יראה כל זכורך את פני ה' כו' וכידוע ולפי ערך יובן שיש קצת מהארת בחי' תוס' זה גם בכל יום &lt;קצו&gt;\nכמו בעמידה<sup data-n=\"3152\">44</sup> דש\"ע בשחר וכמ\"ש בפרע\"ח והוא נקרא דרך כלל בחי' הרוחניו' אך מה שמאיר לצורך קיום העולמו' והנהגותיו מזו\"נ בתמידו' הוא אשר נק' בחי' חיצוניו' והוא בא בבחי' שרש דהיינו בהשווא' א' בלתי שינוי וכנראה לעין שבכל יום מחדש הבריא' והכל במנהג א' כו' וגם בשבת ויו\"ט אין שינוי בזה כי בחי' התוס' אשר מאיר למעלה בשבת ויו\"ט אינו נגלה למטה בעולמו' כו' וכמ\"ש במ\"א וד\"ל.\n<b>והמשל</b> השני בזה הוא ג\"כ עולה כמשל הנ\"ל אלא שהוא בענין אחר והוא ממה שאנו רואי' במלכותא דארעא שהנהגות המלך על מדינתו אינו אלא בשילוח מכתביו שנחתמו בחותם המלך כידוע והנה ידוע אשר נחתם<sup data-n=\"3153\">45</sup> בחותם המלך אין להשיב אפי' לשנות כמלא נימא ואמנם קודם שיחתום המלך על הכתב שמתבונן הוא בחכמתו איך ומה יכתוב אזי יכול להיות שיאמר המלך טעמים וסברות הרבה למה שנכתב שא\"א שיבאו בכתב כלל כי בעצת שכלו וחכמתו יכול להשתנות בשינויים הרבה וכמעט לשנות מהיפך להיפך אבל בבא הסופר לכתוב א\"א לכתוב כ\"א מה שצריך להנהגת המדינה בהכרח וע\"ז יחתום המלך ואז אין להשיב כלל כו' ונמצא משל הזה עולה ג\"כ ע\"ד משל הנ\"ל שבחי' החותם הוא בחי' חיצוניות ובחי' ההתבוננו' בטעמי' של המכתב והחותם הוא בחי' הפנימי' והוא כחומר עם הצורה כנ\"ל והרי אנו רואים לעין שלצורך הנהגת המדינה לא יוכל לבא בגילוי כ\"א בחי' החיצוניו' אבל בחי' הפנימי' נסתר ונעלם בלתי המלך לבדו יודע אותם כו' והוא ג\"כ ביאור ענין בחי' שרש ובחי' תוספ' למעלה דמה שבא מן המאציל לאבי\"ע בבחי' שרש הוא בחי' החיצוניו' שהוא ההכרחית להיות מלובש עד למטה מטה כמו להיות נברא יש גמור כמו בריאת אש ומים גשמיים למטה והנהגו' קיץ וחורף וצמיחת תבוא' כו' ועד\"ז גם גבוה<sup data-n=\"3154\">46</sup> מעל גבוה כו' עד גם הנשמו' שנהנין מזיו השכינה שיעור קצוב להם כל ימו' החול אך בשבת ויו\"ט מקבלי' בחי' התוס' בחי' הארת פנים הנ\"ל כמ\"ש והי'<sup data-n=\"3155\">47</sup> מדי חדש כו' וה\"ז בחי' כמשל החותם הוא ביומין דחול לפי שמקבלי' מו\"ק דזו\"נ וכנמשל ההתבוננו' לפני המכתב הוא בחי' התוס' שמאיר בשבת שממנו בא בחי' שרש בו' יומין הבאי' אח\"כ כו' וכמ\"ש במ\"א באריכו' וד\"ל.\n<b>ובכל</b> המשלים האלה שבחי' השרש בא בבחי' החיצוניו' כדי הצורך להנהגה בלבד כו' וע\"כ יובן הטעם למה שעלה ברצון המאציל במספר מכוון ת\"ר אלף שרשים בזו\"נ בלבד כי זה המספר בא בבחי' שרש לצורך ההנהגה דבי\"ע בלבד כנ\"ל וידוע דאשר בא בבחי' שרש הוא בא ונמשך ומתלבש עד למטה מטה עד רגלי העשי' כמובן מתוך הנ\"ל וא\"כ אם הי' בא בבחי' שרש בריבוי יותר ממספר ת\"ר כו' היו גם",[["3151","43","<b>ג' פעמי' בשנה יראה כל זכורך</b>: פ' ראה טז, טז."],["3152","44","<b>בעמידה דש\"ע. . וכמ\"ש בפרע\"ח</b>: ראה סידור שחרית לד, רע\"א. לז, סע\"א ואילך. לקו\"ת פינחס עו, ב. עז סע\"א ואילך."],["3153","45","<b>נחתם בחותם המלך אין להשיב</b>: לשון הכתוב אסתר ח, ח — ונחתום בטבעת המלך."],["3154","46","<b>גבוה מעל גבוה</b>: לשון הפסוק קהלת ה, ז."],["3155","47","<b>והי' מדי חדש</b>: ישעי' סו, כג."]]],[2100990057,"החיצונים יכולי' לקבל מהם כי הי' בא בהתלבשות עד שגם הם יקבלו כמו שמקבלים גם עכשיו מבחי' השרש הבא בהנהגה דבי\"ע כו' ואמנם עתה בהיות שלא בא האור במספר זה רק בבחי' שרש ותוספת הברכה בכפלי כפלי' כנ\"ל הוא בא רק בבחי' תוספת שהוא בבחי' רוחניו' כמו בשבת ויו\"ט כנ\"ל הרי יש ברירה שיסתלק התוספ' כשמתגברי' החיצונים וכנ\"ל שבחי' התוס' יכול להסתלק כשגורם החטא כו' כי בחי' הרוחניו' לפעמי' יאיר ולפעמי' יתעלה כו' משא\"כ &lt;קצז&gt;\nאם הי' הכל בא בבחי' שרש הרי זה כמו הנחתם בבחי' חותם שנא' אשר נחתם בטבעת המלך אין להשיב ויכולים הכל לקבל כמבואר מתוך משלים הנ\"ל וא\"כ הרי מובן מכל זה דמה שנעשה בחי' קו המדה במספר השרשי' הי' רק בשביל טובה וחסד לאורו' עליונים שלא יחריבו אותם תוספ' יניקו' החיצונים וכמ\"ש בזוהר דהוו מטשטשי עלמא משא\"כ עכשיו כשאינם מקבלי' רק במדה ובחי' התוס' מסתלק מהם כו' וד\"ל.\n<b>ובכל</b> הנ\"ל מובן מ\"ש בפ'<sup data-n=\"3156\">48</sup> פקודי ויהי מאת ככר הכסף לצקת את אדני הקדש ואת אדני הפרכת כו'. כי הנה משכן דמשה נא' בו אשר<sup data-n=\"3157\">49</sup> הראי\"ת בה\"ר והוא בחי' משכן<sup data-n=\"3158\">50</sup> העליון דאצי' שנעשה ע\"י בחי' קו המדה הנ\"ל בכל פרטי מעשיו ביריעו' שהן א\"מ והקרשים המה א\"פ דז\"א והאדנים המה בבחי' מל' שהמה בחי' כלים לאורות כי האדן היה בו חלל בית קיבול לקבל בתוכו בליטת הקרש כנוק' שמקבלת הזכר כו' והוא שם א\"ד כו' וב' אדנים לקרש א' שעלו מספר מאה אדני' המה ת\"ר אלף שרשים הנ\"ל שמת\"ר אלף שרשים שנתנו כאו\"א כופר<sup data-n=\"3159\">51</sup> נפשו מחצית השקל נעשה מאה ככר כסף ככר לו' אלפי' כו' וענין מחצית<sup data-n=\"3160\">52</sup> השקל ידוע בלק\"ת שהוא עשרים גרה י' מבחי' א\"ח וי' מבחי' א\"י וכופר הנפש הזה נעשה למעלה בחי' אדן לקרש והוא הנק'<sup data-n=\"3161\">53</sup> סמכין בזוהר כמו שהרגל יעמיד הראש וא\"ל הי' נופל כך האדנים החזיקו הקרשים ונא' בקרשים עצי<sup data-n=\"3162\">54</sup> שטים עומדי' כמ\"ש כי<sup data-n=\"3163\">55</sup> האדם עץ השדה כו' וכמבואר בזוהר כך כנ\"י נק' בחי' כלי להחזיק כל האורו' העליונים כו' וכך עלה ברצון המאציל במשכן העליון הנ\"ל שיהי' בחי' הכלים שלו שהן האדני' רק במספר מאה בלבד מטעם הנ\"ל כי זה צריך לבא בבחי' שרש למטה להנהגו' עולמו' התחתוני' שמתנהגי' עפ\"י משכן העליון כמובן בהיכלו' דפ' פקודי וד\"ל והתורה נצחית היא וגם בכל דור ודור אין במשכן העליון רק כמספר הזה וע\"כ משכן דמשה לא נתבטל גם בימי דוד ושלמה שהרי גנזוהו לפי שהוא בבחי' משכן העליון שהוא נצחי בלתי שינוי מטעם הנ\"ל אך מה שבא בו בבחי' תוספת בזה יש שינויי' כפי העת והזמן כנ\"ל וד\"ל.",[["3156","48","<b>בפ' פקודי ויהי מאת ככר הכסף</b>: לח, כז."],["3157","49","<b>אשר הראי\"ת בה\"ר</b>: תרומה כו, ל."],["3158","50","<b>משכן העליון</b>: ראה זהר (רע\"מ) בשלח נט, ב. תרומה קמ, ב. קנט, א. קסב, ב."],["3159","51","<b>כופר נפשו</b>: תשא ל, יב."],["3160","52","<b>מחצית השקל ידוע בלק\"ת שהוא עשרים גרה</b>: ראה תו\"ח שמות תקעג, א. ובהמ\"מ לשם. וראה ביאוה\"ז תשא נג, א ואילך."],["3161","53","<b>הנק' סמכין בזוהר</b>: ראה זהר שמות רמ, א."],["3162","54","<b>עצי שטים עומדי'</b>: תרומה כו, טו."],["3163","55","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."]]],[2100990058,"<h3>ענין החושן ואפוד</h3>\n<b>ענין</b><sup data-n=\"3164\">1</sup> החושן והאפוד. הנה ענין החושן שהי' על הלב דאהרן כו' הוא הי' בחי' לבוש לז\"א שהוא אהרן למעלה ובלבושי' שורה א\"מ לכך היו חקוקי' בהאבנים שבו שמות כל השבטים כו' ומאחורי ז\"א מתחיל בנין הנוק' כידוע והוא בחי' לבוש האפוד בגי' פ\"ה והוא לבוש דנוק' דז\"א וכתיב וירכסו<sup data-n=\"3165\">2</sup> את החשן מטבעותיו אל טבעו' האפוד בפתיל תכלת ולא יזח החשן מעל האפוד הענין הוא כמ\"ש<sup data-n=\"3166\">3</sup> בזוהר דהאי תכלת תכלא דאתקשר בכלא כו' &lt;קצח&gt;\nפי' מבחי' הגבורו' שמקשר ומדבק להיו' זו\"נ מחוברי' תמיד ולא יזח החשן כו' כי התשוקה שבין זכר לנקבה מחברם תמיד והוא מבחי' הגבורו' כו' והחשן<sup data-n=\"3167\">4</sup> הוא בחי' קטנו' שהוא אותיו' נחש כמ\"ש בלק\"ת וע\"כ צריך שלא יזח מעל האפוד כי המל'<sup data-n=\"3168\">5</sup> נק' דינא רפיא כו' וד\"ל. וביאור פרטי הדברים מובן לי\"ח וד\"ל.",[["3164","1","<b>ענין החושן והאפוד</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (מט, א). נמצא ג\"כ בכת\"י 611 סד, א."],["3165","2","<b>וירכסו את החשן</b>: תצוה כח, כח. פקודי לט, כא."],["3166","3","<b>כמ\"ש בזוהר דהאי תכלת תכלא דאתקשר בכלא</b>: ראה זוהר פקודי רלא, א."],["3167","4","<b>והחושן. . בחי' קטנו'. . אותיות נחש</b>: ראה לקו\"ת חוקת סא, ד ואילך. אמרי בינה שער הציצית פד, ד."],["3168","5","<b>המל' נק' דינא רפיא</b>: פע\"ח שער ר\"ה פ\"א. ועוד. תו\"א וירא יד, ד. דרך מצותיך קט, ב."]]],[2100990059,"<h3>ביאור לדרוש דאם בחוקותי תלכו</h3>\n<b></b><b>(ביאור<sup data-n=\"3169\">1</sup> שני לדרוש דאם בחוקותי תלכו הנ\"ל)</b>\n<b>להבין</b> שרש ענין החקיקות הנ\"ל ע\"פ אם<sup data-n=\"3170\">2</sup> בחוקותי תלכו כו'. הנה ענין החקיקה מבפנים הנ\"ל הוא ענין בחי' התרחבות הכלים שנעשה ע\"י הכאות האורות דוקא וביאור הדבר הוא עד\"מ המכה בפטיש בעץ גולמי וע\"י ההכאה שהוא מכה בפטיש בכח ממילא מתחקק בגולם הכלי חקיקה עמוקה ורחבה כפי ערך ההכאה של הפטיש ואחר שע\"י ההכאה נעשה בגולמי בית קיבול מצחצחו לבית קיבול מתוכו מבפנים ואח\"כ מחליקו ומצחצחו לגולם הכלי מבחוץ בכדי שיהא נאה גם מבחוץ כו'.\n<b>והנמשל</b> מזה יובן למעלה בבחי' כלים לאורו' העליונים הנק' בחי' התיקון שהוא ענין התרחבו' הכלים כידוע אין התרחבות הכלים בא אלא ע\"י הכאת האור בלבד עד\"מ המכה בפטיש כנ\"ל, כי הנה ידוע בענין התיקון<sup data-n=\"3171\">3</sup> שהוא ריבוי אורו' וריבוי כלים ע\"י שם מ\"ה כו' כי בשם ב\"ן שבו הי' השבירה הי' בחי' נקודו' בלבד ונק' ז' נקודות דתוהו והוא ענין מיעוט הכלים כמו הנקודה שהיא כמו גולמיית בלתי",[["3169","1","<b>ביאור שני לדרוש דאם בחוקותי</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (מט, ב).\nהמאמר נדפס לעיל ח\"א ע' תד. והביאור (הא') נדפס שם ע' תיז."],["3170","2","<b>אם בחוקותי תלכו</b>: בחוקותי כו, ג."],["3171","3","<b>התיקון שהוא ריבוי אורו' וריבוי כלים</b>: ראה ע\"ח שער (י) התיקון פ\"ה. שער (יא) המלכים פ\"א-ב. תו\"א ט, ג. תו\"ח בראשית ט, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקעז."]]],[2100990060,"תוך ובית קיבול ואמנם ע\"י הכאת האור בנקודו' הללו משם מ\"ה דתיקון נעשה בהם בחי' בית קיבול וכניסת האור עם עשיי' בית קיבול באי' כא' עד\"מ המכה בפטיש הנ\"ל וזהו ענין ריבוי הכלים שהוא לפי ערך ריבוי כניסת האורו' דוקא מטעם שנעשה הבית קיבול רק ע\"י בחי' הכאה של האור בלבד כנ\"ל וד\"ל. והענין של ריבוי הכלים ידוע שהוא בא ע\"י ענין ההתכללות של האורו' זה בזה בכמה אופנים שונים עי\"ז ממילא נעשה ריבוי הכלים כמו חסד שבחסד מתכלל עם גבורה שבחסד וכן חסד שבגבורה עם גבורה שבחסד כו' עד שנמתקו הגבורו' בחסדי' ונתכללו החסדי' בגבורו' באופנים רבים מאד ע\"כ ממילא בכל התכללו' פרטי יש מציא' אופן פרטי להשראת אור בכלי ואחר שיש ריבוי אופני' בהתכללו' ממילא יש ריבוי הכלים וכידוע זה עד\"מ מזיגת דבר בדבר שיש בו כמה מיני אופני' כו' וכמ\"ש במ\"א וד\"ל ובחי' ריבוי הכלים הללו שהוא ע\"י בחי' ההתכללו' הוא הנק' פרצוף אדם עד\"מ פרצוף אדם התחתון שאנו רואים שמתכללים בו כל האיברי' בתכלית ההתכללו' עד שכאו\"א מקבל מחבירו כו' כי ירפאו לכאב הראש בהקזת גיד שברגל כו' וכידוע וכל ניתוח האיברי' פנימי' וחיצוניי' כולם קשורי' ואחוזים &lt;קצט&gt;\nיחד זה בזה עד מבלי ימצא ראש וסוף כי הראש מקבל חיותו מן הרגל כו' וכמ\"ש במ\"א משא\"כ קודם בחי' התיקון הי' בחי' הנקודו' זה תחת זה מובדלי' ומופרדי' ואין להם שייכו' וקשר זע\"ז כלל כו' וע\"כ נק בחי' התיקון הזה שע\"י ההתכללו' בשם אדם והוא שם<sup data-n=\"3172\">4</sup> מ\"ה בגי' אד\"ם והטעם הוא כי ע\"י הכאו' האורו' דוקא בא סיבת התרחבו' הכלים שהוא בחי' ההתכללו' כנ\"ל והכאת האור הוא אור דשם מ\"ה כמאמר שם<sup data-n=\"3173\">5</sup> מ\"ה במילוי אלפין מלגיו דמקשר לון כו' ואיהו ארח כל האצי' כו' וכמ\"ש ביאורו במ\"א וד\"ל.\n<b>ולהבין</b> ביאור הדברי' איך בא בחי' הכאת האור דשם מ\"ה לעשו' ההתכללו' הנ\"ל יובן עפ\"י המבואר במ\"א בענין והנורא שהוא מדת ת\"ת שבו דוקא שם הוי' על היותו כלול מחו\"ג כו' כי בשם אל הוא רק בחי' חסד ובשם אלקי' אין שם אלא בחי' גבור' כו' וכמו שמים ואש א\"א שיתחברו כך אינם מתחברי' אך בבוא עליהם מאור א\"ס הארה גבוה משניהם יחד אזי מתבטלים ממציאותם ויכולי' אז למצוא בחי' התכללו' מזה בזה וישכנו יחד כאיש א' וכנראה בחוש במלכותא דארעא שהשר הגדול והעבד הנבזה יעמדו שניהם יחד לפני המלך בהשווא' א' ממש וכשילך המלך אז השר מובדל ומרומם בפ\"ע והעבד עומד לפניו מרחוק כו' א\"כ מי עשה בשר ועבד חיבור וקישור בתחלה בעמדם יחד לפני המלך הרי אין זה אלא בחי' ביטול שהי' בהם מאימת המלך להיותו מרומם הרבה משניהם כו' והנמשל מובן בספי' ת\"ת אחר היותו כלול מחו\"ג ב' הפכי' בהכרח הוא מפני שאור המאציל עצמו שגבוה מכולם בא ומאיר שם ע\"כ נתבטלו ויוכלו להתחבר ולהתקשר וזהו הנק' נור\"א כו' וכמ\"ש במ\"א וגם כאן בענין סיבת ההתכללו' באה ג\"כ רק מפני המשכת אור גבוה מעצמו' המאציל וכשהוא בא מתבטלי' וזוהי עד\"מ הכאת הפטיש שממילא",[["3172","4","<b>שם מ\"ה בגי' אדם</b>: ראה פרדס שעה\"כ בערכו. ע\"ח (שער התיקון) ש\"י, פ\"ג. שער (לח) לאה ורחל פ\"ב. שער (לט) מ\"ן ומ\"ד דרוש ה'. מאו\"א מערכת אדם סקס\"ו."],["3173","5","<b>שם מ\"ה במילוי אלפין מלגיו דמקשר לון</b>: ראה ת\"ז בהקדמה (יז, א)."]]],[2100990061,"נעשה בית קיבול כו' כך הוא ענין המשכת הביטול בנקודו' הנ\"ל שהוא עד\"מ כמו בית קיבול ותוך ונעשה ממילא ע\"י כניס' האור הגבוה והוא שם מ\"ה כו' ונמצא המשכת שם מ\"ה עם עשי' הכלים בריבוי באי' כא' עד\"מ הנ\"ל מהכאת הפטיש כו' ולפי ערך כניסת האור דשם מ\"ה כך נעשה ערך ריבוי הכלים להיותו עושה בהם בחי' בית קיבול ותוך ע\"י המשכת הביטול משם זה ולכך נק' שם מ\"ה כי בחי' מ\"ה זה הוא בחי' המשכת ביטול כלומר מה פשפשת כו' עד שכאו\"א מתבטל כו' וד\"ל.\n<b>והנה</b> מבואר למעלה דריבוי הכלים וריבוי האורו' א' הוא דודאי ריבוי הכלים מחזיק ריבוי האורו' וכמו בית קיבול כשהוא עמוק ורחב הרבה יכנס בו יותר וסיבת התרחבו' הכלי מריבוי האור בא כו' וע\"כ מובן שכניסת והמשכת האור עם עשיי' התרחבו' הכלי א' הוא ובהיפוך בהסתלקו' האור הי' הכלי גולמי בלתי תוך כלל וכמו בחי' הנקודו' דב\"ן בבחי' התוהו שנסתלקו האורו' מפני מיעוט הכלים כו' ובזה יובן מארז\"ל לא<sup data-n=\"3174\">6</sup> מצא הקדב\"ה כלי מחזיק ברכה אלא השלום פי' כלי מחזיק ברכה הוא ענין ריבוי הרחבת הכלים שמחזיק ריבוי האורו' שנק' ברכ\"ה כידוע ואין זה אלא ע\"י השלו\"ם וכמ\"ש עושה<sup data-n=\"3175\">7</sup> השלו\"ם כו' כמו במיכאל<sup data-n=\"3176\">8</sup> וגבריאל מים ואש ואין מכבין זא\"ז כו' לפי שהוא בחי' המשכת הביטול משם מ\"ה וכנ\"ל בענין והנור\"א כו' וזהו הנק' שלו\"ם שהוא בחי' יסוד שמאיר משם מ\"ה והוא אור &lt;ר&gt;\nהנכנס בכלי כמשל הכא' הפטיש וע\"כ השלו\"ם הוא דוקא העושה את הכלי להיו' מחזיק ברכה כו' וד\"ל.\n<b>ואחר</b> כל זה יובן ענין החקיקה מבפנים הנ\"ל דהיינו ע\"י משה<sup data-n=\"3177\">9</sup> שנק' מחוקק וכמ\"ש כי<sup data-n=\"3178\">10</sup> שם חלקת מחוקק ספון ופי' מחוקק הוא דבר שבו עושין החוקה והוא הבית קיבול והוא בחי' אור החוקק בכלי כמשל הכא' הפטיש הנ\"ל וזהו דוקא בחי' שם מ\"ה דמשה וכמ\"ש משה ונחנו<sup data-n=\"3179\">11</sup> מה כו' כי שרשו<sup data-n=\"3180\">12</sup> מבחי' יסוד אבא כידוע ובחי' יסוד אבא נק' מחוקק וכמ\"ש באר<sup data-n=\"3181\">13</sup> חפרוה שרים כו' במחוקק במשענותם (ואהרן<sup data-n=\"3182\">14</sup> לא נק' מחוקק אע\"פ שהי' מבחי' נצח דאבא כי לא נק' מחוקק אלא בחי' יסוד מטעם כניסתו במקבל וכענין אין<sup data-n=\"3183\">15</sup> אשה כורתת ברית אלא למי שעשאה כלי וכמ\"ש כי<sup data-n=\"3184\">16</sup> בועלייך עושייך כו' וכמ\"ש במ\"א) וד\"ל.",[["3174","6","<b>לא מצא הקדב\"ה כלי מחזיק ברכה אלא השלום</b>: משנה סוף עוקצין."],["3175","7","<b>עושה השלום</b>: ראה ישעי' מה, ז — עושה שלום."],["3176","8","<b>במיכאל וגבריאל מים ואש</b>: ראה ספר המאמרים תרל\"ה ח\"א ע' קפח: ”ברע\"מ פ' פינחס דף רך\"ה ע\"א. . וע\"פ פי' זה דרע\"מ נא' בכל הדרושים מיכאל. . מים וגבריאל. . אש\". וראה גם בהערות המו\"ל שם. ספר הבהיר (ס\"ט) סי\"א הובא בהשמטות לזהר בראשית (סכ\"ט) רסג, א. במדב\"ר פי\"ב, ח. וש\"נ. מגלה עמוקות אופן קעז."],["3177","9","<b>משה שנק' מחוקק</b>: ראה ברכה לג, כא. וראה לקו\"ת מטות פח, א."],["3178","10","<b>כי שם חלקת מחוקק ספון</b>: ברכה שם."],["3179","11","<b>ונחנו מה</b>: בשלח ט, ז. ח."],["3180","12","<b>שרשו מבחי' יסוד אבא</b>: ראה שער האמונה פ\"ו. תו\"ח בשלח ריט, א. וראה לקו\"ש ח\"ו ע' 244. וש\"נ."],["3181","13","<b>באר חפרוה שרים</b>: חקת כא יח."],["3182","14","<b>ואהרן. . נצח דאבא</b>: ראה סה\"מ תרכ\"ז ע' רחצ ביאור ע\"ז."],["3183","15","<b>אין אשה כורתת ברית</b>: ראה סנהדרין כב, ב."],["3184","16","<b>כי בועלייך עושייך</b>: ישעי' נד, ה."]]],[2100990062,"<b>ועתה</b> יש להבין שרש ענין החקיקה מבחוץ הנ\"ל. דהנה עד\"מ הצורף שנוטל גולם מתכת או עץ ועושה בו בית קיבול ותוך ואח\"כ מחליקו וגם מצחצחו מבחוץ כנ\"ל הנה זה הצחצוח מבחוץ הוא שלא יתלכלך מבחוץ בדבר המטנף מפני שמבחוץ נדבק כל פסולת ביותר מבפנים על היות יד הכל ממשמשי' שם ועוד מפני שעיקר העכרורית מבחוץ לכלי הוא כו' והנמשל בזה יובן למשכיל למעלה להיות כי תחלה היו זו\"נ בבחי' אב\"א כמארז\"ל ד\"ו<sup data-n=\"3185\">17</sup> פרצופי' כו' ואח\"כ נעשה בחי' הנסירה להיו' פב\"פ כו' כידוע והטעם שהיו בבחי' אב\"א בתחלה ידוע שהוא מפני יראת החיצונים שלא יקבלו יניקה מבחי' אחוריי' כי פי' בחי' אחור למעלה הוא בחי' חיצוניו' ההשפעה שניתנה כמאן<sup data-n=\"3186\">18</sup> דשדי בתר כתפוהי וכיוצא ומזה גם החיצונים יכולי' לקבל ולפי שהוא בחי' חיצוניו' של הכלים עליונים נדבק שם העכרורית והפסולת ביותר וכמשל לכלוך הכלי מבחוץ כנ\"ל ע\"כ היו דבוקי' אב\"א והיו בחי' האחוריי' נעלמי' מן החיצונים ומן בחי' הפנים לא יוכלו לקבל על היותו רם ומובדל מהם בערך ולא יוכלו לגשת אליו מקרוב כלל כו' אך הנה רצה המאציל שיהי' תיקון לבחי' האחוריי' ג\"כ ואע\"פ שיבא בגילוי ולא יוכלו החיצונים לקבל כו' אשר לזאת היה ענין הנסירה וענין התחלקו' דו פרצופי' הנ\"ל כי פי' נסירה הוא ענין צחצוח ותיקון וכמ\"ש ויבן<sup data-n=\"3187\">19</sup> ה' אלקי' את הצלע וא' בזוהר<sup data-n=\"3188\">20</sup> דאו\"א תקינו לה כו' ופי' וענין התיקון הזה הוא לצחצח למרק בחי' העכרורית הנדבק באחוריי' ולהבהיק אותו בצחצוח גדול עד שיאיר אור בחי' האחוריי' כמו בחי' אור הפנימי' כו' וכמו משל שע\"י מירוק וצחצוח באחוריי' של הכלי יבהיק יפיו מבחוץ כמו בערך היופי אשר מבפנים כו' וענין זה המירוק והצחצוח למעלה הוא ענין הברורי' דרפ\"ח כו' שנפלו בשם ב\"ן והוא ענין מה שאמרו ז\"ל בא<sup data-n=\"3189\">21</sup> נחש על חוה והטיל בה זוהמא וידוע פי' מאמר זה בספרי הקבלה שהוא יניקו' החיצוני' מאחוריי' דשם ב\"ן שנק' חוה כו' וכאשר מתהפך הרע לטוב ע\"י הבירור כמ\"ש בזוהר לאהפכא<sup data-n=\"3190\">22</sup> חשוכא לנהורא ומרירו למיתקא כו' הוא ענין המירוק והצחצוח באחוריי' דשם ב\"ן מזוהמת הנחש הקדמוני ולהסיר ממנה כל טינוף ופסולת ועכרורית עד שיהי' אור בחי' האחוריי' מאיר במדרג' בחי' אור הפנים כו' ולא יוכלו החיצוני' &lt;רא&gt;\nלקבל מן האחוריי' כמו שלא יוכלו לקבל מבחי' פנים וכמ\"ש במ\"א שזהו כל עיקר ענין הד'<sup data-n=\"3191\">23</sup> גליו' לברר בחי' אחוריי' דב\"ן ולעשותו בבחי' הפנים וכמ\"ש אנכי<sup data-n=\"3192\">24</sup> הסתר אסתיר פני כו' וכל שאינו בהסתר פנים אינו מהם כו' וז\"ש לכתך<sup data-n=\"3193\">25</sup> אחרי במדבר כו' ובכלב נא' יען<sup data-n=\"3194\">26</sup> כי מלא אחרי כו' וכמ\"ש אחרי<sup data-n=\"3195\">27</sup> ה' תלכו ומבואר ענינו במ\"א באריכו' וד\"ל.",[["3185","17","<b>דו פרצופי'</b>: ברכות סא, א. וע\"ש בפרש\"י."],["3186","18","<b>כמאן דשדי בתר כתפוהי</b>: ראה תניא פכ\"ב (כז, ב)."],["3187","19","<b>ויבן ה' אלקי' את הצלע</b>: בראשית ב, כב."],["3188","20","<b>בזוהר דאו\"א תקינו לה</b>: ראה זהר בראשית מח, ב. מט, א."],["3189","21","<b>בא נחש על חוה והטיל בה זוהמא</b>: שבת קמו, א."],["3190","22","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["3191","23","<b>הד' גליו' לברר בחי' אחוריי' דב\"ן</b>: תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] תח, א."],["3192","24","<b>אנכי הסתר אסתיר פני</b>: וילך לא, יח."],["3193","25","<b>לכתך אחרי במדבר</b>: ירמי' ב, ב."],["3194","26","<b>יען כי מלא אחרי</b>: דברים א, לו — יען אשר מלא אחרי."],["3195","27","<b>אחרי ה' תלכו</b>: פ' ראה יג, ה."]]],[2100990063,"<b>ובעבודת</b> ה' ג\"כ מובן ענין הבירור הזה למטה לאהפכא חשוכא לנהורא כו' מנפש הבהמיו' דנוגה וכמ\"ש ימי<sup data-n=\"3196\">28</sup> שנותינו בהם ע' שנה כו' וכמ\"ש למעלה שהוא ענין התלבשו' הנפש האלקי' בנפש הבהמיו' הנק' צלם דנוגה להיות תחת הזמן במספר ע' שנה שהוא כפי הצורך להיו' בצלם זה הניתן לו למרק ולצחצח בחי' אחוריי' דשם ב\"ן מבחי' אלקי' אחרי' שנדבקי' שם כו' וד\"ל ובאתעדל\"ת בבירור ומירוק אחוריי' דכנ\"י בצלם דנוג' כמ\"כ יתברר למעלה בחי' אחוריי' דשם ב\"ן למעלה מכל סיג ופסולת דאלקי' אחרי' כו' ויאיר אור בהיר כמו אור הפנים וכמ\"ש ולילה<sup data-n=\"3197\">29</sup> כיום יאיר כו' וכל זה הוא ענין העיכוב של הגאולה כידוע ואפי' בנשמו' הגבוהו' כנשמו' התנאי' והאבות וגם כמו נשמת משה כולם צריכים לבא למטה בגוף כדי לברר וללבן בחי' האחוריי' מטעם ענין הנסירה למעלה כנ\"ל וע\"כ נא' גם למשה כי<sup data-n=\"3198\">30</sup> לא יראני האדם וחי בחייהם<sup data-n=\"3199\">31</sup> אינן רואי' מצד שלא נתברר עדיין כל בחי' האחוריי' אבל במיתתן רואי' לפי שנתברר בע' שנה בחי' האחוריי' להיו' כמו בחי' פנים כו' וד\"ל וזהו ענין בע\"ת<sup data-n=\"3200\">32</sup> שגדולי' גם מצדיקים גמורי' כידוע וגם ידוע מארז\"ל טוב<sup data-n=\"3201\">33</sup> זה מלאך חיים מאד זה מלאך המות כו' והכל מטעם א' לפי שהתשובה הוא להשיב הנדח כמ\"ש לבלתי<sup data-n=\"3202\">34</sup> ידח ממנו נדח והיינו תשוב<sup data-n=\"3203\">35</sup> ה\"א תתא' למקורה להבדל מיניקו' החיצוני' ע\"י בירור וצחצוח כנ\"ל ולכך בע\"ת גדולי' מצדיקי' כי מבררים כל בחי' האחוריי' מהרע הנדבק שם ועושי' מבחי' אחוריי' בחי' פנים כו' וזהו יותר מעלה גם מבחי' הצחצוח שמבפנים כי יכול להיו' יופי הכלי מבחוץ יותר מבפנים כו' והיינו ג\"כ שאמרו טוב מאד זה מלאך המות כי לאחר שיבורר המות וכמ\"ש בלע<sup data-n=\"3204\">36</sup> המו\"ת לנצח כו' הרי נברר בחי' הרע הנדבק באחוריי' כמ\"ש רגלי'<sup data-n=\"3205\">37</sup> יורדות מות ואז האור גדול מאור הפנים ולכך נק' מאד כו' וזהו שאמרו ז\"ל דיפה<sup data-n=\"3206\">38</sup> שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב לשון יפה הוא ענין יפוי בחי' האחוריי' שהוא טוב מאד יותר מכל חיי העוה\"ב כו' וד\"ל.\n<b>והנה</b> כל הנ\"ל בענין ב' החקיקות מבפנים ומבחוץ הכל הוא מבחי' אור אבא שנק' מחוקק והוא משה שנק' מחוקק להיותו מבחי' יסוד אבא כנ\"ל אך הנה בהכרח לומר שיש בחי' מקור ושרש גם לאותו המחוקק העושה החקיקו' הנ\"ל שמשם מקבל כח ועוז להיות עושה חקיקו' הללו ועד\"מ האדם שחוקק באבן הרי יש בידו אבן שחוקק בו והאדם הוא הנק' מחוקק לפי שחוקק באבן וא\"כ יש כח ושרש",[["3196","28","<b>ימי שנותינו בהם ע' שנה</b>: תהלים צ, י."],["3197","29","<b>ולילה כיום יאיר</b>: תהלים קלט, יב."],["3198","30","<b>כי לא יראני האדם</b>: תשא לג, כ."],["3199","31","<b>בחייהם אינן רואי'</b>: ראה תורת כהנים ויקרא א, א. ילקו\"ש ויקרא ריש רמז תלא. במדבר רבא ספי\"ד. כלה רבתי פ\"ג."],["3200","32","<b>בע\"ת שגדולי' גם מצדיקים גמורי'</b>: דעת ר' אבהו בברכות לד, ב. והביאו הרמב\"ם בהל' תשובה פ\"ז ה\"ד. וראה סה\"מ תש\"ט ע' 183 בהערה."],["3201","33","<b>טוב זה מלאך חיים</b>: בראשית א, לא. ראה ילקוט שמעוני שם רמז טז. וש\"נ. ב\"ר פ\"ט, י. זהר בהקדמה יד, א. וראה תו\"א תשא פו, ב."],["3202","34","<b>לבלתי ידח ממנו נדח</b>: שמואל-ב יד, יד."],["3203","35","<b>תשוב ה\"א תתא'</b>: ראה אגה\"ת פ\"ד."],["3204","36","<b>בלע המו\"ת לנצח</b>: ישעי' כה, ח."],["3205","37","<b>רגלי' יורדות מות</b>: משלי ה, ה."],["3206","38","<b>דיפה שעה אחת בתשובה ומע\"ט בעוה\"ז</b>: אבות פ\"ד, מי\"ז."]]],[2100990064,"למחוקק זה שיוכל לחקוק באבן שנק' מחוקק וכמ\"ש בענין שנא' במחוקק<sup data-n=\"3207\">39</sup> במשענותם כו' הרי מחוקק זה מבואר למעלה שהוא בחי' יסוד אבא ובאר שחפורה שרים כו' וכרוה במחוקק זה בהכרח &lt;רב&gt;\nשבא להם כח שרשי ממקור ושרש כל הנאצלים והוא בחי' כתר דא\"א ונק' גלגלתא ושם תרי\"ג<sup data-n=\"3208\">40</sup> מצו' חקוקי' בתרי\"ג ארחי' כו' והן המצות שנק' חוקים כמאמר חוקה<sup data-n=\"3209\">41</sup> שחקקתי לך כו' כמו לבישת שעטנז ומצו' פרה אדומה<sup data-n=\"3210\">*41</sup> וכמו ציצית ותפילין לפני התפלה כולם המה בחי' שרש ומקור עליון למחוקק זה שעושה החקיקו' הנ\"ל והיינו שאמרו בחוקה שחקקתי לך בשרש כל הנאצלי' והוא בבחי' כתר דא\"א כו' עפי\"ז יחקוק המחוקק זה משה כמ\"ש בו כי שם חלקת מחוקק ספון כו' וד\"ל.\n<b>וביאור</b> הדברים הנה שם מ\"ה דאור אבא הנק' מחוקק הוא מקור החסדי' וכמבואר למעלה על היותו יורד מגבוה לנמוך לעשות הרחבת הכלים והכלים עצמן הם מבחי' צרופי אותיו' שהוא בחי' שם ב\"ן בכלל והוא מבחי' הגבורו' והצמצומי' כנודע והנה כח המחבר אותו אור דשם מ\"ה מקור החסדי' בכלים שהם משם ב\"ן הרי הוא מחבר ב' הפכי' כמו אש ומים אחר שהמה שני הפכי' זה מחסדי' וזה מגבורו' א\"כ בהכרח לומר שהוא גבוה משניהם יחד וכפי הכלל הנ\"ל בענין והנורא כו' והיינו להיו' כי אותו הכח המחבר שם מ\"ה וב\"ן להיו' נק' מחוקק ריבוי האורו' ליכנס בריבוי הכלים הוא בא ממקום גבוה מכולם והוא מבחי' כתר דא\"א שהוא בחי' ממוצע בין עצמו' אור א\"ס הפשוט ובין בחי' מאורו' דאצי' שגנוזי' בא\"א כו' וע\"כ הוא מקור למחוקק הנ\"ל עד שעל ידו נעשה יחוד מ\"ה בב\"ן כו' וזהו אם בחוקותי תלכו פי' תלכו הוא יחוד דמ\"ה וב\"ן והלואי<sup data-n=\"3211\">42</sup> אם בחוקותי יהי' יחוד זה והיינו ע\"י בחי' כתר דא\"א דוקא שרש המחוקק הנ\"ל וכמאמרם ז\"ל בחוקה שחקקתי לך כבר כו' וד\"ל.\n<b>וזהו</b> ואת<sup data-n=\"3212\">43</sup> מצוותי תשמרו כו'. כי הנה אמרו ז\"ל בטל<sup data-n=\"3213\">44</sup> רצונך מפני רצונו כו' הרי גילוי אור רצון העליון הפשוט שהוא בחי' כתר דא\"א ונק' רעוא דכל רעוין הוא ע\"י ביטול הרצון למטה וביטול הרצון למטה בנפש האדם הוא בג' מדרגו' שמזכיר בפסוק ואהבת<sup data-n=\"3214\">45</sup> א' בכל לבבך שהוא נפש הבהמיו' שנלקח משם ב\"ן כו' והב' בכל נפשך הוא ניצוץ האלקי' שנלקח מיחוד דז\"א ונוק' שהוא משם מ\"ה כנ\"ל והג' בכל מאדך ופי' מאד הוא בחי' רצון הפשוט בלתי מוגבל בכלי כלל וע\"ז נא' בעליו' כללו' נ\"י הנה<sup data-n=\"3215\">46</sup> ישכיל עבדי ירום ונשא וגבה מאד למעלה גם משם מ\"ה הנק' מחוקק אלא יגיעו לבחי' מאד דהיינו כתר דא\"א ששם חלקת מחוקק ספון וגנוז כו'",[["3207","39","<b>במחוקק במשענותם</b>: חקת כא, יח."],["3208","40","<b>תרי\"ג מצו'. . בתרי\"ג ארחי'</b>: ראה זהר (אדרא רבא) נשא קכט, א. קלו, א."],["3209","41","<b>חוקה שחקקתי לך</b>: ראה תנחומא חוקת ג. במדב\"ר רפי\"ט. וראה רמב\"ם הל' מעילה בסופן."],["3210","*41","<b>חוקה. . פרה אדומה</b>: ראה קהלת רבה עה\"פ מי כהחכם. מד\"ר פ' בא פי\"ט. תצוה ר\"פ לח."],["3211","42","<b>והלואי אם בחוקותי</b>: ראה ע\"ז ה, סע\"א."],["3212","43","<b>ואת מצוותי תשמרו</b>: בחוקותי כו, ג."],["3213","44","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב, מ\"ד."],["3214","45","<b>ואהבת א' בכל לבבך</b>: ואתחנן ו, ה."],["3215","46","<b>הנה ישכיל עבדי</b>: ישעי' נב, יג."]]],[2100990065,"המחבר מ\"ה וב\"ן כנ\"ל וזהו ואת מצוותי תשמרו פי' שמירה זו הוא עד\"מ כלי הנר המחזיק בתוכו השמן והאור וכענין הנ\"ל במאמר רז\"ל כלי מחזיק ברכה כו' שהוא כניסת ריבוי האורו' בריבוי הכלים כו' וכך הוא ענין המצו' כמ\"ש כי<sup data-n=\"3216\">47</sup> נר מצוה כו' משם ב\"ן והאור הוא שם מ\"ה שכנוס בריבוי בתוכו והשימור שיהי' משתמר ריבוי האורו' בריבוי הכלים ויתאחדו תמיד ולא יפרדו הוא ע\"י כח העליון מהם המחבר ומייחד ומקשר אותם כנ\"ל והוא בחי' אור הכתר דא\"א כו' וזהו שאמר אם בחוקותי תלכו שהוא בחי' שרש המחוקק הנ\"ל כשהוא בבחי' כתר דא\"א והיינו גילוי רצון העליון הפשוט הנק' רעוא דכל רעוין שבא ע\"י ביטול רצון בבחי' מאדך למטה כנ\"ל אזי ממילא עי\"ז יהי' שימור למעשה &lt;רג&gt;\nהמצות שיהי' האורו' נשמרי' בכלים והיינו ואת מצוותי תשמרו מפני אותו כח העליון שמאיר מאור הכתר המחבר מ\"ה וב\"ן יחד כנ\"ל וד\"ל.\n<b>ועשיתם</b><sup data-n=\"3217\">48</sup> אותם. פי' ענין העשי' שהזכיר כאן בכללו' ענין המצות הוא מטעם שהמעשה כולה כלולה בחסד דרועא ימינא דוקא וכנראה בחוש שכל המעשה והפעולה אשר יפעול האדם הוא רק בידו הימנית שבה עיקר כח המעשה וגם מה שעושה בשמאלו נמשך מימינו כו' והטעם הוא לפי שהחסד הוא הכולל לכל המדו' כמ\"ש יומם<sup data-n=\"3218\">49</sup> יצוה ה' חסדו וידוע מ\"ש יומם בתוס' מ\"ם יתירה להורו' על בחי' אור החסד שהוא משתתף ומתחבר לבא ולהאיר בכל פרטי המדו' וכידוע שזהו ענין עננא<sup data-n=\"3219\">50</sup> דאהרן דאזיל עם כולהו יומין כו' וכמ\"ש במ\"א ביאור וטעם לדבר לפי שכל פרט מן המדה גם שהיא מבחי' גבורו' וכיוצא בהכרח לה שתתחבר עם מדת החסד אחר שהיא בחי' השפעה וכל השפעה בהכרח באה ע\"י אור החסד כו' וע\"כ גם כל מעשה בפרט בהכרח שיבא בה הכח והעוז מן היד הימנית מטעם זה כו' וד\"ל וע\"כ נא' בצדקה והי'<sup data-n=\"3220\">51</sup> מעשה הצדקה מפני שהחסד והצדקה נק' בשם מעשה ע\"ש שהוא הנותן כח לכל העשיות הפרטיות המסתעפו' כו' ולכך שקולה<sup data-n=\"3221\">52</sup> מצות צדקה כנגד כל המצות מטעם זה וד\"ל.\n<b>ויובן</b> ביאור זה עפ\"י הידוע בכתבי האריז\"ל דבכללו' ההשתלשלו' הכתר הוא בבחי' אצי' כי פי' האצי'<sup data-n=\"3222\">53</sup> לשון אצלו ג\"כ והוא ענין אצל וסמוך לפי",[["3216","47","<b>כי נר מצוה</b>: משלי ו, כג."],["3217","48","<b>ועשיתם אותם</b>: בחוקותי כו, ג."],["3218","49","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט."],["3219","50","<b>עננא דאהרן דאזיל עם כולהו יומין</b>: ראה זהר אמור קג, א-ב. בלק קצא, ב. וראה זהר בראשית מו, א: יומא קדמאה אזיל עם כולהו. עץ חיים שער (כה) דרושי הצלם דרוש ב כלל ז ושער מאמרי רשב\"י יתרו סח, ב־ עטרת ראש דרוש לש\"ת מז, ב: יומם. . דאזיל (וראה ע\"ח שם סוף כלל ח). פרי עץ חיים שער (כח) הסוכות פ\"א־ סידור כאן רלז, ג־ שחרית נב, ד־ לקו\"ת האזינו עו, ב: יומא דאזיל. שער מאמרי רשב\"י תרומה קלט, א־ אמור קג, ב: יומא דכליל. לקו\"ש י\"ט כסלו ח\"ה ע' 174 בהערה. וראה באור החמה לזהר אמור קג, ב־ רמ\"ז לזהר ויחי רמז, א־ מקדש מלך וארא לא, א: יומא דכליל. ניצוצי אורות לזהר וארא שם: יומא דאזיל."],["3220","51","<b>והי' מעשה הצדקה</b>: ישעי' לב, יז."],["3221","52","<b>שקולה מצות צדקה כנגד כל המצות</b>: ב\"ב ט, א."],["3222","53","<b>האצי' לשון אצלו. . וסמוך</b>: פרדס שער אבי\"ע בתחלתו."]]],[2100990066,"שהכתר<sup data-n=\"3223\">54</sup> הוא בחי' ממוצע כו' והחכמה הוא בבחי' בריא' כמ\"ש בראשית<sup data-n=\"3224\">55</sup> ברא כו' והבינה ביצי' והמדו' בעשי' וראיה לשניהם דביצירת האדם כתיב ויצר<sup data-n=\"3225\">56</sup> ה' אלקי' שהוא אור אימא כו' ובז\"א דאצי' נא' ששת<sup data-n=\"3226\">57</sup> ימים עשה הוי' כו' וידוע שהן ו\"ק דז\"א ונא' בו לשון עשי' הרי מבואר שהעשי' עכ\"פ במדו' דז\"א והיינו לפי שכללו' המדו' מקבלי' מעננא דאהרן כו' והוא יד הימין שבה כח המעשה כו' וכנ\"ל וע\"כ כל עיקר ענין המדו' המה רק בבחי' עשי' כנרא' בחוש שכל השפעה למקבל בא מן המדו' כמו התפעלו' הרחמי' והחסד שאין זה אלא כשיש מקבל דוקא משא\"כ חו\"ב מובדלי' הם וכמ\"ש<sup data-n=\"3227\">58</sup> במ\"א בביאור המאמר בזוהר קדש מלה בגרמי' כו' וד\"ל וזהו ועשיתם אותם כי להיו' ריבוי המשכו' האורו' בכלים הוא ע\"י אור החסד מקור כל העשיו' כנ\"ל וד\"ל.\n<b>ונתתי</b><sup data-n=\"3228\">59</sup> גשמיכם בעתם כו'. הנה אחר שאמר ועשיתם אותם בבחי' המעשה הנ\"ל בריבוי אורו' דמ\"ה ליכנס בכלים כו' אמר מהיכן יהי' סיבה לזה המעשה ונתתי גשמיכם כו' דהנה הגשמי' יורדי' מגבוה לנמוך והמה המגדלי' כו' כנ\"ל וכן<sup data-n=\"3229\">60</sup> יהי' דברי אשר יצא מפי כו' דהיינו קול דתורה כי אע\"פ שיחוד מ\"ה וב\"ן נעשה למטה ולמעלה ע\"י מצוותי וחוקותי הנ\"ל אבל כדי שיהי' התעוררו' לזה היחוד ולהגדילו בתמידו' הוא ע\"י קול דתורה כמ\"ש בגשמי' והרוה<sup data-n=\"3230\">61</sup> את הארץ והולידה והצמיחה כו' שהוא הנותן כח ליחוד זה מלמטה כו' וזהו בעתם בעת יחוד דמ\"ה וב\"ן ירד הגשם ליתן להם כח להתייחד כו' והיינו שאמרו גדול<sup data-n=\"3231\">62</sup> תלמוד שמביא לידי מעשה פי' שמביא אור &lt;רד&gt;\nשם מ\"ה לבא ולהיות בבחי' המעשה הנ\"ל דהיינו בריבוי אורו' בריבוי הכלים כו' וד\"ל.\n<b>ונתנה</b><sup data-n=\"3232\">63</sup> הארץ יבולה ועץ השדה יתן פריו, הנה פי' ונתנה הארץ הוא העלא' מ\"ן ממעשה המצו' משם ב\"ן ויבולה הוא ברורי' דרפ\"ח שבה כו' וכנ\"ל ומה שאמר ועץ השדה כו' הוא שם מ\"ה ולכאורה מיותר זה הפסוק שכבר אמר ביחוד מ\"ה וב\"ן במ\"ש ואת מצוותי תשמרו וגם הלא יש להבין בזה מהו ההפרש בין הגשם שהוא ג\"כ הורדת אור שם מ\"ה לעץ השדה שיתן פריו שהוא ג\"כ משם מ\"ה כו'.\n<b>אך</b> הענין יובן בהקדים את הידוע דיש ב\"פ אתעדל\"ע הא' אתעדל\"ע שבאה ע\"י אתעדל\"ת והב' אתעדל\"ע שלפני אתעדל\"ת ולכאורה אינו מובן מהו ההפרש ביניהם אחר ששניהם אתערותא דלעילא הוא כו' אלא שרש הענין הוא דלפני",[["3223","54","<b>שהכתר הוא בחי' ממוצע</b>: ראה ע\"ח (מב) דרושי אבי\"ע פ\"א. סידור שו, ב."],["3224","55","<b>בראשית ברא</b>: בראשית א, א."],["3225","56","<b>ויצר ה' אלקי'</b>: בראשית ב, יט."],["3226","57","<b>ששת ימים עשה הוי'</b>: יתרו כ, יא."],["3227","58","<b>וכמ\"ש במ\"א בביאור המאמר בזוהר קדש מלה בגרמי'</b>: זהר אמור צד, ב. וראה ביאוה\"ז אמור."],["3228","59","<b>ונתתי גשמיכם בעתם</b>: בחוקותי כו, ד."],["3229","60","<b>וכן יהי' דברי אשר יצא מפי</b>: ישעי' נה, יא."],["3230","61","<b>והרוה את הארץ</b>: שם י."],["3231","62","<b>גדול תלמוד שמביא לידי מעשה</b>: קידושין מ, ב. ב\"ק יז, א."],["3232","63","<b>ונתנה הארץ יבולה</b>: בחוקותי שם."]]],[2100990067,"אתעדל\"ת שצריך לבא אור מלמעלה ליתן כח לתחתונים להעלו' מ\"ן הוא בא ממקום גבוה מאד והיינו מעלמין הסתימין שלפני האצי' והמה ענין הכרוזי' שב\"ק מכרזת שהוא מבחי' י\"ג מדה\"ר כו' כמ\"ש במ\"א וזה האור אינו בא למטה בהתגלות אלא בא למטה בהעלם גדול כו' כמ\"ש במ\"א אבל אתעדל\"ע שנעשה אחר אתעדל\"ת הוא בא למטה בבחי' גילוי אור כי בא ונמשך מעלמין דאתגליין שבבחי' האצי' ונק' מ\"ד דז\"א כידוע וזהו ההפרש בין הגשמי' לעץ השדה שהגשמי' המה באי' מן השמים כמ\"ש כאשר<sup data-n=\"3233\">64</sup> ירד הגשם מן השמים כו' ונק' ירידה לעוצם רוממותו ולעוצם ירידתו למטה להתלבש ולבא בהעלם ליתן כח לארץ להעלו' מ\"ן וכמ\"ש והרוה את הארץ והולידה כו' ועץ השדה הוא בחי' שם מ\"ה ומ\"ד שבא ומאיר לאחר אתעדל\"ת בהעלא' מ\"ן ובא בהתגלו' כו' ולכך נמשל לעץ השדה שהוא צומח בגילוי וזהו ועץ השדה יתן פריו אבל הגשמי' יורדי' מגבוה לנמוך לעשו' אתעדל\"ת למטה הנה הוא בא מעלמין סתימין וגם מתלבש בהעלם כנ\"ל ומה שאמרו גדול תלמוד שמביא לידי מעשה הכונה שמביא וגורם שיבא המעשה מן ההעלם לגילוי באתעדל\"ת כענין והרוה את הארץ ואח\"כ והולידה והצמיחה וע\"כ הקדים לומר ונתתי גשמיכם ואח\"כ ונתנה הארץ יבולה ועץ השדה כי המשכ' גשמי' צריך לבא תחלה והוא בא מעלמין הסתימין ולכך אמר ונתתי אני בעצמי הוא הנותן כו' וד\"ל.",[["3233","64","<b>כאשר ירד הגשם מן השמים</b>: ישעי' נה, י."]]],[2100990068,"<h3>משה ידבר</h3>\n<b>בעזר\"ה חג השבועות</b>\n<b>משה</b><sup data-n=\"3234\">1</sup> ידבר והאלקים יעננו בקול<sup data-n=\"3235\">*1</sup>, וארז\"ל בקולו<sup data-n=\"3236\">2</sup> של משה. והנה מה שיש לדקדק בפסוק זה רבות הנה הא' מה שלא ביאר בכתוב מה הן הדברים שמשה ידבר והאלקים יעננו דעשרת הדברות הי' משה מדבר דבר ה' לישראל וכמ\"ש אנכי<sup data-n=\"3237\">3</sup> עומד בין ה' וביניכם להגיד כו' ולא נאמר בענין זה שמשה יהי' המדבר והאלקים יענהו ואם ב' דברו' הראשונו' אנכי<sup data-n=\"3238\">*3</sup> ולא יהי' לך &lt;רה&gt;\nלא משה אמרם אלא מפי הגבורה שמענום וא\"כ על איזה דבר הוא אומר שמשה ידבר והאלקי' ענהו, ועוד לשון ידבר ואלקי' יעננו לשון עתיד הוא ולשון הווה הוא דמשמע שמשה ידבר תמיד ואלקי' יעננו כו' והל\"ל משה דיבר והאלקי' ענהו כו'. אך הנה ארז\"ל בחג זה דהיום",[["3234","1","<b>משה ידבר</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (נב, ב).\nהנחת המהרי\"ל נדפס בתו\"א יתרו סז, ד. וראה בהנסמן במ\"מ לשם. מאמר זה באריכות נדפס בתורת חיים [בהוצאת קה\"ת — תשס\"ג] יתרו רנז, א.\nמאמר זה עם הגהות כ\"ק אדמו\"ר הצ\"צ נדפס באוה\"ת יתרו ע' תתמג. ובעמוד תתלג נדפס הג\"ה על נוסח התו\"א.\nהד\"ה ”מראיהם ומעשיהם\" הנדפס לקמן ע' תסד הוא המשך לד\"ה זה."],["3235","*1","<b>משה ידבר והאלקים יעננו בקול</b>: יתרו יט, יט."],["3236","2","<b>בקולו של משה</b>: ברכות מה, א."],["3237","3","<b>אנכי עומד בין ה' וביניכם</b>: ואתחנן ד, ה."],["3238","*3","<b>אנכי ולא יהי' לך. . מפי הגבורה שמענום</b>: מכות כד, רע\"א. ראה מו\"נ ח\"ב פל\"ג. תניא פ\"כ."]]],[2100990069,"גורם וכמו שאמר רב יוסף אי<sup data-n=\"3239\">4</sup> לאו האי יומא דקא גרים כמה יוסף איכא בשוקא. ולהבין למה האי יומא דוקא הוא דקא גרים הלא מעלת התורה מצד עצמה היא ולמה לו לתלות בהאי יומא.\n<b>אך</b> הענין הוא דיש להבין כל עיקר ענין מתן תורה מה חידוש היה בזה והלא כבר קיים<sup data-n=\"3240\">5</sup> אברהם אע\"ה כל התורה עד שלא ניתנה ואפי' עירוב תבשילין וכמ\"ש וישמור<sup data-n=\"3241\">6</sup> משמרתי מצוותי חוקותי ותורתי ובודאי לימד את התורה גם לבנו<sup data-n=\"3242\">7</sup> יצחק ויצחק למדה ליעקב ומה חידוש הי' בנתינתה לבנ\"י ע\"י משה כו'. אך הנה נודע בזוהר דרמ\"ח<sup data-n=\"3243\">8</sup> מ\"ע אינון רמ\"ח איברי' דמלכא פי' ענין איברי' והלא לכאורה אינו מובן דהא אין<sup data-n=\"3244\">9</sup> לו גוף כו' אך יובן עפ\"י מ\"ש בזוהר<sup data-n=\"3245\">10</sup> דכל אורו' האצילו' בי' ספירין דקרא לון י' תיקונין כו' אינו אלא לאתקנא רזא דשמיה כו' כי ע\"ס דאצי' אינם נמשכים רק מבחי' שמות המאציל ובכלל הן הנה ז'<sup data-n=\"3246\">11</sup> שמות שאינן נמחקים הידועים והם מלובשים בז' מדותיו ית' כמ\"ש לך<sup data-n=\"3247\">12</sup> ה' הגדולה והגבורה כו' עד לך ה' הממלכה כו' שהרי באמת מצד עצמו' אור המאציל הרי נק' אור פשוט בתכלית וכמאמר אנת<sup data-n=\"3248\">13</sup> הוא חד ולא בחושבן כו' אנת חכים ולא בחכמ' ידיע' מבין ולא בבינה ידיע' כו' עד לאו דאית לך צדק ידיע' דאיהו דין כו' ולאו מכל אינון מדות כלל.\n<b>וביאור</b> הדברים הללו כך הוא כי אור החכמה שנאצל מן המאציל עד שנקרא בשם חכים אינו אלא כדי שיהי' מקור ושרש לשרש עד שיהי' נמצא מציא' החכמה למטה בנבראי' להשכיל כל מושכל אבל לגבי עצמו' המאציל הרי הוא למעלה מערך מהות החכמה ואע\"פ שמאציל החכמה חכמתו העצמית אינה בחי' חכמ' ידיעא כלל כחכמה זו שנאצל כמו שמסיים ולאו מכל אינון מדות כלל כו' כי חכמה זו שנאצל כבר היא מקור ושרש לחכמ' דבי\"ע אבל עצמו' אור א\"ס פשוט הוא ואין שייך בו לומר חכים בחכמה ידיעא אלא רק בשביל ההשפעה להיו' חכמה למטה צמצם א\"ע להיו' נק' חכים בבחי' אצי' והצמצום הזה הוא בא ע\"י אותיו' דשם<sup data-n=\"3249\">14</sup> הוי' בניקוד פת\"ח כידוע וכן במחשבה שנמשך מן השכל נא' בו כי<sup data-n=\"3250\">15</sup> לא מחשבותי מחשבותיכם כי כמו הוא חכים ולא בחכמ' ידיע' כך מחשבותיו הם מובדל מערך",[["3239","4","<b>אי לאו האי יומא</b>: פסחים סח, ב."],["3240","5","<b>קיים אברהם אע\"ה כל התורה</b>: ראה יומא כח, ב. לקו\"ש חל\"ה ע' 107 ואילך."],["3241","6","<b>וישמור משמרתי</b>: תולדות כו, ה."],["3242","7","<b>לבנו יצחק ויצחק למדה ליעקב</b>: ראה תנחומא ויגש יא. שמו\"ר פ\"א, א. רמב\"ם הל' ע\"ז וחקותיהם ספ\"א."],["3243","8","<b>דרמ\"ח מ\"ע אינון רמ\"ח איברי' דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["3244","9","<b>אין לו גוף</b>: ע\"פ פיוט יגדל. פיה\"מ להרמב\"ם סנהדרין פ\"י היסוד הג'."],["3245","10","<b>בזוהר. . בי' ספירין. . י' תיקונין</b>: ראה ת\"ז בהקדמה (יז, א)."],["3246","11","<b>ז' שמות שאינן נמחקים</b>: ראה רמב\"ם הל' יסוה\"ת פ\"י, ה\"ב."],["3247","12","<b>לך ה' הגדולה והגבורה</b>: דברי הימים-א כט, יא."],["3248","13","<b>אנת הוא חד</b>: ת\"ז בהקדמה (יז, א)."],["3249","14","<b>דשם הוי' בניקוד פתח</b>: ראה פרדס (שער הנקודות) שכ\"ח, פ\"ה. פע\"ח (שער העמידה) ש\"ט, פי\"ט. סידור האריז\"ל ומ\"ח שם. ובאוה\"ת ואתחנן ע' שעט מציין לזהר תולדות קמה, סע\"א."],["3250","15","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."]]]]});
